window.ANSWER_TERMS = {"ATP":{"match":"adenosinetrifosfaat|adenosine trifosfaat|adenosine-trifosfaat|ATP","title":"ATP (adenosinetrifosfaat)","short":"ATP is de energiemunt van de cel: bij afsplitsing van de derde fosfaatgroep komt energie vrij die transport, contractie en biosynthese aandrijft.","definition":"<p><strong>ATP</strong> (adenosinetrifosfaat) bestaat uit adenine, ribose en drie fosfaatgroepen. Hydrolyse van de eindstandige fosfaatbinding (ATP → ADP + P<sub>i</sub>) levert ongeveer 30 kJ/mol — genoeg om ongunstige reacties te koppelen aan een gunstige: spiercontractie, de Na⁺/K⁺-ATPase, en de opbouw van eiwitten, vetten en DNA.</p><p>Het meeste ATP komt uit de <em>oxidatieve fosforylering</em> in het mitochondrion: de elektronentransportketen pompt protonen naar de intermembraanruimte, en ATP-synthase laat die protonengradiënt terugstromen en maakt daarmee ATP (chemiosmose). Glycolyse en de citroenzuurcyclus leveren daarnaast rechtstreeks een kleine hoeveelheid.</p><p>De cel slaat ATP nauwelijks op — de voorraad gaat in seconden — dus productie en verbruik zijn strak gekoppeld: veel ADP versnelt de verbranding, overmaat ATP remt die af.</p>","image_url":"","wiki_titles":["Adenosine triphosphate","ATP synthase"]},"lysosoom":{"title":"Lysosoom","short":"Membraanblaasje vol verterende enzymen dat afvalstoffen en opgenomen materiaal afbreekt.","definition":"<p>Het <b>lysosoom</b> is een blaasje omgeven door één membraan, gevuld met hydrolytische enzymen die bij een lage pH (~4,5) macromoleculen afbreken. Het is de 'maag' van de cel.</p><p>Het verteert materiaal dat via endocytose of fagocytose is opgenomen en ruimt via autofagie versleten celonderdelen op.</p>","image_url":"","wiki_title":"Lysosome","match":"lysosoom|lysosomen"},"peroxisoom":{"title":"Peroxisoom","short":"Klein organel dat vetzuren afbreekt en daarbij waterstofperoxide vormt, dat het met catalase onschadelijk maakt.","definition":"<p>Het <b>peroxisoom</b> is een klein, door één membraan omgeven organel. Het breekt lange vetzuren af (β-oxidatie) en ontgift stoffen, waarbij waterstofperoxide (H₂O₂) ontstaat.</p><p>Het enzym catalase in het peroxisoom zet dit reactieve H₂O₂ meteen om in water en zuurstof.</p>","image_url":"","wiki_title":"Peroxisome","match":"peroxisoom|peroxisomen"},"golgi-complex":{"title":"Golgi-complex","short":"Stapel afgeplatte blaasjes die eiwitten en lipiden uit het ER modificeert, sorteert en verpakt voor transport.","definition":"<p>Het <b>Golgi-complex</b> (Golgi-apparaat) bestaat uit een stapel afgeplatte membraanzakjes. Het ontvangt eiwitten en lipiden vanuit het endoplasmatisch reticulum.</p><p>Hier worden ze verder bewerkt (bijvoorbeeld glycosylering), gesorteerd en in transportblaasjes verpakt richting hun bestemming.</p>","image_url":"","wiki_title":"Golgi apparatus","match":"golgi-complex|golgi complex|golgi-systeem|golgi systeem|golgi-apparaat|golgi apparaat"},"glad endoplasmatisch reticulum":{"title":"Glad endoplasmatisch reticulum","short":"ER zonder ribosomen; maakt lipiden, ontgift stoffen en slaat calcium op.","definition":"<p>Het <b>glad endoplasmatisch reticulum</b> heeft geen ribosomen. Het synthetiseert lipiden en steroïden, ontgift geneesmiddelen (vooral in de lever) en slaat Ca²⁺ op.</p><p>In spiercellen (sarcoplasmatisch reticulum) regelt de calciumopslag de spiercontractie.</p>","image_url":"","wiki_title":"Endoplasmic reticulum","match":"glad endoplasmatisch reticulum|glad ER"},"ribosoom":{"title":"Ribosoom","short":"Moleculaire machine die met behulp van mRNA aminozuren aaneenrijgt tot een eiwit (translatie).","definition":"<p>Het <b>ribosoom</b> is opgebouwd uit ribosomaal RNA en eiwitten. Het leest de codons van het mRNA af en koppelt de bijbehorende aminozuren aan elkaar.</p><p>Ribosomen komen vrij in het cytoplasma voor of gebonden aan het ruw endoplasmatisch reticulum.</p>","image_url":"","wiki_title":"Ribosome","match":"ribosoom|ribosomen"},"actine":{"title":"Actine","short":"Eiwit dat microfilamenten vormt; betrokken bij celvorm, celbeweging en spiercontractie.","definition":"<p><b>Actine</b> is een van de meest voorkomende eiwitten in de cel. Losse moleculen (G-actine) polymeriseren tot dunne draden (F-actine): de microfilamenten van het cytoskelet.</p><p>Actinefilamenten geven de cel vorm, maken beweging en deling mogelijk en vormen samen met myosine het contractiele apparaat van spiercellen.</p>","image_url":"","wiki_title":"Actin","match":"actine|actinefilamenten|actinefilament"},"microtubuli":{"title":"Microtubuli","short":"Holle buisjes van tubuline; het stevigste onderdeel van het cytoskelet, sporen voor transport en de mitosespoel.","definition":"<p><b>Microtubuli</b> zijn holle buisjes opgebouwd uit tubuline-dimeren. Ze zijn dynamisch: ze groeien en krimpen aan hun uiteinden.</p><p>Ze geven de cel structuur, vormen de rails voor de motoreiwitten kinesine en dyneïne, en bouwen tijdens de celdeling de mitosespoel.</p>","image_url":"","wiki_title":"Microtubule","match":"microtubuli|microtubulus"},"tight junctions":{"title":"Tight junction","short":"Verbinding die de membranen van naburige cellen dicht afsluit en zo een lekvrije barrière vormt.","definition":"<p>Een <b>tight junction</b> (zonula occludens) sluit de ruimte tussen twee cellen volledig af, zodat er niets ongecontroleerd tussendoor lekt.</p><p>Zo houdt hij bijvoorbeeld darm- en huidbarrières waterdicht en scheidt hij het apicale van het basolaterale membraandeel.</p>","image_url":"","wiki_title":"Tight junction","match":"tight junctions|tight junction"},"gap junctions":{"title":"Gap junction","short":"Kanaaltjes tussen aangrenzende cellen waardoor ionen en kleine moleculen rechtstreeks kunnen overgaan.","definition":"<p>Een <b>gap junction</b> is een kanaalverbinding (van connexinen) die het cytoplasma van twee cellen rechtstreeks verbindt.</p><p>Ionen en kleine moleculen stromen er direct doorheen, wat cellen elektrisch en metabool koppelt — belangrijk in hart- en gladde spier.</p>","image_url":"","wiki_title":"Gap junction","match":"gap junctions|gap junction"},"endocriene signalering":{"title":"Endocriene signalering","short":"Klieren geven hormonen af aan het bloed, dat ze naar verre doelorganen vervoert.","definition":"<p>Bij <b>endocriene signalering</b> scheiden endocriene klieren hormonen rechtstreeks in de bloedbaan uit.</p><p>Via het bloed bereiken de hormonen doelcellen elders in het lichaam die de bijbehorende receptor dragen. Het effect is trager maar wijdverbreid.</p>","image_url":"","wiki_title":"Endocrine system","match":"endocriene signalering|endocrien|endocriene secretie|endocriene celsignalering"},"glycoproteine":{"title":"Glycoproteïne","short":"Eiwit met aangehechte suikerketens; veel membraan- en secretie-eiwitten zijn geglycosyleerd.","definition":"<p>Een <b>glycoproteïne</b> is een eiwit waaraan tijdens de rijping in ER en Golgi suikerketens zijn gekoppeld (glycosylering).</p><p>Ze zitten veel in de celmembraan en in secreten en spelen een rol bij herkenning, adhesie en bescherming.</p>","image_url":"","wiki_title":"Glycoprotein","match":"glycoproteïne|glycoproteine|glycoproteïnen|glycoproteinen|glycoproteinen"},"cholesterol":{"title":"Cholesterol","short":"Vetachtige stof die de celmembraan stevigheid en de juiste vloeibaarheid geeft en grondstof is voor steroïden.","definition":"<p><b>Cholesterol</b> is een steroïd dat tussen de fosfolipiden van de celmembraan zit en de membraanvloeibaarheid stabiliseert.</p><p>Het is bovendien de grondstof voor steroïdhormonen, vitamine D en galzouten.</p>","image_url":"","wiki_title":"Cholesterol","match":"cholesterol"},"apoptose":{"title":"Apoptose","short":"Geprogrammeerde celdood: een geordend 'zelfmoordprogramma' dat de cel netjes opruimt zonder ontsteking.","definition":"<p><b>Apoptose</b> is gecontroleerde celdood. De cel krimpt, het DNA wordt in stukken geknipt en de cel valt uiteen in nette blaasjes (apoptotic bodies).</p><p>Macrofagen ruimen die op zonder ontstekingsreactie. Het is essentieel voor ontwikkeling en het verwijderen van beschadigde cellen.</p>","image_url":"","wiki_title":"Apoptosis","match":"apoptose"},"necrose":{"title":"Necrose","short":"Ongecontroleerde celdood door schade, waarbij de cel opzwelt, openbarst en een ontstekingsreactie uitlokt.","definition":"<p><b>Necrose</b> is celdood door acute schade (zuurstoftekort, toxinen, trauma). De cel zwelt op en de membraan scheurt.</p><p>De vrijkomende celinhoud lokt een ontstekingsreactie uit — anders dan bij de 'nette' apoptose.</p>","image_url":"","wiki_title":"Necrosis","match":"necrose"},"citraat":{"title":"Citraat","short":"Eerste product van de citroenzuurcyclus, gevormd uit acetyl-CoA en oxaalacetaat.","definition":"<p><b>Citraat</b> (citroenzuur) ontstaat wanneer acetyl-CoA in de citroenzuurcyclus aan oxaalacetaat wordt gekoppeld.</p><p>Het is de eerste stap van de cyclus; de naamgever citroenzuurcyclus verwijst ernaar.</p>","image_url":"","wiki_title":"Citric acid","match":"citraat"},"epidermis":{"title":"Epidermis","short":"De opperhuid: het bovenste, uit meerlagig verhoornend plaveiselepitheel opgebouwde deel van de huid.","definition":"<p>De <b>epidermis</b> (opperhuid) is de buitenste huidlaag, opgebouwd uit meerlagig verhoornend plaveiselepitheel zonder bloedvaten.</p><p>Ze bestaat vooral uit keratinocyten in opeenvolgende lagen (basale → hoornlaag) en levert de beschermende barrière.</p>","image_url":"","wiki_title":"Epidermis","match":"epidermis|de epidermis"},"dermis":{"title":"Dermis","short":"De lederhuid onder de epidermis: bindweefsel met collageen, bloedvaten, zenuwen, klieren en haarfollikels.","definition":"<p>De <b>dermis</b> (lederhuid) ligt onder de epidermis en bestaat uit bindweefsel met collageen en elastine.</p><p>Ze bevat bloedvaten, zenuwuiteinden, zweet- en talgklieren en haarfollikels en geeft de huid stevigheid en elasticiteit. Men onderscheidt een papillaire en een reticulaire dermis.</p>","image_url":"","wiki_title":"Dermis","match":"dermis|de dermis|papillaire dermis|reticulaire dermis"},"subcutis":{"title":"Subcutis","short":"Het onderhuidse vetweefsel dat isoleert, energie opslaat en als stootkussen dient.","definition":"<p>De <b>subcutis</b> (onderhuids bindweefsel, hypodermis) is de diepste laag en bestaat vooral uit vetweefsel.</p><p>Ze isoleert tegen kou, slaat energie op, dempt stoten en verbindt de huid met onderliggende structuren.</p>","image_url":"","wiki_title":"Subcutaneous tissue","match":"subcutis|de subcutis|hypodermis"},"melanocyt":{"title":"Melanocyt","short":"Pigmentcel in het stratum basale die melanine maakt en dit aan omliggende keratinocyten afgeeft.","definition":"<p>De <b>melanocyt</b> ligt in het stratum basale en produceert in melanosomen het pigment melanine.</p><p>Via uitlopers geeft hij melanine af aan naburige keratinocyten, die er hun kern mee tegen UV-schade beschermen. Verschillen in huidskleur berusten op de activiteit, niet het aantal, van melanocyten.</p>","image_url":"","wiki_title":"Melanocyte","match":"melanocyt|melanocyten"},"fibroblast":{"title":"Fibroblast","short":"De belangrijkste bindweefselcel; produceert collageen, elastine en de overige extracellulaire matrix.","definition":"<p>De <b>fibroblast</b> is de meest voorkomende cel in bindweefsel en de dermis. Hij maakt de vezels (collageen, elastine) en de grondsubstantie aan.</p><p>Bij wondgenezing migreren fibroblasten naar de wond, vormen nieuw matrixmateriaal en kunnen als myofibroblast de wond samentrekken.</p>","image_url":"","wiki_title":"Fibroblast","match":"fibroblast|fibroblasten"},"lymfocyt":{"title":"Lymfocyt","short":"Witte bloedcel van de specifieke afweer; omvat de B-cellen (antistoffen) en T-cellen.","definition":"<p>De <b>lymfocyt</b> is de sleutelcel van het adaptieve (specifieke) immuunsysteem. B-lymfocyten maken antistoffen; T-lymfocyten doden geïnfecteerde cellen of sturen de afweer aan.</p><p>Lymfocyten circuleren tussen bloed, lymfe en lymfoïde organen.</p>","image_url":"","wiki_title":"Lymphocyte","match":"lymfocyt|lymfocyten"},"plasmacel":{"title":"Plasmacel","short":"Uit een B-cel gerijpte cel die grote hoeveelheden antistoffen (antilichamen) produceert.","definition":"<p>De <b>plasmacel</b> is een geactiveerde, uitgerijpte B-lymfocyt. Zijn sterk ontwikkelde ruw endoplasmatisch reticulum maakt hem tot een antistoffabriek.</p><p>Hij scheidt grote hoeveelheden specifieke antilichamen af tegen één antigeen.</p>","image_url":"","wiki_title":"Plasma cell","match":"plasmacel|plasmacellen"},"milt":{"title":"Milt","short":"Lymfoïd orgaan dat oude bloedcellen afbreekt en bloedgedragen ziekteverwekkers filtert.","definition":"<p>De <b>milt</b> filtert het bloed: de rode pulpa ruimt versleten erytrocyten op, de witte pulpa herbergt lymfocyten voor de afweer tegen bloedgedragen pathogenen.</p><p>Ook dient de milt als bloedreservoir.</p>","image_url":"","wiki_title":"Spleen","match":"milt"},"meerlagig plaveiselepitheel":{"title":"Meerlagig plaveiselepitheel","short":"Epitheel van meerdere lagen platte cellen; beschermt tegen mechanische belasting (o.a. de opperhuid).","definition":"<p><b>Meerlagig plaveiselepitheel</b> bestaat uit meerdere cellagen met bovenop platte (plaveisel)cellen.</p><p>Het is bestand tegen slijtage en komt voor waar veel mechanische belasting is: epidermis, mondholte, slokdarm. In de huid is het verhoornd.</p>","image_url":"","wiki_title":"Stratified squamous epithelium","match":"meerlagig plaveiselepitheel"},"overgangsepitheel":{"title":"Overgangsepitheel","short":"Rekbaar epitheel (urotheel) dat van vorm verandert bij vullen en legen, o.a. in de blaas.","definition":"<p><b>Overgangsepitheel</b> (urotheel) kan uitrekken en samentrekken: de cellen worden platter als het orgaan zich vult.</p><p>Het bekleedt de urinewegen, zoals de blaas, en is daar ook een waterdichte barrière.</p>","image_url":"","wiki_title":"Transitional epithelium","match":"overgangsepitheel"},"collageen":{"title":"Collageen","short":"Sterkste structuureiwit van het lichaam; hoofdbestanddeel van bindweefsel, dermis, pezen en bot.","definition":"<p><b>Collageen</b> is het meest voorkomende eiwit in het lichaam en vormt sterke, drievoudig gewonden vezels.</p><p>In de dermis geeft het de huid trekvastheid; fibroblasten maken het aan. Voor de aanmaak is vitamine C nodig (hydroxylering van proline).</p>","image_url":"","wiki_title":"Collagen","match":"collageen"},"nodulus":{"title":"Nodulus","short":"Vaste, verheven en voelbare knobbel die dieper in de huid reikt dan een papel (> ~1 cm).","definition":"<p>Een <b>nodulus</b> (nodus, knobbel) is een stevige, verheven laesie die groter is dan een papel en dieper in de dermis of subcutis reikt.</p><p>Voorbeelden zijn een dermatofibroom of sommige huidtumoren.</p>","image_url":"","wiki_title":"Nodule (medicine)","match":"nodulus|nodus|noduli|nodi"},"vesikel":{"title":"Vesikel","short":"Klein, met helder vocht gevuld blaasje in de huid (< ~1 cm).","definition":"<p>Een <b>vesikel</b> (vesicula) is een klein blaasje gevuld met helder vocht, kleiner dan ongeveer 1 cm.</p><p>Vesikels komen voor bij o.a. herpes, waterpokken en acuut eczeem. Een groter blaasje heet een bulla.</p>","image_url":"","wiki_title":"Blister","match":"vesikel|vesikels|vesicula|vesiculae"},"ulcus":{"title":"Ulcus","short":"Diep huiddefect tot in de dermis of dieper, dat met een litteken geneest (een 'zweer').","definition":"<p>Een <b>ulcus</b> (zweer) is een dieper weefselverlies dat tot in de dermis of subcutis reikt.</p><p>Doordat de dermis is aangetast, geneest het met littekenvorming. Een ulcus cruris (open been) is een bekend voorbeeld.</p>","image_url":"","wiki_title":"Ulcer (dermatology)","match":"ulcus|ulcera"},"atrofie":{"title":"Atrofie","short":"Verdunning of afname van weefsel; bij de huid een dunnere, kwetsbaardere epidermis en/of dermis.","definition":"<p><b>Atrofie</b> is het slinken van een weefsel of orgaan doordat de cellen krimpen of in aantal afnemen.</p><p>Huidatrofie (bijv. na langdurig sterk corticosteroïdgebruik of door veroudering) geeft een dunne, doorschijnende, kwetsbare huid.</p>","image_url":"","wiki_title":"Atrophy","match":"atrofie"},"autosomaal dominant":{"title":"Autosomaal dominant","short":"Overervingspatroon waarbij één afwijkend gen (op een niet-geslachtschromosoom) al ziekte geeft.","definition":"<p>Bij <b>autosomaal dominante</b> overerving volstaat één gemuteerd allel op een autosoom om de aandoening tot uiting te laten komen.</p><p>Aangedane ouders geven het gemiddeld aan de helft van hun kinderen door; de aandoening komt in elke generatie voor, ongeacht geslacht.</p>","image_url":"","wiki_title":"Dominance (genetics)","match":"autosomaal dominant"},"multipotent":{"title":"Multipotent","short":"Eigenschap van een stamcel die kan uitgroeien tot een beperkt aantal verwante celtypen.","definition":"<p>Een <b>multipotente</b> stamcel kan zich ontwikkelen tot meerdere, maar verwante celtypen binnen één lijn.</p><p>Een hematopoëtische stamcel bijvoorbeeld levert alle bloedcellen, maar geen huid- of zenuwcellen.</p>","image_url":"","wiki_title":"Cell potency","match":"multipotent"},"pneumonie":{"title":"Pneumonie","short":"Een pneumonie is een infectie van het longweefsel (alveoli), meestal door bacteriën of virussen, met koorts, hoesten en kortademigheid.","definition":"<p>Bij een <strong>pneumonie</strong> (longontsteking) raken de alveoli ontstoken en vullen ze zich met ontstekingsvocht en cellen. Daardoor is minder longoppervlak beschikbaar voor gaswisseling.</p><p>Typische klachten zijn koorts, hoesten (vaak met sputum), kortademigheid en soms pijn bij het ademen. Bij lichamelijk onderzoek kunnen crepitaties of een gedempte percussie optreden; een X-thorax toont een infiltraat. De meest voorkomende verwekker van de buiten het ziekenhuis opgelopen pneumonie is <em>Streptococcus pneumoniae</em>.</p>","image_url":"","wiki_title":"Pneumonia","match":"pneumonie|longontsteking","option_only":true},"escherichia coli":{"title":"Escherichia coli","short":"E. coli is een gramnegatieve staafbacterie die normaal in de darm leeft en de belangrijkste verwekker is van urineweginfecties.","definition":"<p><strong><em>Escherichia coli</em></strong> is een gramnegatieve, facultatief anaerobe staaf uit de familie van de <em>Enterobacteriaceae</em>. Het is een normaal onderdeel van de darmflora.</p><p>Buiten de darm is E. coli de belangrijkste verwekker van urineweginfecties (cystitis, pyelonefritis) en een belangrijke oorzaak van sepsis en neonatale meningitis. Sommige stammen (zoals EHEC en ETEC) veroorzaken diarree; EHEC kan via shigatoxine het hemolytisch-uremisch syndroom veroorzaken.</p>","image_url":"","wiki_title":"Escherichia coli","match":"escherichia coli|e. coli|e.coli","option_only":true},"staphylococcus aureus":{"title":"Staphylococcus aureus","short":"S. aureus is een grampositieve kok in trosjes, coagulasepositief, die huid- en wondinfecties, abcessen en ernstige systemische infecties veroorzaakt.","definition":"<p><strong><em>Staphylococcus aureus</em></strong> is een grampositieve kok die in trosjes groeit en <em>coagulase-positief</em> is (onderscheid met andere stafylokokken). Ongeveer een derde van de mensen draagt hem in de neus.</p><p>Hij veroorzaakt huid- en wekedeleninfecties (impetigo, furunkels, abcessen, wondinfecties), maar ook osteomyelitis, septische artritis, endocarditis en sepsis. Via toxines kan hij voedselvergiftiging en het toxischeshocksyndroom veroorzaken. MRSA is een methicillineresistente variant.</p>","image_url":"","wiki_title":"Staphylococcus aureus","match":"staphylococcus aureus|s. aureus|stafylococcus aureus","option_only":true},"klebsiella pneumoniae":{"title":"Klebsiella pneumoniae","short":"K. pneumoniae is een gramnegatieve staaf met een dik kapsel die urineweginfecties en (ziekenhuis)pneumonie veroorzaakt.","definition":"<p><strong><em>Klebsiella pneumoniae</em></strong> is een gramnegatieve staaf uit de <em>Enterobacteriaceae</em> met een dik polysacharidekapsel, waardoor kolonies slijmerig zijn.</p><p>Hij veroorzaakt urineweginfecties, sepsis en pneumonie, vooral bij ouderen, alcoholisten en patiënten met diabetes of in het ziekenhuis. Klebsiella is berucht om antibioticaresistentie (ESBL- en carbapenemaseproducerende stammen).</p>","image_url":"","wiki_title":"Klebsiella pneumoniae","match":"klebsiella pneumoniae|k. pneumoniae|klebsiella","option_only":true},"pyelonefritis":{"title":"Pyelonefritis","short":"Pyelonefritis is een bacteriële infectie van het nierbekken en de nier, met koorts, flankpijn en vaak klachten van een blaasontsteking.","definition":"<p><strong>Pyelonefritis</strong> is een opstijgende urineweginfectie die de nier en het nierbekken bereikt, meestal door <em>E. coli</em>.</p><p>Kenmerkend zijn koorts, koude rillingen, flankpijn en slagpijn in de nierloge, eventueel met mictieklachten. Het is een gecompliceerde urineweginfectie die behandeld wordt met antibiotica met goede weefselpenetratie (niet nitrofurantoïne).</p>","image_url":"","wiki_title":"Pyelonephritis","match":"pyelonefritis|nierbekkenontsteking","option_only":true},"cystitis":{"title":"Cystitis","short":"Cystitis is een ontsteking van de blaas, meestal door een bacteriële infectie, met pijnlijke en frequente mictie zonder koorts.","definition":"<p><strong>Cystitis</strong> (blaasontsteking) is een infectie van de lage urinewegen, meestal door <em>E. coli</em> vanuit de darmflora. Vrouwen zijn vaker aangedaan door hun korte urethra.</p><p>Klachten: pijn bij het plassen (dysurie), vaak kleine beetjes plassen (frequentie), aandrang en soms hematurie, zonder koorts of flankpijn. Ongecompliceerde cystitis wordt behandeld met bijv. nitrofurantoïne of fosfomycine.</p>","image_url":"","wiki_title":"Cystitis","match":"cystitis|blaasontsteking","option_only":true},"magnesium":{"title":"Magnesium","short":"Magnesium is een belangrijk intracellulair kation, cofactor van ATP-afhankelijke enzymen en nodig voor stabiele zenuw- en spierprikkelbaarheid.","definition":"<p><strong>Magnesium</strong> (Mg<sup>2+</sup>) zit vooral in bot en intracellulair. Het is cofactor van honderden enzymen, met name die met ATP werken, en stabiliseert de membraanpotentiaal.</p><p>Hypomagnesiëmie (o.a. door diuretica, PPI's, alcohol of diarree) geeft spierkrampen, tetanie, ritmestoornissen en kan hypokaliëmie en hypocalciëmie onderhouden (PTH-secretie daalt). Magnesiumsulfaat wordt gebruikt bij (pre-)eclampsie en torsade de pointes.</p>","image_url":"","wiki_title":"Magnesium in biology","match":"magnesium|mg2+|magnesiumsulfaat","option_only":true},"oestrogeen":{"title":"Oestrogeen","short":"Oestrogenen (vooral oestradiol) zijn vrouwelijke geslachtshormonen uit de ovaria die de geslachtskenmerken, cyclus en botdichtheid beïnvloeden.","definition":"<p><strong>Oestrogenen</strong> (oestradiol, oestron, oestriol) zijn steroïdhormonen die vooral door de granulosacellen in de ovariële follikel worden gemaakt, door aromatisering van androgenen. In de zwangerschap maakt de placenta veel oestriol.</p><p>Ze zorgen voor de vrouwelijke secundaire geslachtskenmerken, laten het endometrium prolifereren (folliculaire fase), geven rond de ovulatie positieve terugkoppeling (LH-piek) en beschermen botmassa. Na de menopauze daalt de spiegel, wat o.a. osteoporose bevordert.</p>","image_url":"","wiki_title":"Estrogen","match":"oestrogeen|oestrogenen|oestradiol|estradiol|estrogeen","option_only":true},"roken":{"title":"Roken","short":"Roken is de belangrijkste vermijdbare oorzaak van ziekte en sterfte: het veroorzaakt o.a. longkanker, COPD en hart- en vaatziekten.","definition":"<p>Tabaksrook bevat nicotine (verslavend), koolmonoxide, teer en tientallen kankerverwekkende stoffen. <strong>Roken</strong> beschadigt het luchtwegepitheel en het endotheel en bevordert ontsteking en trombose.</p><p>Het is een hoofdoorzaak van longkanker en andere kankers (o.a. mond, slokdarm, blaas), COPD, atherosclerose (myocardinfarct, CVA, perifeer arterieel vaatlijden) en complicaties in de zwangerschap. Stoppen loont op elke leeftijd.</p>","image_url":"","wiki_title":"Tobacco smoking","match":"roken|tabaksgebruik|tabak","option_only":true},"complement factoren":{"title":"Complement","short":"Het complementsysteem is een cascade van plasma-eiwitten die micro-organismen opsoneert, ontsteking aanjaagt en via het membraanaanvalscomplex cellen lyseert.","definition":"<p>Het <strong>complementsysteem</strong> bestaat uit plasma-eiwitten (C1–C9 en regulatoren) die in een cascade worden geactiveerd via de klassieke (antilichamen), de lectine- en de alternatieve route.</p><p>Belangrijke functies: <em>opsonisatie</em> (C3b), aantrekken van ontstekingscellen en mestcelactivatie (anafylatoxinen C3a en C5a) en lysis van micro-organismen door het <em>membraanaanvalscomplex</em> (C5b–C9). Tekort aan late complementfactoren geeft een verhoogd risico op <em>Neisseria</em>-infecties.</p>","image_url":"","wiki_title":"Complement system","match":"complement factoren|complementfactoren|complement|complementsysteem","option_only":true},"pneumothorax":{"title":"Pneumothorax","short":"Een pneumothorax is lucht in de pleuraholte, waardoor de long (deels) inklapt; acuut kortademig met pijn, bij spanningspneumothorax levensbedreigend.","definition":"<p>Bij een <strong>pneumothorax</strong> komt lucht tussen de pleurabladen, waardoor de negatieve intrapleurale druk verdwijnt en de long door zijn elastische terugslag inklapt.</p><p>Hij kan spontaan ontstaan (primair bij lange, slanke jonge mannen door blebs; secundair bij longziekte zoals COPD) of na trauma. Klachten: plotselinge pijn op de borst en kortademigheid; verminderd ademgeruis en hypersonore percussie. Bij een <em>spanningspneumothorax</em> hoopt lucht zich op als een ventiel, met verschuiving van het mediastinum en circulatoire shock: direct ontlasten.</p>","image_url":"","wiki_title":"Pneumothorax","match":"pneumothorax|klaplong","option_only":true},"x-thorax":{"title":"X-thorax","short":"Een X-thorax is een röntgenfoto van de borstkas; het eerste beeldvormend onderzoek bij verdenking op longafwijkingen, hartfalen of pneumothorax.","definition":"<p>Een <strong>X-thorax</strong> is een röntgenopname van de borstkas, meestal posterieur-anterieur en lateraal. Lucht is zwart, weke delen grijs en bot wit.</p><p>Het is snel, goedkoop en met een lage stralingsdosis, en wordt gebruikt om o.a. pneumonie (infiltraat), pleuravocht, pneumothorax, longtumoren, hartvergroting en tekenen van hartfalen op te sporen. Kleine of subtiele afwijkingen zijn er minder goed op te zien dan op een CT.</p>","image_url":"","wiki_title":"Chest radiograph","match":"x-thorax|thoraxfoto|röntgenfoto van de thorax|x thorax|x-thorax (röntgenfoto)","option_only":true},"echo abdomen":{"title":"Echo abdomen","short":"Een echo abdomen is een echografisch onderzoek van de buikorganen; zonder straling en goed voor galblaas, galwegen, lever, nieren en vrij vocht.","definition":"<p>Bij een <strong>echo abdomen</strong> wordt met geluidsgolven een beeld gemaakt van de buikorganen. Het onderzoek gebruikt geen ioniserende straling, is goedkoop en direct beschikbaar.</p><p>Het is bijzonder geschikt voor het aantonen van galstenen en cholecystitis, verwijde galwegen, leverafwijkingen, nierstuwing (hydronefrose), een abdominaal aorta-aneurysma en vrij vocht. Darmgas en een dikke buikwand beperken het zicht; de kwaliteit hangt af van de onderzoeker.</p>","image_url":"","wiki_title":"Abdominal ultrasonography","match":"echo abdomen|echografie abdomen|echo van de buik|abdominale echografie|echo-abdomen","option_only":true},"hypothalamus":{"title":"Hypothalamus","short":"De hypothalamus is het regelcentrum van de homeostase: hij stuurt hypofyse, autonoom zenuwstelsel, temperatuur, honger, dorst en circadiaan ritme.","definition":"<p>De <strong>hypothalamus</strong> is een klein deel van het diencephalon, onder de thalamus en rond de derde ventrikel. Hij is via het infundibulum verbonden met de hypofyse.</p><p>Hij maakt releasing- en inhibiting-hormonen (o.a. TRH, CRH, GnRH, GHRH, dopamine) die via het portale systeem de voorkwab sturen, en ADH en oxytocine die in de achterkwab worden afgegeven. Daarnaast regelt hij lichaamstemperatuur, honger en verzadiging, dorst, het slaap-waakritme (nucleus suprachiasmaticus) en het autonome zenuwstelsel.</p>","image_url":"","wiki_title":"Hypothalamus","match":"hypothalamus","option_only":true},"ruggenmerg":{"title":"Ruggenmerg","short":"Het ruggenmerg verbindt de hersenen met de rest van het lichaam; het bevat banen in de witte stof en neuronen voor reflexen in de grijze stof.","definition":"<p>Het <strong>ruggenmerg</strong> (medulla spinalis) loopt in het wervelkanaal van het foramen magnum tot ongeveer L1–L2 (conus medullaris), waarna de cauda equina volgt. Het geeft 31 paar spinale zenuwen af.</p><p>In dwarsdoorsnede ligt de vlindervormige <em>grijze stof</em> (voorhoorn: motorneuronen; achterhoorn: sensorische schakeling) binnenin, omgeven door <em>witte stof</em> met opstijgende (bijv. achterstrengen, tractus spinothalamicus) en afdalende banen (tractus corticospinalis).</p>","image_url":"","wiki_title":"Spinal cord","match":"ruggenmerg|medulla spinalis","option_only":true},"spinale ganglia":{"title":"Spinale ganglia","short":"Spinale ganglia liggen in de achterwortels van de spinale zenuwen en bevatten de cellichamen van de sensorische (pseudo-unipolaire) neuronen.","definition":"<p>Een <strong>spinaal ganglion</strong> (dorsaalwortelganglion) is een verdikking van de achterwortel, vlak bij het foramen intervertebrale.</p><p>Het bevat de cellichamen van de <em>primaire sensorische neuronen</em>. Deze zijn pseudo-unipolair: één uitloper splitst in een perifere tak naar de receptor en een centrale tak naar het ruggenmerg. Er liggen geen synapsen in het ganglion. Het varicella-zostervirus kan hier latent blijven.</p>","image_url":"","wiki_title":"Dorsal root ganglion","match":"spinale ganglia|spinaal ganglion|ganglion spinale|dorsale wortelganglia|ganglia spinalia","option_only":true},"maturatie":{"title":"Maturatie","short":"Maturatie is rijping: het proces waarin een cel, weefsel of organisme zijn uiteindelijke, volwassen vorm en functie bereikt.","definition":"<p><strong>Maturatie</strong> betekent rijping. In de embryologie en voortplanting gaat het bijvoorbeeld om de rijping van geslachtscellen (oöcyt- en spermatozoönmaturatie), waarbij de meiose wordt voltooid en de cel bevruchtingsklaar wordt.</p><p>In bredere zin gebruikt men het voor de rijping van organen (bijv. longrijping, rijping van het zenuwstelsel) en van cellen van het immuunsysteem (bijv. T-celmaturatie in de thymus).</p>","image_url":"","wiki_title":"","match":"maturatie|rijping","option_only":true},"hypertensie":{"title":"Hypertensie","short":"Hypertensie is een blijvend verhoogde bloeddruk (≥140/90 mmHg op het spreekuur); een belangrijke risicofactor voor hart- en vaatziekten.","definition":"<p>Bij <strong>hypertensie</strong> is de bloeddruk herhaaldelijk verhoogd: op het spreekuur ≥140/90 mmHg. Meestal is er geen aanwijsbare oorzaak (<em>primaire/essentiële</em> hypertensie); bij een minderheid is er een secundaire oorzaak, zoals nierziekte, nierarteriestenose, hyperaldosteronisme of feochromocytoom.</p><p>Hypertensie geeft meestal geen klachten, maar beschadigt op termijn vaten en organen: linkerventrikelhypertrofie, hartfalen, CVA, nierschade en retinopathie. Behandeling: leefstijl (zout, gewicht, beweging, alcohol) en medicatie (o.a. diuretica, ACE-remmers/ARB's, calciumantagonisten).</p>","image_url":"","wiki_title":"Hypertension","match":"hypertensie|hoge bloeddruk|arteriële hypertensie","option_only":true},"diabetes mellitus":{"title":"Diabetes mellitus","short":"Diabetes mellitus is een chronisch verhoogde bloedglucose door een tekort aan insuline (type 1) of verminderde insulinegevoeligheid met relatief tekort (type 2).","definition":"<p>Bij <strong>diabetes mellitus</strong> is de bloedglucose chronisch te hoog. Bij <em>type 1</em> vernietigt een auto-immuunproces de bètacellen van de pancreas (absoluut insulinetekort, vaak op jonge leeftijd, risico op ketoacidose). Bij <em>type 2</em> is er insulineresistentie (vaak met overgewicht) en een tekortschietende insulineproductie.</p><p>Klachten: dorst, veel plassen, moeheid en gewichtsverlies. Op termijn ontstaan microvasculaire (retinopathie, nefropathie, neuropathie) en macrovasculaire complicaties (hart- en vaatziekten). Diagnose o.a. nuchter glucose ≥7,0 mmol/L of HbA1c ≥48 mmol/mol.</p>","image_url":"","wiki_title":"Diabetes","match":"diabetes mellitus|diabetes|suikerziekte|diabetes mellitus type 2|diabetes mellitus type 1|diabetes mellitus 2","option_only":true},"ulcus pepticum":{"title":"Ulcus pepticum","short":"Een ulcus pepticum is een zweer in maag of duodenum door aantasting door maagzuur, meestal bij H. pylori-infectie of NSAID-gebruik.","definition":"<p>Een <strong>ulcus pepticum</strong> is een defect in de wand van maag (ulcus ventriculi) of duodenum (ulcus duodeni) dat dieper gaat dan de muscularis mucosae. Het ontstaat door een verstoorde balans tussen aanvallende factoren (zuur, pepsine) en beschermende factoren (slijm, bicarbonaat, doorbloeding).</p><p>De belangrijkste oorzaken zijn <em>Helicobacter pylori</em> en <em>NSAID's</em> (inclusief aspirine). Klachten: epigastrische pijn, soms gerelateerd aan maaltijden. Complicaties: bloeding, perforatie en obstructie. Behandeling: protonpompremmer en H. pylori-eradicatie.</p>","image_url":"","wiki_title":"Peptic ulcer disease","match":"ulcus pepticum|maagzweer|ulcus duodeni|ulcus ventriculi|peptisch ulcus","option_only":true},"acute cholecystitis":{"title":"Acute cholecystitis","short":"Acute cholecystitis is een ontsteking van de galblaas, meestal doordat een galsteen de ductus cysticus afsluit; pijn rechtsboven, koorts en een positief teken van Murphy.","definition":"<p>Bij een <strong>acute cholecystitis</strong> blokkeert meestal een galsteen de <em>ductus cysticus</em>. De galblaas zwelt, de wand raakt geïrriteerd en ontstoken, en secundair kan een bacteriële infectie ontstaan.</p><p>Klachten: aanhoudende pijn rechts in de bovenbuik (langer dan een galsteenkoliek), koorts en een positief <em>teken van Murphy</em> (pijn en stokkende inademing bij palpatie onder de ribboog). De echo toont galstenen, een verdikte galblaaswand en vocht rond de galblaas. Behandeling: antibiotica en (vroege) cholecystectomie.</p>","image_url":"","wiki_title":"Cholecystitis","match":"acute cholecystitis|cholecystitis|galblaasontsteking","option_only":true},"diarree":{"title":"Diarree","short":"Diarree is het vaker dan normaal (≥3x per dag) produceren van brijige tot waterdunne ontlasting.","definition":"<p><strong>Diarree</strong> betekent een verhoogde frequentie (meestal ≥3 keer per dag) en verminderde consistentie van de ontlasting. Acute diarree (&lt;2 weken) is meestal infectieus (virussen zoals norovirus, bacteriën, parasieten).</p><p>Mechanismen: <em>secretoir</em> (bijv. door toxines zoals choleratoxine), <em>osmotisch</em> (bijv. lactose-intolerantie, laxantia), <em>inflammatoir</em> (bijv. IBD, invasieve bacteriën, met bloed en slijm) en versnelde motiliteit. Het belangrijkste risico is uitdroging en elektrolytverlies.</p>","image_url":"","wiki_title":"Diarrhea","match":"diarree","option_only":true},"anemie":{"title":"Anemie","short":"Anemie is een te laag hemoglobinegehalte in het bloed, waardoor het zuurstoftransport vermindert.","definition":"<p>Bij <strong>anemie</strong> is de hemoglobineconcentratie verlaagd (bij volwassenen ongeveer &lt;8,5 mmol/L bij mannen en &lt;7,5 mmol/L bij vrouwen). Klachten: moeheid, kortademigheid bij inspanning, bleekheid en hartkloppingen.</p><p>Indeling op het MCV: <em>microcytair</em> (o.a. ijzergebrek, thalassemie), <em>normocytair</em> (o.a. acuut bloedverlies, chronische ziekte, nierfalen) en <em>macrocytair</em> (o.a. vitamine B12- of foliumzuurtekort). Daarnaast onderscheidt men verminderde aanmaak van versterkte afbraak (hemolyse) of verlies.</p>","image_url":"","wiki_title":"Anemia","match":"anemie|bloedarmoede","option_only":true},"koorts":{"title":"Koorts","short":"Koorts is een verhoogde lichaamstemperatuur (≥38,0 °C) doordat de hypothalamus het setpoint hoger instelt, meestal als reactie op infectie.","definition":"<p>Bij <strong>koorts</strong> wordt het temperatuursetpoint in de hypothalamus verhoogd. Pyrogenen zoals bacteriële producten en cytokines (IL-1, IL-6, TNF) stimuleren daar de productie van prostaglandine E<sub>2</sub>.</p><p>Het lichaam ervaart de normale temperatuur dan als te koud: vasoconstrictie en rillingen verhogen de temperatuur. Als het setpoint weer daalt, volgen zweten en vasodilatatie. Koortsremmers (paracetamol, NSAID's) remmen de prostaglandinesynthese. Hyperthermie (bijv. hitteberoerte) is iets anders: daar is het setpoint níet verhoogd.</p>","image_url":"","wiki_title":"Fever","match":"koorts|febris|pyrexie|hoge koorts","option_only":true},"lever":{"title":"Lever","short":"De lever is de grootste klier van het lichaam: hij regelt stofwisseling van suikers, vetten en eiwitten, maakt gal en eiwitten (o.a. albumine, stollingsfactoren) en ontgift stoffen.","definition":"<p>De <strong>lever</strong> ligt rechtsboven in de buik en krijgt bloed uit de a. hepatica en (voor ±75%) uit de <em>v. portae</em>, met voedingsstoffen uit de darm.</p><p>Functies: opslag en afgifte van glucose (glycogeen, gluconeogenese), vet- en cholesterolmetabolisme, aanmaak van plasma-eiwitten (albumine, stollingsfactoren), ureumvorming, galproductie, afbraak van bilirubine en ontgifting van geneesmiddelen en alcohol. Functionele eenheden zijn de leverlobjes met hepatocyten rond sinusoïden.</p>","image_url":"","wiki_title":"Liver","match":"lever|hepar","option_only":true},"maag":{"title":"Maag","short":"De maag slaat voedsel tijdelijk op, mengt het met maagzuur en pepsine en geeft het geleidelijk af aan het duodenum.","definition":"<p>De <strong>maag</strong> bestaat uit cardia, fundus, corpus, antrum en pylorus. Het slijmvlies bevat klieren met <em>pariëtale cellen</em> (zoutzuur en intrinsieke factor), <em>hoofdcellen</em> (pepsinogeen), slijmcellen en endocriene cellen (o.a. G-cellen met gastrine in het antrum).</p><p>De maag doodt micro-organismen, start de eiwitvertering en mengt voedsel tot chymus. Intrinsieke factor is nodig voor opname van vitamine B12 in het terminale ileum.</p>","image_url":"","wiki_title":"Stomach","match":"maag|gaster|ventriculus","option_only":true},"galblaas":{"title":"Galblaas","short":"De galblaas slaat gal uit de lever op en dikt die in; na een vetrijke maaltijd trekt hij samen onder invloed van cholecystokinine.","definition":"<p>De <strong>galblaas</strong> ligt aan de onderzijde van de lever en is via de ductus cysticus verbonden met de galwegen. Ze slaat de gal die de lever continu maakt op en concentreert die door water en zout terug te resorberen.</p><p>Na een (vetrijke) maaltijd geeft het duodenum <em>cholecystokinine</em> af: de galblaas trekt samen en de sfincter van Oddi ontspant, zodat gal in het duodenum komt voor de vetvertering. Galstenen kunnen koliek, cholecystitis of een choledocholithiasis geven.</p>","image_url":"","wiki_title":"Gallbladder","match":"galblaas|vesica biliaris|vesica fellea","option_only":true},"de milt":{"title":"Milt","short":"De milt filtert het bloed: hij ruimt oude en beschadigde rode bloedcellen op en vormt een afweerorgaan tegen bacteriën in het bloed.","definition":"<p>De <strong>milt</strong> ligt linksboven in de buik onder het diafragma. Ze bestaat uit <em>rode pulpa</em> (sinusoïden waar verouderde of afwijkende erytrocyten worden afgebroken) en <em>witte pulpa</em> (lymfatisch weefsel met B- en T-cellen rond arteriolen).</p><p>De milt is belangrijk voor de afweer tegen <em>gekapselde bacteriën</em> (pneumokok, meningokok, H. influenzae). Na splenectomie is het risico op een ernstige sepsis daardoor verhoogd; deze patiënten worden gevaccineerd.</p>","image_url":"","wiki_title":"Spleen","match":"de milt|milt|lien|splenomegalie","option_only":true},"appendix":{"title":"Appendix","short":"De appendix is een wormvormig aanhangsel van het caecum met veel lymfatisch weefsel; ontsteking ervan (appendicitis) is een veelvoorkomende acute buik.","definition":"<p>De <strong>appendix vermiformis</strong> is een smal, blind eindigend aanhangsel van het caecum, meestal rechtsonder in de buik. De wand bevat veel lymfoïde follikels.</p><p>Bij <em>appendicitis</em> raakt het lumen afgesloten (bijv. door een fecoliet of lymfoïde hyperplasie), waarna ontsteking en infectie volgen. Typisch begint de pijn rond de navel en verplaatst zich naar rechtsonder (punt van McBurney), met misselijkheid en koorts.</p>","image_url":"","wiki_title":"Appendix (anatomy)","match":"appendix|blindedarm|appendix vermiformis|wormvormig aanhangsel","option_only":true},"colon ascendens":{"title":"Colon ascendens","short":"Het colon ascendens is het opstijgende deel van de dikke darm rechts in de buik, van caecum tot flexura hepatica; het ligt secundair retroperitoneaal.","definition":"<p>Het <strong>colon ascendens</strong> loopt aan de rechterzijde van de buik omhoog van het caecum tot de <em>flexura coli dextra</em> (hepatica) onder de lever, waar het overgaat in het colon transversum.</p><p>Het ligt secundair retroperitoneaal. De bloedvoorziening komt uit de a. mesenterica superior (a. ileocolica en a. colica dextra). In dit deel is de ontlasting nog vloeibaar en wordt veel water en zout teruggeresorbeerd.</p>","image_url":"","wiki_title":"Ascending colon","match":"colon ascendens|opstijgende colon|opstijgend colon","option_only":true},"secundaire follikel":{"title":"Secundaire follikel","short":"Een secundaire follikel is een groeiende ovariële follikel met meerdere lagen granulosacellen, een zona pellucida en theca, die een vochtholte (antrum) gaat vormen.","definition":"<p>In het ovarium rijpen follikels van <em>primordiaal</em> → <em>primair</em> → <strong>secundair</strong> → tertiair (Graafse follikel).</p><p>In een secundaire follikel is de oöcyt omgeven door meerdere lagen granulosacellen en een zona pellucida, met daaromheen een theca interna en externa. Tussen de granulosacellen ontstaan vochtholtes die samenvloeien tot een <em>antrum</em>. Thecacellen maken onder invloed van LH androgenen, die granulosacellen onder invloed van FSH omzetten in oestrogeen.</p>","image_url":"","wiki_title":"Ovarian follicle","match":"secundaire follikel|secundaire follikels|antrale follikel","option_only":true},"spermatogonia":{"title":"Spermatogonia","short":"Spermatogonia zijn de stamcellen van de spermatogenese aan de basaalmembraan van de tubuli seminiferi; ze delen mitotisch.","definition":"<p><strong>Spermatogonia</strong> zijn diploïde kiemcellen die tegen de basaalmembraan van de tubuli seminiferi liggen, buiten de bloed-testisbarrière van de Sertolicellen.</p><p>Vanaf de puberteit delen ze <em>mitotisch</em>: een deel blijft stamcel, een deel wordt primaire spermatocyt. Die doorloopt de meiose (secundaire spermatocyt → spermatide), waarna spermiogenese het spermatozoön vormt. Het hele proces duurt ±64–74 dagen.</p>","image_url":"","wiki_title":"Spermatogonium","match":"spermatogonia|spermatogonium|spermatogoniën","option_only":true},"ao-antagonisme":{"title":"AB0-antagonisme","short":"Bij AB0-antagonisme breken maternale anti-A- of anti-B-antistoffen (IgG) de rode bloedcellen van het kind af; meestal bij een moeder met bloedgroep O en een kind met A of B.","definition":"<p>Bij <strong>AB0-antagonisme</strong> heeft de moeder meestal <em>bloedgroep O</em> en het kind bloedgroep A of B. Mensen met bloedgroep O maken van nature anti-A- en anti-B-antistoffen, waarvan een deel IgG is en de placenta kan passeren.</p><p>Die antistoffen veroorzaken hemolyse van de foetale erytrocyten, wat bij de pasgeborene leidt tot een ongeconjugeerde hyperbilirubinemie. Het verloopt meestal milder dan rhesusantagonisme en kan ook bij een eerste zwangerschap voorkomen. De directe antiglobulinetest (Coombs) bij het kind is vaak (zwak) positief.</p>","image_url":"","wiki_title":"Hemolytic disease of the newborn (ABO)","match":"ao-antagonisme|ab0-antagonisme|abo-antagonisme|ab0-incompatibiliteit|bloedgroepantagonisme","option_only":true},"nier":{"title":"Nier","short":"De nieren filteren het bloed en regelen water-, zout- en zuur-base-evenwicht en bloeddruk; ook maken ze hormonen (renine, EPO, actief vitamine D).","definition":"<p>De <strong>nieren</strong> liggen retroperitoneaal aan weerszijden van de wervelkolom. De functionele eenheid is het <em>nefron</em>: glomerulus, proximale tubulus, lis van Henle, distale tubulus en verzamelbuis. Samen filteren de nieren ongeveer 180 liter per dag, waarvan meer dan 99% wordt teruggeresorbeerd.</p><p>Ze scheiden afvalstoffen (ureum, creatinine) en geneesmiddelen uit, regelen het volume en de samenstelling van de lichaamsvloeistoffen en de pH, en maken <em>renine</em> (bloeddruk), <em>erytropoëtine</em> (aanmaak van rode bloedcellen) en <em>calcitriol</em> (actief vitamine D).</p>","image_url":"","wiki_title":"Kidney","match":"nier|nieren|ren","option_only":true},"blaas":{"title":"Blaas (vesica urinaria)","short":"De blaas is een gespierd hol orgaan in het kleine bekken dat urine verzamelt en bij mictie leegt.","definition":"<p>De <strong>blaas</strong> ligt achter de symfyse. De wand bestaat uit urotheel (overgangsepitheel), dat zich aanpast aan de vullingsgraad, en de m. detrusor (gladde spier). Het driehoekige trigonum ligt tussen de twee ureteruitmondingen en de urethra-opening. Vulling en lediging worden gestuurd door autonome en willekeurige zenuwen (parasympathisch: contractie van de detrusor).</p>","image_url":"","wiki_title":"Urinary bladder","match":"blaas|urineblaas|vesica urinaria","option_only":true},"uterus":{"title":"Uterus (baarmoeder)","short":"De uterus is het peervormige, gespierde orgaan in het kleine bekken waarin het embryo innestelt en de foetus groeit.","definition":"<p>De <strong>uterus</strong> bestaat uit fundus, corpus en cervix. De wand heeft drie lagen: endometrium (slijmvlies dat cyclisch opbouwt en afstoot), myometrium (dikke laag gladde spier) en perimetrium. De uterus ligt meestal geanteverteerd en geanteflecteerd en wordt doorbloed door de a. uterina.</p>","image_url":"","wiki_title":"Uterus","match":"uterus|baarmoeder","option_only":true},"ovarium":{"title":"Ovarium (eierstok)","short":"Het ovarium is de vrouwelijke geslachtsklier die eicellen laat rijpen en oestrogenen en progesteron maakt.","definition":"<p>Het <strong>ovarium</strong> ligt aan weerszijden van de uterus in de fossa ovarica. In de cortex liggen follikels in verschillende stadia van rijping; na de ovulatie wordt de follikel een corpus luteum dat progesteron maakt. Het ovarium wordt doorbloed door de a. ovarica uit de aorta en is via het lig. suspensorium ovarii en het lig. ovarii proprium opgehangen.</p>","image_url":"","wiki_title":"Ovary","match":"ovarium|eierstok|ovaria","option_only":true},"gonaden":{"title":"Gonaden","short":"Gonaden zijn de geslachtsklieren: testes bij de man en ovaria bij de vrouw; ze maken geslachtscellen en geslachtshormonen.","definition":"<p>De <strong>gonaden</strong> ontstaan embryonaal uit de genitale richel van het intermediair mesoderm, waarin oerkiemcellen vanuit de dooierzakwand migreren. Onder invloed van het SRY-gen ontwikkelt de indifferente gonade zich tot testis; zonder SRY ontstaat een ovarium. Ze worden aangestuurd door LH en FSH uit de hypofyse.</p>","image_url":"","wiki_title":"Gonad","match":"gonaden|gonade|geslachtsklieren","option_only":true},"calcium":{"title":"Calcium","short":"Calcium is nodig voor botten, spiercontractie, zenuwgeleiding en stolling; de bloedspiegel wordt geregeld door PTH, vitamine D en calcitonine.","definition":"<p>Het meeste <strong>calcium</strong> zit in botten als hydroxyapatiet. In het bloed is ongeveer de helft eiwitgebonden (vooral aan albumine) en de rest vrij geïoniseerd, de biologisch actieve vorm. Calcium is tweede boodschapper in cellen en essentieel voor spiercontractie, neurotransmitterafgifte en stolling. Afwijkingen geven bijv. tetanie (hypocalciëmie) of dorst, obstipatie en verwardheid (hypercalciëmie).</p>","image_url":"","wiki_title":"Calcium in biology","match":"calcium|ca2+|calciumion","option_only":true},"ijzer":{"title":"IJzer","short":"IJzer is nodig voor hemoglobine, myoglobine en enzymen; het lichaam regelt de ijzervoorraad vooral via de opname in de darm.","definition":"<p><strong>IJzer</strong> wordt vooral in het duodenum opgenomen, als heemijzer of als Fe²⁺. In het bloed wordt het vervoerd door transferrine en opgeslagen als ferritine. Het hormoon hepcidine uit de lever remt de opname en afgifte. Het lichaam heeft geen actieve uitscheidingsroute, dus verlies gaat vooral via bloedverlies.</p>","image_url":"","wiki_title":"Iron in biology","match":"ijzer|fe|ijzersuppletie","option_only":true},"albumine":{"title":"Albumine","short":"Albumine is het meest voorkomende plasma-eiwit; het houdt vocht in de bloedbaan (colloïd-osmotische druk) en vervoert veel stoffen.","definition":"<p><strong>Albumine</strong> wordt in de lever gemaakt. Het zorgt voor het grootste deel van de colloïd-osmotische druk en bindt o.a. calcium, bilirubine, vrije vetzuren, hormonen en geneesmiddelen. Een laag albumine komt voor bij leverziekte, nefrotisch syndroom, ondervoeding en ontsteking (negatief acutefase-eiwit) en kan oedeem geven.</p>","image_url":"","wiki_title":"Human serum albumin","match":"albumine|serumalbumine","option_only":true},"cortisol":{"title":"Cortisol","short":"Cortisol is het belangrijkste glucocorticoïd uit de bijnierschors; het is een stresshormoon met effecten op stofwisseling en afweer.","definition":"<p><strong>Cortisol</strong> wordt gemaakt in de zona fasciculata onder invloed van ACTH, met een dagritme (hoog in de ochtend). Het verhoogt de bloedglucose (gluconeogenese), breekt eiwitten af, remt ontsteking en afweer en ondersteunt de bloeddruk. Overmaat geeft het syndroom van Cushing, tekort bijnierinsufficiëntie (ziekte van Addison).</p>","image_url":"","wiki_title":"Cortisol","match":"cortisol|hydrocortison","option_only":true},"progesteron":{"title":"Progesteron","short":"Progesteron is een steroïdhormoon uit het corpus luteum en de placenta dat het endometrium voorbereidt op en de zwangerschap ondersteunt.","definition":"<p><strong>Progesteron</strong> wordt in de luteale fase door het corpus luteum gemaakt en in de zwangerschap vanaf ongeveer 10 weken door de placenta. Het zet het endometrium om naar de secretoire fase, ontspant het myometrium, maakt cervixslijm taai en verhoogt de basale lichaamstemperatuur. Daling van progesteron aan het eind van de cyclus leidt tot menstruatie.</p>","image_url":"","wiki_title":"Progesterone","match":"progesteron|progestageen","option_only":true},"adrenaline":{"title":"Adrenaline (epinefrine)","short":"Adrenaline is een catecholamine uit het bijniermerg dat de ‘fight-or-flight’-reactie aanstuurt via alfa- en bèta-receptoren.","definition":"<p><strong>Adrenaline</strong> wordt door chromaffiene cellen van het bijniermerg afgegeven bij stress. Het verhoogt hartfrequentie en contractiekracht (β1), verwijdt de bronchi (β2), vernauwt vaten in huid en darm (α1) en verhoogt de bloedglucose. Als geneesmiddel is het het middel bij anafylaxie (intramusculair) en wordt het gebruikt bij reanimatie.</p>","image_url":"","wiki_title":"Adrenaline","match":"adrenaline|epinefrine|epinephrine","option_only":true},"femur":{"title":"Femur (dijbeen)","short":"De femur is het langste en sterkste bot van het lichaam, tussen heup en knie.","definition":"<p>De <strong>femur</strong> heeft proximaal de femurkop, het collum en de trochanter major en minor, en distaal de condylus medialis en lateralis. Het collum maakt een hoek met de schacht (collodiafysaire hoek). Collumfracturen komen veel voor bij ouderen met osteoporose; de bloedvoorziening van de kop kan daarbij in gevaar komen.</p>","image_url":"","wiki_title":"Femur","match":"femur|dijbeen","option_only":true},"os sacrum":{"title":"Os sacrum (heiligbeen)","short":"Het os sacrum is het driehoekige bot uit vijf vergroeide sacrale wervels dat de achterwand van het bekken vormt.","definition":"<p>Het <strong>os sacrum</strong> articuleert boven met de vijfde lendenwervel, aan beide zijden met de ossa ilia (sacro-iliacale gewrichten) en onder met het stuitbeen. Door de foramina sacralia treden de sacrale zenuwen uit. Het promontorium is een belangrijk oriëntatiepunt in de verloskunde.</p>","image_url":"","wiki_title":"Sacrum","match":"os sacrum|heiligbeen|sacrum","option_only":true},"aorta":{"title":"Aorta","short":"De aorta is de grootste slagader; ze voert zuurstofrijk bloed van de linkerventrikel naar de lichaamscirculatie.","definition":"<p>De <strong>aorta</strong> bestaat uit de aorta ascendens (met de kransslagaders), de arcus aortae (met truncus brachiocephalicus, a. carotis communis sinistra en a. subclavia sinistra), de aorta thoracica descendens en de aorta abdominalis, die ter hoogte van L4 splitst. De wand is rijk aan elastische lamellen, wat zorgt voor de windketelfunctie.</p>","image_url":"","wiki_title":"Aorta","match":"aorta|lichaamsslagader","option_only":true},"streptococcus pyogenes":{"title":"Streptococcus pyogenes (groep A-streptokok)","short":"Groep A-streptokok: grampositieve, bètahemolytische kok in ketens die o.a. keelontsteking, impetigo, erysipelas en roodvonk veroorzaakt.","definition":"<p><strong><em>Streptococcus pyogenes</em></strong> koloniseert keel en huid. Het M-eiwit beschermt tegen fagocytose; pyrogene exotoxinen veroorzaken roodvonk en het toxischeshocksyndroom. Invasieve infecties zijn o.a. cellulitis en necrotiserende fasciitis. Na een infectie kunnen immunologische complicaties optreden: acuut reuma en poststreptokokken-glomerulonefritis. Penicilline is eerste keus.</p>","image_url":"","wiki_title":"Streptococcus pyogenes","match":"streptococcus pyogenes|s. pyogenes|groep a-streptokok|groep a streptokok|groep-a-streptokokken","option_only":true},"herpes genitalis":{"title":"Herpes genitalis","short":"Herpes genitalis is een seksueel overdraagbare infectie met HSV-2 of HSV-1, met pijnlijke blaasjes en zweertjes in het genitale gebied.","definition":"<p>Bij <strong>herpes genitalis</strong> ontstaan na besmetting pijnlijke groepjes blaasjes die openbreken tot oppervlakkige ulcera, vaak met koorts, pijn bij het plassen en vergrote lieslymfeklieren. Het virus blijft latent in de sacrale ganglia en kan recidiveren. Een primaire infectie rond de bevalling geeft een groot risico op neonatale herpes.</p>","image_url":"","wiki_title":"Genital herpes","match":"herpes genitalis|genitale herpes","option_only":true},"metronidazol":{"title":"Metronidazol","short":"Metronidazol is een antibioticum tegen anaerobe bacteriën en bepaalde protozoën.","definition":"<p><strong>Metronidazol</strong> wordt in anaerobe micro-organismen omgezet in reactieve deeltjes die het DNA beschadigen. Het werkt tegen anaerobe bacteriën (o.a. <em>Bacteroides</em>, <em>Clostridioides</em>) en protozoën zoals <em>Giardia</em>, <em>Trichomonas</em> en <em>Entamoeba</em>. Bijwerkingen: metaalsmaak, misselijkheid en een disulfiramachtige reactie met alcohol.</p>","image_url":"","wiki_title":"Metronidazole","match":"metronidazol|flagyl","option_only":true},"ecg":{"title":"ECG (elektrocardiogram)","short":"Een ECG registreert de elektrische activiteit van het hart via elektroden op de huid.","definition":"<p>Een standaard <strong>12-afleidingen-ECG</strong> laat de P-top (boezemdepolarisatie), het QRS-complex (kamerdepolarisatie) en de T-top (repolarisatie) zien. Het wordt gebruikt om ritmestoornissen, geleidingsstoornissen, ischemie en infarct, hypertrofie en elektrolytstoornissen (bijv. hyperkaliëmie) op te sporen.</p>","image_url":"","wiki_title":"Electrocardiography","match":"ecg|elektrocardiogram|ekg","option_only":true},"bradycardie":{"title":"Bradycardie","short":"Bradycardie is een trage hartslag, bij volwassenen meestal onder 50–60 slagen per minuut.","definition":"<p><strong>Bradycardie</strong> kan fysiologisch zijn (bijv. bij getrainde sporters en tijdens de slaap) of pathologisch, door sinusknoopdysfunctie, AV-blok, medicatie (bètablokkers, digoxine, verapamil), hypothyreoïdie, hypothermie of verhoogde intracraniële druk. Klachten zijn moeheid, duizeligheid en syncope.</p>","image_url":"","wiki_title":"Bradycardia","match":"bradycardie","option_only":true},"hypotensie":{"title":"Hypotensie","short":"Hypotensie is een lage bloeddruk; klinisch relevant als ze leidt tot klachten of onvoldoende doorbloeding van organen.","definition":"<p><strong>Hypotensie</strong> kan constitutioneel en onschuldig zijn. Pathologische hypotensie ontstaat bij ondervulling (bloedverlies, dehydratie), vaatverwijding (sepsis, anafylaxie, medicatie), verminderde pompfunctie (cardiogeen) of obstructie (tamponnade, longembolie). Orthostatische hypotensie treedt op bij opstaan. Een daling van de doorbloeding geeft duizeligheid, verwardheid, oligurie en uiteindelijk shock.</p>","image_url":"","wiki_title":"Hypotension","match":"hypotensie|lage bloeddruk","option_only":true},"hyperglycemie":{"title":"Hyperglykemie","short":"Hyperglykemie is een te hoge bloedglucose, zoals bij diabetes mellitus.","definition":"<p>Bij <strong>hyperglykemie</strong> komt glucose boven de nierdrempel (ongeveer 10 mmol/L) in de urine, wat osmotische diurese, dorst en polyurie geeft. Ernstige ontregeling kan leiden tot diabetische ketoacidose (vooral type 1) of een hyperosmolair hyperglykemisch syndroom (vooral type 2). Ook stress, infectie en corticosteroïden kunnen de glucose verhogen.</p>","image_url":"","wiki_title":"Hyperglycemia","match":"hyperglycemie|hyperglykemie","option_only":true},"hypoglycemie":{"title":"Hypoglykemie","short":"Hypoglykemie is een te lage bloedglucose, met klachten zoals trillen, zweten, honger en bij ernstige vormen verwardheid en bewustzijnsverlies.","definition":"<p>Een <strong>hypoglykemie</strong> (meestal &lt;4 mmol/L bij diabetes) komt vooral voor bij gebruik van insuline of sulfonylureumderivaten, bij te weinig eten, inspanning of alcohol. Eerst ontstaan adrenerge klachten (trillen, zweten, hartkloppingen, honger), daarna neuroglycopene klachten (verwardheid, gedragsverandering, insulten, coma). Behandeling: snelle suikers of glucose intraveneus, of glucagon.</p>","image_url":"","wiki_title":"Hypoglycemia","match":"hypoglycemie|hypoglykemie","option_only":true},"hypothyreoïdie":{"title":"Hypothyreoïdie","short":"Hypothyreoïdie is een te trage schildklierwerking, met vermoeidheid, kouwelijkheid, gewichtstoename en obstipatie.","definition":"<p><strong>Hypothyreoïdie</strong> wordt in Nederland meestal veroorzaakt door de auto-immuunziekte van Hashimoto, daarnaast na thyreoïdectomie of radioactief jodium, door medicatie (amiodaron, lithium) of zelden door hypofyse-uitval. Klachten: traagheid, kouwelijkheid, droge huid, gewichtstoename, obstipatie, bradycardie en depressieve klachten. Bij primaire hypothyreoïdie is het TSH verhoogd en het vrij T4 laag; behandeling met levothyroxine.</p>","image_url":"","wiki_title":"Hypothyroidism","match":"hypothyreoïdie|hypothyreoidie|trage schildklier","option_only":true},"hyperthyreoïdie":{"title":"Hyperthyreoïdie","short":"Hyperthyreoïdie is een te snelle schildklierwerking, met hartkloppingen, gewichtsverlies, warmte-intolerantie en onrust.","definition":"<p><strong>Hyperthyreoïdie</strong> wordt o.a. veroorzaakt door de ziekte van Graves, een toxisch multinodulair struma, een toxisch adenoom of een (tijdelijke) thyreoïditis. Klachten: hartkloppingen of boezemfibrilleren, gewichtsverlies ondanks goede eetlust, zweten, tremor, onrust, slecht slapen en diarree. Diagnose: laag TSH met verhoogd vrij T4.</p>","image_url":"","wiki_title":"Hyperthyroidism","match":"hyperthyreoïdie|hyperthyreoidie|hyperthyreoïdie|overactieve schildklier","option_only":true},"hypofyse":{"title":"Hypofyse","short":"De hypofyse is een kleine klier onder de hersenen die via hormonen veel andere klieren aanstuurt.","definition":"<p>De <strong>hypofyse</strong> ligt in de sella turcica en is via de hypofysesteel met de hypothalamus verbonden. De <em>voorkwab</em> (adenohypofyse) maakt GH, prolactine, TSH, ACTH, LH en FSH onder invloed van releasing-hormonen. De <em>achterkwab</em> (neurohypofyse) geeft ADH en oxytocine af, die in de hypothalamus worden gemaakt.</p>","image_url":"","wiki_title":"Pituitary gland","match":"hypofyse|glandula pituitaria|hersenaanhangsel","option_only":true},"bijniermerg":{"title":"Bijniermerg","short":"Het bijniermerg maakt adrenaline en noradrenaline; het functioneert als een omgebouwd sympathisch ganglion.","definition":"<p>Het <strong>bijniermerg</strong> ontstaat uit de neurale lijst. De chromaffiene cellen worden direct geïnnerveerd door preganglionaire sympathische vezels (via acetylcholine op nicotinerge receptoren) en geven bij stress catecholaminen af in het bloed, vooral adrenaline. Een tumor van deze cellen heet een feochromocytoom.</p>","image_url":"","wiki_title":"Adrenal medulla","match":"bijniermerg|medulla glandulae suprarenalis","option_only":true},"obstipatie":{"title":"Obstipatie","short":"Obstipatie is een te harde en/of te weinig frequente ontlasting, vaak met moeizaam persen.","definition":"<p>Van <strong>obstipatie</strong> spreekt men bij minder dan drie keer per week ontlasting, harde ontlasting, persen of een gevoel van onvolledige lediging. Oorzaken zijn o.a. weinig vezels en vocht, weinig beweging, medicatie (opioïden, ijzer, anticholinergica, calciumantagonisten), hypothyreoïdie, hypercalciëmie, neurologische ziekten en obstructie door een tumor. Behandeling met leefstijladviezen en laxantia zoals macrogol.</p>","image_url":"","wiki_title":"Constipation","match":"obstipatie|verstopping|constipatie","option_only":true},"gastritis":{"title":"Gastritis","short":"Gastritis is een ontsteking van het maagslijmvlies, meestal door Helicobacter pylori, NSAID's of alcohol.","definition":"<p><strong>Gastritis</strong> kan acuut of chronisch zijn. Chronische actieve gastritis wordt vooral veroorzaakt door <em>Helicobacter pylori</em> en kan leiden tot atrofie, intestinale metaplasie en een verhoogd risico op maagcarcinoom en MALT-lymfoom. Auto-immuungastritis treft vooral het corpus, met vitamine B12-tekort. Veel patiënten hebben geen klachten.</p>","image_url":"","wiki_title":"Gastritis","match":"gastritis|maagslijmvliesontsteking","option_only":true},"appendicitis":{"title":"Appendicitis","short":"Appendicitis is een ontsteking van de appendix, met buikpijn die vaak rond de navel begint en naar rechtsonder trekt.","definition":"<p>Bij <strong>appendicitis</strong> raakt het lumen van de appendix afgesloten (bijv. door een fecoliet of lymfoïde hyperplasie), waarna ontsteking en infectie volgen. Klachten: pijn eerst rond de navel, later rechtsonder (McBurney), misselijkheid, koorts en lokale peritoneale prikkeling. Zonder behandeling kan perforatie optreden. Diagnose met echo en/of CT; behandeling meestal appendectomie.</p>","image_url":"","wiki_title":"Appendicitis","match":"appendicitis|blindedarmontsteking","option_only":true},"gastroenteritis":{"title":"Gastro-enteritis","short":"Gastro-enteritis is een ontsteking van maag en darm, meestal door een virus, met braken en diarree.","definition":"<p>Acute <strong>gastro-enteritis</strong> wordt meestal veroorzaakt door virussen (norovirus, rotavirus), soms door bacteriën (<em>Campylobacter</em>, <em>Salmonella</em>) of parasieten. Het belangrijkste risico is uitdroging, vooral bij jonge kinderen en ouderen. Behandeling bestaat vooral uit orale rehydratie; antibiotica zijn zelden nodig.</p>","image_url":"","wiki_title":"Gastroenteritis","match":"gastroenteritis|gastro-enteritis|buikgriep","option_only":true},"peritonitis":{"title":"Peritonitis","short":"Peritonitis is een ontsteking van het buikvlies, meestal door een perforatie of infectie van een buikorgaan.","definition":"<p><strong>Secundaire peritonitis</strong> ontstaat bij perforatie (bijv. ulcus, appendicitis, diverticulitis) of na buikoperaties. Klachten: hevige buikpijn, koorts, een plankharde buik met défense musculaire en loslaatpijn, en een stille buik. Spontane bacteriële peritonitis komt voor bij ascites door levercirrose. Behandeling: antibiotica en vaak chirurgie.</p>","image_url":"","wiki_title":"Peritonitis","match":"peritonitis|buikvliesontsteking","option_only":true},"maagperforatie":{"title":"Maagperforatie","short":"Bij een maagperforatie ontstaat een gat in de maagwand, meestal door een ulcus, waardoor maaginhoud in de buikholte lekt.","definition":"<p>Een <strong>perforatie</strong> van maag of duodenum geeft plotselinge, hevige bovenbuikpijn die zich snel over de hele buik uitbreidt, met een plankharde buik (chemische peritonitis). Op een staande X-thorax of CT is vrij lucht onder het diafragma te zien. Risicofactoren zijn NSAID-gebruik, <em>H. pylori</em> en roken. Behandeling is meestal chirurgisch sluiten.</p>","image_url":"","wiki_title":"Gastrointestinal perforation","match":"maagperforatie|perforatie van de maag|ulcusperforatie","option_only":true},"diagnostische laparoscopie":{"title":"Diagnostische laparoscopie","short":"Bij een diagnostische laparoscopie wordt via kleine sneetjes met een camera in de buikholte gekeken.","definition":"<p>Bij een <strong>laparoscopie</strong> wordt de buik opgeblazen met CO₂ en via kleine incisies een camera en instrumenten ingebracht. Het wordt diagnostisch gebruikt bij onduidelijke buikpijn, verdenking op endometriose of buitenbaarmoederlijke zwangerschap en voor stadiëring van tumoren; vaak kan in dezelfde ingreep worden behandeld.</p>","image_url":"","wiki_title":"Laparoscopy","match":"diagnostische laparoscopie|laparoscopie|kijkoperatie","option_only":true},"mri":{"title":"MRI","short":"MRI maakt met een sterk magneetveld en radiogolven gedetailleerde beelden van weke delen, zonder ioniserende straling.","definition":"<p>Bij <strong>MRI</strong> worden waterstofkernen in een sterk magneetveld door radiogolven aangeslagen; het signaal bij terugkeer verschilt per weefseltype. MRI is bijzonder geschikt voor hersenen, ruggenmerg, gewrichten, weke delen en het bekken. Nadelen zijn de lange duur, kosten en beperkingen bij pacemakers en sommige metalen implantaten.</p>","image_url":"","wiki_title":"Magnetic resonance imaging","match":"mri|mri-scan|magnetic resonance imaging","option_only":true},"igg":{"title":"IgG","short":"IgG is de meest voorkomende antistofklasse in het bloed; het is belangrijk bij de secundaire immuunrespons en passeert de placenta.","definition":"<p><strong>IgG</strong> is een monomeer en heeft vier subklassen. Het werkt via neutralisatie, opsonisatie (via Fcγ-receptoren op fagocyten) en complementactivatie. Het is de belangrijkste antistof bij een herhaalde blootstelling en de enige klasse die actief via de placenta naar de foetus gaat, wat pasgeborenen maandenlang beschermt.</p>","image_url":"","wiki_title":"Immunoglobulin G","match":"igg|immunoglobuline g","option_only":true},"epidurale anesthesie":{"title":"Epidurale anesthesie","short":"Bij epidurale anesthesie wordt via een katheter in de epidurale ruimte een lokaal anestheticum toegediend, bijv. als pijnstilling bij de bevalling.","definition":"<p>Bij <strong>epidurale anesthesie</strong> wordt verdovingsmiddel (vaak met een opioïd) buiten de dura gegeven, waar het de zenuwwortels verdooft. Het werkt trager en is beter doseerbaar dan een spinale (intrathecale) verdoving. Bijwerkingen: bloeddrukdaling, jeuk, koorts, tijdelijk krachtsverlies en zelden postpunctionele hoofdpijn of een epiduraal hematoom.</p>","image_url":"","wiki_title":"Epidural administration","match":"epidurale anesthesie|epiduraal","option_only":true},"vruchtwaterpunctie":{"title":"Vruchtwaterpunctie (amniocentese)","short":"Bij een vruchtwaterpunctie wordt onder echogeleide vruchtwater afgenomen voor onderzoek naar chromosoomafwijkingen of infecties bij de foetus.","definition":"<p>Een <strong>amniocentese</strong> wordt meestal vanaf ongeveer 15–16 weken zwangerschap gedaan. Het vruchtwater bevat foetale cellen waarvan het DNA kan worden onderzocht. Er is een klein risico op een miskraam. Een vlokkentest kan eerder (vanaf ongeveer 11 weken) en onderzoekt placentaweefsel.</p>","image_url":"","wiki_title":"Amniocentesis","match":"vruchtwaterpunctie|amniocentese","option_only":true},"morfine":{"title":"Morfine","short":"Morfine is een sterk werkend opioïd dat µ-opioïdreceptoren activeert; gebruikt bij ernstige pijn en kortademigheid in de palliatieve fase.","definition":"<p><strong>Morfine</strong> werkt pijnstillend via µ-receptoren in het centrale zenuwstelsel. Bijwerkingen zijn obstipatie (altijd een laxans erbij), misselijkheid, sufheid, ademhalingsdepressie, miosis en jeuk; bij langdurig gebruik ontstaan tolerantie en afhankelijkheid. De actieve metabolieten worden via de nier uitgescheiden en hopen op bij nierfalen. Antidotum: naloxon.</p>","image_url":"","wiki_title":"Morphine","match":"morfine|morphine","option_only":true},"aceton":{"title":"Aceton (ketonlichaam)","short":"Aceton is een ketonlichaam dat ontstaat uit acetoacetaat; het geeft de zoete ‘nagellakgeur’ van de adem bij ketose.","definition":"<p>Bij vasten of insulinetekort maakt de lever uit vetzuren de <strong>ketonlichamen</strong> acetoacetaat en β-hydroxybutyraat, die door brein, hart en spier als brandstof gebruikt kunnen worden. Aceton ontstaat spontaan uit acetoacetaat, wordt niet verder gebruikt en wordt uitgeademd. Bij diabetische ketoacidose ruikt de adem daardoor fruitig.</p>","image_url":"","wiki_title":"Ketone bodies","match":"aceton|ketonlichamen|ketonen","option_only":true},"vimentine":{"title":"Vimentine","short":"Vimentine is een intermediair filament in cellen van mesenchymale oorsprong, zoals fibroblasten, endotheel en leukocyten.","definition":"<p><strong>Vimentine</strong> geeft cellen mechanische stevigheid en verankert organellen. In de pathologie is het een immunohistochemische marker voor tumoren van mesenchymale oorsprong (sarcomen). Andere intermediaire filamenten zijn keratine (epitheel), desmine (spier), GFAP (gliacellen), neurofilamenten en lamines.</p>","image_url":"","wiki_title":"Vimentin","match":"vimentine|vimentin","option_only":true},"22q11 deletie syndroom":{"title":"22q11-deletiesyndroom","short":"Het 22q11-deletiesyndroom ontstaat door een microdeletie op chromosoom 22 en geeft o.a. hartafwijkingen, een gehemeltespleet, hypocalciëmie en immuunstoornissen.","definition":"<p>Bij het <strong>22q11-deletiesyndroom</strong> (DiGeorge) is de ontwikkeling van de derde en vierde kieuwzakjes verstoord. Kenmerken (‘CATCH-22’): hartafwijkingen (vooral conotruncaal, zoals Fallot en truncus arteriosus), afwijkend gezicht, hypoplasie van de thymus (T-celtekort), gehemeltespleet en hypocalciëmie door hypoplastische bijschildklieren. Op latere leeftijd is er een verhoogd risico op psychose.</p>","image_url":"","wiki_title":"DiGeorge syndrome","match":"22q11 deletie syndroom|22q11-deletiesyndroom|digeorge-syndroom|velocardiofaciaal syndroom","option_only":true},"syndroom van marfan":{"title":"Syndroom van Marfan","short":"Het syndroom van Marfan is een autosomaal dominante bindweefselziekte door mutaties in het fibrilline-1-gen.","definition":"<p>Bij het <strong>syndroom van Marfan</strong> zijn de microfibrillen van elastische vezels afwijkend en is TGF-β-signalering verhoogd. Kenmerken: lange, slanke gestalte met lange ledematen en vingers, hypermobiele gewrichten, borstkasafwijkingen, lensluxatie (meestal naar boven) en verwijding van de aortawortel met risico op dissectie. Behandeling o.a. met bètablokkers of ARB's en tijdige aortachirurgie.</p>","image_url":"","wiki_title":"Marfan syndrome","match":"syndroom van marfan|marfansyndroom|marfan syndroom","option_only":true},"achondroplasie":{"title":"Achondroplasie","short":"Achondroplasie is de meest voorkomende vorm van disproportionele dwerggroei, door een activerende mutatie in FGFR3.","definition":"<p>Bij <strong>achondroplasie</strong> remt het overactieve FGFR3 de enchondrale verbening in de groeischijven. Kenmerken: korte ledematen (vooral bovenarmen en bovenbenen), een relatief normale romp, een groot hoofd met een prominent voorhoofd en een normale intelligentie. Het erft autosomaal dominant over, maar ontstaat meestal de novo (vaak bij oudere vaders).</p>","image_url":"","wiki_title":"Achondroplasia","match":"achondroplasie","option_only":true},"cilindrisch epitheel":{"title":"Cilindrisch epitheel","short":"Cilindrisch epitheel bestaat uit cellen die hoger zijn dan breed, met de kern aan de basis; het bekleedt o.a. maag en darm.","definition":"<p><strong>Eenlagig cilindrisch epitheel</strong> komt voor in maag, dunne en dikke darm en galblaas, en is gespecialiseerd in absorptie en secretie (vaak met microvilli of slijmbekercellen). Met trilharen komt het voor in de eileider. In de slokdarm kan plaveiselepitheel door cilindrisch epitheel vervangen worden (Barrett).</p>","image_url":"","wiki_title":"Simple columnar epithelium","match":"cilindrisch epitheel|eenlagig cilindrisch epitheel|cilinderepitheel","option_only":true},"meerrijig plaveiselepitheel":{"title":"Meerrijig (pseudostratified) epitheel","short":"Meerrijig epitheel lijkt meerlagig, maar alle cellen raken de basaalmembraan; met trilharen bekleedt het de luchtwegen.","definition":"<p>In <strong>meerrijig epitheel</strong> liggen de kernen op verschillende hoogtes, waardoor het meerlagig lijkt, terwijl elke cel contact maakt met de basaalmembraan. Het klassieke voorbeeld is het respiratoire epitheel (meerrijig trilhaarcilinderepitheel met slijmbekercellen) in neus, trachea en bronchi. Een ‘meerrijig plaveiselepitheel’ bestaat strikt genomen niet.</p>","image_url":"","wiki_title":"Pseudostratified columnar epithelium","match":"meerrijig plaveiselepitheel|meerrijig epitheel|meerrijig trilhaarcilinderepitheel","option_only":true},"notochord":{"title":"Notochord (chorda dorsalis)","short":"De notochord is een staafvormige structuur in het embryo die de as aangeeft en het bovenliggende ectoderm aanzet tot vorming van de neurale plaat.","definition":"<p>De <strong>chorda dorsalis</strong> ontstaat uit het axiaal mesoderm tijdens de gastrulatie. Door signalen zoals Sonic hedgehog induceert zij de neurale plaat en de ventrale structuren van de neurale buis, en stuurt zij de vorming van de wervellichamen. Bij volwassenen blijft er alleen een restant over in de nucleus pulposus; een chordoom is een tumor van chordaresten.</p>","image_url":"","wiki_title":"Notochord","match":"notochord|chorda dorsalis","option_only":true},"axiaal mesoderm":{"title":"Axiaal mesoderm","short":"Het axiaal mesoderm is het mesoderm in de middellijn van het embryo; hieruit ontstaat de notochord.","definition":"<p>Tijdens de gastrulatie migreren cellen via de primitiefstreep. Het mesoderm wordt van mediaal naar lateraal ingedeeld in <strong>axiaal mesoderm</strong> (chorda dorsalis en prechordale plaat), paraxiaal mesoderm (somieten), intermediair mesoderm (urogenitaal stelsel) en lateraal plaatmesoderm (lichaamswand, hart, vaten).</p>","image_url":"","wiki_title":"Mesoderm","match":"axiaal mesoderm|chordamesoderm","option_only":true},"laterale plaat mesoderm":{"title":"Laterale plaatmesoderm","short":"Het laterale plaatmesoderm splitst in een somatisch en splanchnisch blad, waaruit lichaamswand, ledematen, hart, vaten en de wand van de darm ontstaan.","definition":"<p>Het <strong>laterale plaatmesoderm</strong> splitst zich in het <em>somatische</em> (pariëtale) blad, dat met het ectoderm de lichaamswand en het bindweefsel van de ledematen vormt, en het <em>splanchnische</em> (viscerale) blad, dat met het endoderm de wand van de darm, het hart en de bloedvaten vormt. De ruimte ertussen wordt de lichaamsholte (coeloom).</p>","image_url":"","wiki_title":"Lateral plate mesoderm","match":"laterale plaat mesoderm|lateraal plaatmesoderm|laterale plaatmesoderm","option_only":true},"neurulatie":{"title":"Neurulatie","short":"Neurulatie is de vorming van de neurale buis uit de neurale plaat in de derde en vierde week van de embryonale ontwikkeling.","definition":"<p>Bij <strong>neurulatie</strong> verdikt het ectoderm boven de chorda tot de neurale plaat, die zich opvouwt tot neurale plooien die in de middellijn sluiten tot de neurale buis. De sluiting begint in het midden en eindigt bij de craniale (dag ±25) en caudale (dag ±28) neuroporus. Niet sluiten geeft anencefalie of spina bifida. Uit de neurale lijst ontstaan o.a. perifere zenuwen, melanocyten en het bijniermerg.</p>","image_url":"","wiki_title":"Neurulation","match":"neurulatie","option_only":true},"nidatie":{"title":"Nidatie (innesteling)","short":"Nidatie is de innesteling van de blastocyst in het endometrium, ongeveer 6–7 dagen na de bevruchting.","definition":"<p>Bij <strong>nidatie</strong> hecht de blastocyst zich met de trofoblast aan het endometrium, meestal aan de achterwand van het corpus uteri. De syncytiotrofoblast dringt het endometrium binnen en begint hCG te maken, dat het corpus luteum in stand houdt. Innesteling buiten de uterusholte (meestal in de tuba) heet een extra-uteriene graviditeit.</p>","image_url":"","wiki_title":"Implantation (embryology)","match":"nidatie|innesteling","option_only":true},"primaire spermatocyten":{"title":"Primaire spermatocyt","short":"Een primaire spermatocyt is een diploïde kiemcel die de eerste meiotische deling ondergaat.","definition":"<p>Een <strong>primaire spermatocyt</strong> ontstaat uit een spermatogonium en verdubbelt eerst haar DNA. Tijdens de lange profase van meiose I vindt crossing-over plaats tussen homologe chromosomen. Na meiose I ontstaan twee secundaire spermatocyten.</p>","image_url":"","wiki_title":"Spermatocyte","match":"primaire spermatocyten|primaire spermatocyt|spermatocyt i","option_only":true},"secundaire spermatocyten":{"title":"Secundaire spermatocyt","short":"Een secundaire spermatocyt is een haploïde cel (met dubbele chromatiden) die direct de tweede meiotische deling ondergaat.","definition":"<p><strong>Secundaire spermatocyten</strong> ontstaan uit meiose I en bestaan maar kort, omdat ze snel meiose II doorlopen. Daaruit ontstaan per secundaire spermatocyt twee spermatiden.</p>","image_url":"","wiki_title":"Spermatocyte","match":"secundaire spermatocyten|secundaire spermatocyt|spermatocyt ii","option_only":true},"spermatide":{"title":"Spermatide","short":"Een spermatide is een haploïde cel uit de tweede meiotische deling, die via spermiogenese uitgroeit tot een spermatozoön.","definition":"<p>Bij de <strong>spermiogenese</strong> verandert een ronde spermatide in een spermatozoön: het acrosoom wordt gevormd, de kern condenseert, er groeit een staart (flagel) en overtollig cytoplasma wordt afgestoten en door Sertolicellen opgenomen. Er vindt geen celdeling meer plaats.</p>","image_url":"","wiki_title":"Spermatid","match":"spermatide|spermatiden","option_only":true},"agenesie van beide nieren":{"title":"Bilaterale nieragenesie","short":"Bij bilaterale nieragenesie zijn beide nieren niet aangelegd, met ernstig tekort aan vruchtwater en longhypoplasie als gevolg.","definition":"<p>Bij <strong>bilaterale nieragenesie</strong> ontstaan de nieren niet, doordat de ureterknop niet of verkeerd met het metanefrogene mesoderm in contact komt. Er wordt geen foetale urine gemaakt, met oligo- of anhydramnion. Dat leidt tot de Potter-sequentie: longhypoplasie, een afgeplat gezicht en standsafwijkingen van de ledematen; het is niet met het leven verenigbaar.</p>","image_url":"","wiki_title":"Renal agenesis","match":"agenesie van beide nieren|bilaterale nieragenesie|nieragenesie","option_only":true},"hernia diafragmatica":{"title":"Hernia diafragmatica","short":"Bij een hernia diafragmatica liggen buikorganen via een defect in het diafragma in de borstholte.","definition":"<p>De <strong>congenitale hernia diafragmatica</strong> ontstaat meestal links-achter (hernia van Bochdalek) doordat de pleuroperitoneale membranen niet goed sluiten. Darmen en soms maag en lever liggen in de thorax en belemmeren de groei van de long (longhypoplasie, pulmonale hypertensie). De pasgeborene is direct na de geboorte benauwd met een ingevallen buik.</p>","image_url":"","wiki_title":"Congenital diaphragmatic hernia","match":"hernia diafragmatica|congenitale hernia diafragmatica|hernia van bochdalek","option_only":true},"hyaliene membraanziekte":{"title":"Hyalienemembraanziekte (IRDS)","short":"Hyalienemembraanziekte is ademnood bij te vroeg geboren kinderen door een tekort aan surfactant.","definition":"<p>Bij <strong>IRDS</strong> maken onrijpe longen (vooral vóór 32 weken) te weinig surfactant, waardoor de alveoli samenvallen. Kort na de geboorte ontstaan kreunen, neusvleugelen, intrekkingen en cyanose. Het risico wordt verlaagd door antenatale corticosteroïden aan de moeder; behandeling met CPAP en surfactant via de trachea.</p>","image_url":"","wiki_title":"Infant respiratory distress syndrome","match":"hyaliene membraanziekte|hyalienemembraanziekte|irds|respiratory distress syndrome","option_only":true},"miskraam":{"title":"Miskraam","short":"Een miskraam is het spontaan verloren gaan van een zwangerschap vóór 16 weken (in Nederland), meestal in het eerste trimester.","definition":"<p>Ongeveer 10–15% van de vastgestelde zwangerschappen eindigt in een <strong>miskraam</strong>. De meeste vroege miskramen worden veroorzaakt door chromosoomafwijkingen van het embryo. Klachten zijn bloedverlies en buikkrampen. Het risico stijgt met de leeftijd van de moeder. Bij herhaalde miskramen wordt o.a. gezocht naar het antifosfolipidensyndroom en chromosoomafwijkingen bij de ouders.</p>","image_url":"","wiki_title":"Miscarriage","match":"miskraam|spontane abortus","option_only":true},"polycysteus ovariumsyndroom":{"title":"Polycysteus ovariumsyndroom (PCOS)","short":"PCOS is een hormonale stoornis met onregelmatige of uitblijvende ovulatie, verhoogde androgenen en/of veel kleine follikels in de ovaria.","definition":"<p>Volgens de Rotterdam-criteria spreekt men van <strong>PCOS</strong> bij twee van drie kenmerken: oligo- of anovulatie, klinische of biochemische hyperandrogenisme (acne, hirsutisme) en polycysteuze ovaria op de echo. Het gaat vaak samen met insulineresistentie en overgewicht. Het is een veelvoorkomende oorzaak van subfertiliteit.</p>","image_url":"","wiki_title":"Polycystic ovary syndrome","match":"polycysteus ovariumsyndroom|pcos|polycysteus ovarium syndroom","option_only":true},"salpingitis":{"title":"Salpingitis","short":"Salpingitis is een ontsteking van de eileiders, meestal door een opstijgende seksueel overdraagbare infectie.","definition":"<p><strong>Salpingitis</strong> maakt deel uit van pelvic inflammatory disease (PID) en wordt vaak veroorzaakt door <em>Chlamydia trachomatis</em> of gonokokken. Klachten: onderbuikpijn, koorts, abnormale afscheiding en slingerpijn bij vaginaal toucher. Complicaties zijn tubo-ovarieel abces, verklevingen, buitenbaarmoederlijke zwangerschap en subfertiliteit.</p>","image_url":"","wiki_title":"Salpingitis","match":"salpingitis|eileiderontsteking|pelvic inflammatory disease|pid","option_only":true},"mammacarcinoom":{"title":"Mammacarcinoom (borstkanker)","short":"Het mammacarcinoom is een kwaadaardige tumor van de borstklier, de meest voorkomende kanker bij vrouwen.","definition":"<p>Het <strong>mammacarcinoom</strong> is meestal een invasief carcinoom uitgaande van de afvoergangen (ductaal) of lobjes (lobulair). Risicofactoren zijn leeftijd, familiaire belasting (BRCA1/2), lange oestrogeenblootstelling en alcohol. Behandeling hangt af van stadium en receptorstatus (oestrogeen, progesteron, HER2): chirurgie, radiotherapie, hormonale therapie, chemotherapie en doelgerichte therapie. Er is een bevolkingsonderzoek met mammografie.</p>","image_url":"","wiki_title":"Breast cancer","match":"mammacarcinoom|borstkanker","option_only":true},"anorexie":{"title":"Anorexie (verminderde eetlust)","short":"Anorexie betekent als symptoom verminderde of afwezige eetlust; het is iets anders dan de eetstoornis anorexia nervosa.","definition":"<p>Als symptoom is <strong>anorexie</strong> een aspecifiek teken van ziekte, bijvoorbeeld bij infecties, ontsteking (cytokines), maligniteiten, leverziekte, nierfalen, depressie en als bijwerking van medicatie. Bij acute buikpathologie, zoals appendicitis, is verminderde eetlust een veelvoorkomend begeleidend symptoom.</p>","image_url":"","wiki_title":"Anorexia (symptom)","match":"anorexie|eetlustverlies|verminderde eetlust","option_only":true},"trombosebeen":{"title":"Trombosebeen (diepveneuze trombose)","short":"Een trombosebeen is een stolsel in een diepe vene van het been, met een dik, pijnlijk, warm been.","definition":"<p>Bij een <strong>diepveneuze trombose</strong> ontstaat een stolsel in de diepe venen, meestal in de kuit of bovenbeen. Risicofactoren volgen de trias van Virchow: stase, hypercoagulabiliteit en vaatwandschade (bijv. operatie, immobilisatie, kanker, zwangerschap, oestrogenen). Diagnostiek met een beslisregel (Wells), D-dimeer en compressie-echografie. De belangrijkste complicatie is een longembolie; behandeling met antistolling.</p>","image_url":"","wiki_title":"Deep vein thrombosis","match":"trombosebeen|diepveneuze trombose|dvt|been-trombose","option_only":true},"diverticulitis":{"title":"Diverticulitis","short":"Diverticulitis is een ontsteking van een of meer divertikels (uitstulpingen) van de dikke darm.","definition":"<p>Bij <b>diverticulitis</b> raakt een divertikel ontstoken, vermoedelijk door obstructie en microperforatie. Divertikels ontstaan vooral bij ouderen en bij vezelarme voeding. De ernst wordt ingedeeld volgens Hinchey (van lokale ontsteking tot abces en perforatie met peritonitis). Diagnose met echo of CT; ongecompliceerde gevallen worden meestal conservatief behandeld.</p>","image_url":"","wiki_title":"Diverticulitis","match":"diverticulitis","option_only":true},"corticosteroïden":{"title":"Corticosteroïden","short":"Corticosteroïden zijn van cortisol afgeleide middelen met sterke ontstekingsremmende en immunosuppressieve werking.","definition":"<p>Glucocorticoïden binden aan een intracellulaire receptor en remmen de transcriptie van ontstekingsgenen (cytokines, COX-2) en de vorming van ontstekingsmediatoren. Ze worden lokaal (huid, inhalatie, injectie) en systemisch gebruikt. Bij langdurig systemisch gebruik: osteoporose, hyperglykemie, gewichtstoename, huidatrofie, infecties, spierzwakte, cataract en remming van de eigen bijnier (niet abrupt stoppen).</p>","image_url":"","wiki_title":"Corticosteroid","match":"corticosteroïden|corticosteroiden|glucocorticoïden|corticosteroïd","option_only":true},"tachycardie":{"title":"Tachycardie","short":"Tachycardie is een snelle hartslag, bij volwassenen boven 100 slagen per minuut.","definition":"<p>Een <strong>sinustachycardie</strong> is een fysiologische reactie op o.a. inspanning, koorts, pijn, angst, hypovolemie, anemie, hypoxie en hyperthyreoïdie. Pathologische tachycardieën zijn o.a. boezemfibrilleren, AVNRT en ventrikeltachycardie. Het ECG maakt het onderscheid.</p>","image_url":"","wiki_title":"Tachycardia","match":"tachycardie|sinustachycardie","option_only":true},"persisterende ductus arteriosus":{"title":"Persisterende ductus arteriosus (PDA)","short":"Bij een PDA sluit de ductus arteriosus na de geboorte niet, waardoor bloed van de aorta naar de a. pulmonalis stroomt.","definition":"<p>De <strong>ductus arteriosus</strong> verbindt foetaal de a. pulmonalis met de aorta. Normaal sluit hij in de eerste dagen na de geboorte (door stijgende zuurstofspanning en dalende prostaglandinen). Bij prematuren en na rubella in de zwangerschap blijft hij vaker open. Er is een continu ‘machinegeruis’; sluiting met indomethacine/ibuprofen of via een katheter.</p>","image_url":"","wiki_title":"Patent ductus arteriosus","match":"persisterende ductus arteriosus|open ductus arteriosus|pda|ductus botalli","option_only":true},"hypothermie":{"title":"Hypothermie","short":"Hypothermie is een te lage lichaamstemperatuur, onder 35 °C.","definition":"<p>Bij <strong>hypothermie</strong> vertragen stofwisseling, hartritme en ademhaling. Eerst ontstaan rillen en verwardheid; bij verdere daling verdwijnt het rillen, met bradycardie, ritmestoornissen (Osborn-golven op het ECG) en bewustzijnsdaling. Pasgeborenen, ouderen en mensen onder invloed van alcohol zijn kwetsbaar. Therapeutische hypothermie wordt gebruikt na reanimatie en bij perinatale asfyxie.</p>","image_url":"","wiki_title":"Hypothermia","match":"hypothermie|onderkoeling","option_only":true},"cervixcarcinoom":{"title":"Cervixcarcinoom","short":"Het cervixcarcinoom is kanker van de baarmoederhals, vrijwel altijd veroorzaakt door een persisterende infectie met hoog-risico-HPV.","definition":"<p>Het <strong>cervixcarcinoom</strong> ontstaat via voorstadia (CIN) in de transformatiezone, meestal als plaveiselcelcarcinoom. Klachten: contactbloedingen (na gemeenschap), intermenstrueel bloedverlies en afscheiding. Preventie via HPV-vaccinatie en het bevolkingsonderzoek (hrHPV-test). Behandeling afhankelijk van stadium: operatie of (chemo)radiatie.</p>","image_url":"","wiki_title":"Cervical cancer","match":"cervixcarcinoom|baarmoederhalskanker","option_only":true},"endometriumcarcinoom":{"title":"Endometriumcarcinoom","short":"Het endometriumcarcinoom is kanker van het baarmoederslijmvlies, typisch met bloedverlies na de menopauze.","definition":"<p>Het <strong>endometriumcarcinoom</strong> (type 1) hangt samen met langdurige blootstelling aan oestrogenen zonder progesteron: obesitas, weinig zwangerschappen, PCOS, tamoxifen en het Lynch-syndroom. Het presenteert zich meestal vroeg met postmenopauzaal bloedverlies en heeft dan een goede prognose. Diagnostiek met een transvaginale echo en een endometriumbiopt.</p>","image_url":"","wiki_title":"Endometrial cancer","match":"endometriumcarcinoom|baarmoederkanker|baarmoederslijmvlieskanker","option_only":true},"iga":{"title":"IgA","short":"IgA is de belangrijkste antistof op slijmvliezen en in secreten zoals speeksel, tranen en moedermelk.","definition":"<p><strong>IgA</strong> komt in het bloed als monomeer en op slijmvliezen als dimeer (secretoir IgA), verbonden door een J-keten en beschermd door een secretoire component. Het neutraliseert micro-organismen en toxines zonder ontsteking. Een selectieve IgA-deficiëntie is de meest voorkomende primaire immuundeficiëntie en geeft vaak weinig klachten; bij coeliakie-serologie kan het fout-negatieve uitslagen geven.</p>","image_url":"","wiki_title":"Immunoglobulin A","match":"iga|immunoglobuline a","option_only":true},"galgangatresie":{"title":"Galgangatresie","short":"Bij galgangatresie zijn de galwegen bij een pasgeborene ontstoken en afgesloten, met aanhoudende geelzucht en ontkleurde ontlasting.","definition":"<p>Bij <strong>biliaire atresie</strong> worden de extrahepatische galwegen in de eerste levensweken door een fibroserend proces afgesloten. De baby is na de eerste twee weken nog steeds geel (met een verhoogd geconjugeerd bilirubine), heeft ontkleurde ontlasting en donkere urine. Snelle diagnose is cruciaal: een Kasai-operatie werkt het beste vóór 60 dagen; anders volgt cirrose en levertransplantatie.</p>","image_url":"","wiki_title":"Biliary atresia","match":"galgangatresie|biliaire atresie","option_only":true},"invaginatie":{"title":"Invaginatie","short":"Bij invaginatie schuift een stuk darm in het aansluitende stuk, als een telescoop; vooral bij jonge kinderen.","definition":"<p><strong>Invaginatie</strong> komt vooral voor tussen 6 maanden en 2 jaar, meestal ileocolisch, soms met een vergrote lymfeklier of divertikel van Meckel als ‘leidpunt’. Typisch zijn aanvallen van huilen en buikpijn met optrekken van de benen, braken, een worstvormige zwelling en later ‘bessengeleiontlasting’. Behandeling met luchtdrukreductie of chirurgie.</p>","image_url":"","wiki_title":"Intussusception (medical disorder)","match":"invaginatie|intussusceptie","option_only":true},"echo":{"title":"Echografie","short":"Echografie maakt met hoogfrequente geluidsgolven beelden van weke delen en organen, zonder straling.","definition":"<p>Bij <strong>echografie</strong> zendt een transducer geluidsgolven uit en vangt de echo's op. Vocht is zwart, weefsel grijs; bot en lucht houden het geluid tegen. Het is goedkoop, snel en direct beschikbaar, en geschikt voor o.a. galblaas, nieren, schildklier, zwangerschap, hart (echocardiografie), vaten (duplex) en gewrichten. De kwaliteit hangt af van de onderzoeker en de patiënt.</p>","image_url":"","wiki_title":"Medical ultrasound","match":"echo|echografie|echoscopie|ultrageluid","option_only":true},"ct scan":{"title":"CT-scan","short":"Een CT-scan maakt met röntgenstraling dwarsdoorsneden van het lichaam.","definition":"<p>Bij <strong>computertomografie</strong> draait een röntgenbuis rond de patiënt en wordt een driedimensionaal beeld berekend. CT is snel en zeer geschikt voor trauma, bloedingen in het hoofd, longen, buik en bot; met contrast ook voor vaten. Nadelen zijn de stralingsbelasting en het contrastmiddel (nierfunctie, allergie).</p>","image_url":"","wiki_title":"CT scan","match":"ct scan|ct-scan|computertomografie","option_only":true},"trichomonas":{"title":"Trichomonas vaginalis","short":"Trichomonas vaginalis is een seksueel overdraagbare protozo die vaginitis met schuimende, groengele afscheiding veroorzaakt.","definition":"<p><strong>Trichomoniasis</strong> geeft bij vrouwen jeuk, branderigheid en riekende, schuimende afscheiding, soms met een ‘aardbeiencervix’; bij mannen meestal geen klachten. De beweeglijke flagellaten zijn soms te zien in een nat preparaat; PCR is gevoeliger. Behandeling met metronidazol, ook voor de partner.</p>","image_url":"","wiki_title":"Trichomoniasis","match":"trichomonas|trichomonas vaginalis|trichomoniasis","option_only":true},"os pubis":{"title":"Os pubis (schaambeen)","short":"Het os pubis is het voorste deel van het heupbeen; beide schaambeenderen zijn in de symfyse met elkaar verbonden.","definition":"<p>Het <strong>os pubis</strong> vormt samen met het os ilium en os ischii het heupbeen (os coxae), dat in het acetabulum samenkomt. De ramus superior en inferior begrenzen het foramen obturatum. Fracturen van de schaambeentakken komen veel voor bij ouderen na een val.</p>","image_url":"","wiki_title":"Pubis (bone)","match":"os pubis|schaambeen","option_only":true},"intermediair mesoderm":{"title":"Intermediair mesoderm","short":"Uit het intermediair mesoderm ontwikkelen zich de nieren en de geslachtsorganen.","definition":"<p>Het <strong>intermediair mesoderm</strong> ligt tussen het paraxiale mesoderm (somieten) en het laterale plaatmesoderm. Hieruit ontstaan achtereenvolgens pronephros, mesonephros (met de gang van Wolff) en metanephros (de blijvende nier), en ook de gonaden.</p>","image_url":"","wiki_title":"Intermediate mesoderm","match":"intermediair mesoderm","option_only":true},"velamenteuze insertie":{"title":"Velamenteuze insertie van de navelstreng","short":"Bij een velamenteuze insertie hecht de navelstreng aan de vliezen in plaats van aan de placenta, waardoor de vaten onbeschermd door de vliezen lopen.","definition":"<p>Bij een <strong>velamenteuze insertie</strong> lopen de navelstrengvaten zonder gelei van Wharton door de vliezen naar de placenta. Liggen ze vóór de baarmoedermond (vasa praevia), dan kunnen ze bij het breken van de vliezen scheuren, met snel foetaal bloedverlies. Het komt vaker voor bij meerlingen en IVF.</p>","image_url":"","wiki_title":"Velamentous cord insertion","match":"velamenteuze insertie|velamenteuze insertie van de navelstreng","option_only":true},"langdurig gebroken vliezen":{"title":"Langdurig gebroken vliezen","short":"Bij langdurig gebroken vliezen is het vruchtwater langer dan 24 uur voor de geboorte gebroken, met een verhoogd infectierisico.","definition":"<p>Na het breken van de vliezen kunnen bacteriën uit de vagina opstijgen, met risico op een infectie van vruchtwater en vliezen (chorioamnionitis) en neonatale infectie (o.a. groep B-streptokokken). Bij langdurig gebroken vliezen wordt daarom vaak de baring ingeleid en worden moeder en kind gecontroleerd op tekenen van infectie.</p>","image_url":"","wiki_title":"Prelabor rupture of membranes","match":"langdurig gebroken vliezen|lang gebroken vliezen|prom","option_only":true},"schildklier hormoon":{"title":"Schildklierhormoon (T4 en T3)","short":"Schildklierhormoon (T4 en het actievere T3) regelt het basaal metabolisme, de groei en de ontwikkeling van het zenuwstelsel.","definition":"<p>De schildklier maakt vooral <strong>T4</strong>, dat in de weefsels wordt omgezet in het actievere <strong>T3</strong>. Het hormoon werkt via kernreceptoren en verhoogt o.a. de stofwisseling, warmteproductie en gevoeligheid voor catecholaminen. In de foetale en vroege kinderjaren is het essentieel voor de hersenontwikkeling; daarom wordt congenitale hypothyreoïdie met de hielprik opgespoord.</p>","image_url":"","wiki_title":"Thyroid hormones","match":"schildklier hormoon|schildklierhormoon|thyroxine|t4|t3","option_only":true},"miltruptuur":{"title":"Miltruptuur","short":"Bij een miltruptuur scheurt de milt, meestal na een trauma, met een levensbedreigende inwendige bloeding.","definition":"<p>Een <strong>miltruptuur</strong> ontstaat vooral na een stomp buiktrauma links (soms met ribfracturen). Een vergrote milt (bijv. bij de ziekte van Pfeiffer of malaria) kan al bij gering trauma scheuren. Klachten: pijn linksboven, soms uitstralend naar de linkerschouder (teken van Kehr), en tekenen van shock. Behandeling afhankelijk van stabiliteit: observatie, embolisatie of splenectomie.</p>","image_url":"","wiki_title":"Splenic injury","match":"miltruptuur|scheuring van de milt","option_only":true},"lobaire pneumonie, veroorzaakt door pneumokokken":{"title":"Pneumonie","short":"Een pneumonie is een infectie van het longweefsel (alveoli), meestal door bacteriën of virussen, met koorts, hoesten en kortademigheid.","definition":"<p>Bij een <strong>pneumonie</strong> (longontsteking) raken de alveoli ontstoken en vullen ze zich met ontstekingsvocht en cellen. Daardoor is minder longoppervlak beschikbaar voor gaswisseling.</p><p>Typische klachten zijn koorts, hoesten (vaak met sputum), kortademigheid en soms pijn bij het ademen. Bij lichamelijk onderzoek kunnen crepitaties of een gedempte percussie optreden; een X-thorax toont een infiltraat. De meest voorkomende verwekker van de buiten het ziekenhuis opgelopen pneumonie is <em>Streptococcus pneumoniae</em>.</p>","image_url":"","wiki_title":"Pneumonia","match":"lobaire pneumonie, veroorzaakt door pneumokokken","option_only":true},"diabetes type 2":{"title":"Diabetes mellitus","short":"Diabetes mellitus is een chronisch verhoogde bloedglucose door een tekort aan insuline (type 1) of verminderde insulinegevoeligheid met relatief tekort (type 2).","definition":"<p>Bij <strong>diabetes mellitus</strong> is de bloedglucose chronisch te hoog. Bij <em>type 1</em> vernietigt een auto-immuunproces de bètacellen van de pancreas (absoluut insulinetekort, vaak op jonge leeftijd, risico op ketoacidose). Bij <em>type 2</em> is er insulineresistentie (vaak met overgewicht) en een tekortschietende insulineproductie.</p><p>Klachten: dorst, veel plassen, moeheid en gewichtsverlies. Op termijn ontstaan microvasculaire (retinopathie, nefropathie, neuropathie) en macrovasculaire complicaties (hart- en vaatziekten). Diagnose o.a. nuchter glucose ≥7,0 mmol/L of HbA1c ≥48 mmol/mol.</p>","image_url":"","wiki_title":"Diabetes","match":"diabetes type 2","option_only":true},"appendicitis acuta":{"title":"Appendicitis","short":"Appendicitis is een ontsteking van de appendix, met buikpijn die vaak rond de navel begint en naar rechtsonder trekt.","definition":"<p>Bij <strong>appendicitis</strong> raakt het lumen van de appendix afgesloten (bijv. door een fecoliet of lymfoïde hyperplasie), waarna ontsteking en infectie volgen. Klachten: pijn eerst rond de navel, later rechtsonder (McBurney), misselijkheid, koorts en lokale peritoneale prikkeling. Zonder behandeling kan perforatie optreden. Diagnose met echo en/of CT; behandeling meestal appendectomie.</p>","image_url":"","wiki_title":"Appendicitis","match":"appendicitis acuta","option_only":true},"diabetes mellitus 2":{"title":"Diabetes mellitus","short":"Diabetes mellitus is een chronisch verhoogde bloedglucose door een tekort aan insuline (type 1) of verminderde insulinegevoeligheid met relatief tekort (type 2).","definition":"<p>Bij <strong>diabetes mellitus</strong> is de bloedglucose chronisch te hoog. Bij <em>type 1</em> vernietigt een auto-immuunproces de bètacellen van de pancreas (absoluut insulinetekort, vaak op jonge leeftijd, risico op ketoacidose). Bij <em>type 2</em> is er insulineresistentie (vaak met overgewicht) en een tekortschietende insulineproductie.</p><p>Klachten: dorst, veel plassen, moeheid en gewichtsverlies. Op termijn ontstaan microvasculaire (retinopathie, nefropathie, neuropathie) en macrovasculaire complicaties (hart- en vaatziekten). Diagnose o.a. nuchter glucose ≥7,0 mmol/L of HbA1c ≥48 mmol/mol.</p>","image_url":"","wiki_title":"Diabetes","match":"diabetes mellitus 2","option_only":true},"hoge koorts":{"title":"Koorts","short":"Koorts is een verhoogde lichaamstemperatuur (≥38,0 °C) doordat de hypothalamus het setpoint hoger instelt, meestal als reactie op infectie.","definition":"<p>Bij <strong>koorts</strong> wordt het temperatuursetpoint in de hypothalamus verhoogd. Pyrogenen zoals bacteriële producten en cytokines (IL-1, IL-6, TNF) stimuleren daar de productie van prostaglandine E<sub>2</sub>.</p><p>Het lichaam ervaart de normale temperatuur dan als te koud: vasoconstrictie en rillingen verhogen de temperatuur. Als het setpoint weer daalt, volgen zweten en vasodilatatie. Koortsremmers (paracetamol, NSAID's) remmen de prostaglandinesynthese. Hyperthermie (bijv. hitteberoerte) is iets anders: daar is het setpoint níet verhoogd.</p>","image_url":"","wiki_title":"Fever","match":"hoge koorts","option_only":true},"trisomie 21":{"title":"Trisomie 21 (syndroom van Down)","short":"Het syndroom van Down ontstaat door een extra (deel van) chromosoom 21, met verstandelijke beperking en kenmerkende uiterlijke en medische kenmerken.","definition":"<p>Bij <strong>trisomie 21</strong> (meestal door non-disjunctie, risico stijgend met de leeftijd van de moeder) zijn er o.a. hypotonie, een kenmerkend gezicht, één handpalmplooi, hartafwijkingen (AVSD), duodenumatresie, ziekte van Hirschsprung, hypothyreoïdie, een verhoogd risico op leukemie en vroege Alzheimer. Prenatale screening gebeurt met de NIPT.</p>","image_url":"","wiki_title":"Down syndrome","match":"trisomie 21|syndroom van down|down syndroom","option_only":true},"desmine":{"title":"Desmine","short":"Desmine is het intermediaire filament van spiercellen (skelet, hart en glad), dat sarcomeren met elkaar verbindt.","definition":"<p><strong>Desmine</strong> verbindt de Z-schijven van naburige myofibrillen en verankert ze aan het sarcolemma en de kern. In de pathologie is het een marker voor tumoren van spieroorsprong (bijv. rabdomyosarcoom, leiomyosarcoom). Mutaties geven een desmine-myopathie met hartbetrokkenheid.</p>","image_url":"","wiki_title":"Desmin","match":"desmine|desmin","option_only":true},"alfa thalassemie":{"title":"Alfa-thalassemie","short":"Bij alfa-thalassemie worden te weinig alfa-globineketens gemaakt, door deletie van een of meer van de vier alfa-genen.","definition":"<p>Het beeld van <strong>alfa-thalassemie</strong> hangt af van het aantal ontbrekende genen: van stil dragerschap (1) en een lichte microcytaire anemie (2) tot HbH-ziekte (3) en hydrops foetalis (4, Hb Bart's). Dragers hebben een microcytaire anemie met een normaal ferritine, wat onderscheid met ijzergebrek belangrijk maakt.</p>","image_url":"","wiki_title":"Alpha-thalassemia","match":"alfa thalassemie|alfa-thalassemie|thalassemie","option_only":true},"polycytemia vera":{"title":"Polycytemia vera","short":"Polycytemia vera is een myeloproliferatieve neoplasie met een overmatige aanmaak van rode bloedcellen, meestal door een JAK2-mutatie.","definition":"<p>Bij <strong>polycytemia vera</strong> zijn het hemoglobine en hematocriet verhoogd, vaak ook leukocyten en plaatjes. Klachten: hoofdpijn, roodheid, jeuk na een warm bad, splenomegalie en een verhoogd risico op trombose. Secundaire polycytemie (bijv. door hypoxie bij COPD of EPO-producerende tumoren) heeft een verhoogd EPO. Behandeling met aderlatingen en acetylsalicylzuur.</p>","image_url":"","wiki_title":"Polycythemia vera","match":"polycytemia vera|polycytemie|polycythemie","option_only":true},"zwangerschapsdiabetes":{"title":"Zwangerschapsdiabetes","short":"Zwangerschapsdiabetes is een verhoogde bloedglucose die voor het eerst in de zwangerschap ontstaat, door insulineresistentie onder invloed van placentahormonen.","definition":"<p>Risicofactoren voor <strong>diabetes gravidarum</strong> zijn overgewicht, eerdere zwangerschapsdiabetes, een eerder groot kind, familie met diabetes en bepaalde afkomst. Gevolgen zijn een groot kind (macrosomie), schouderdystocie en neonatale hypoglykemie. Behandeling met dieet, eventueel insuline. Na de zwangerschap is het risico op diabetes type 2 verhoogd.</p>","image_url":"","wiki_title":"Gestational diabetes","match":"zwangerschapsdiabetes|diabetes gravidarum","option_only":true},"os ilium":{"title":"Os ilium (darmbeen)","short":"Het os ilium is het bovenste, waaiervormige deel van het heupbeen, met de crista iliaca.","definition":"<p>Het <strong>os ilium</strong> vormt samen met het os ischii en os pubis het heupbeen en draagt bij aan het acetabulum. Aan de crista iliaca hechten buikspieren aan; de spina iliaca anterior superior is een belangrijk oriëntatiepunt. De bekkenkam wordt gebruikt voor beenmergonderzoek en botgrafts.</p>","image_url":"","wiki_title":"Ilium (bone)","match":"os ilium|darmbeen|ilium","option_only":true},"diffuse intravasale stolling (dis)":{"title":"Diffuse intravasale stolling (DIS)","short":"Bij DIS wordt de stolling in het hele lichaam ontregeld geactiveerd, met microtrombi én bloedingen door verbruik van stollingsfactoren en plaatjes.","definition":"<p><strong>DIS</strong> ontstaat bij o.a. sepsis, trauma, obstetrische complicaties (placentaloslating, vruchtwaterembolie), acute promyelocytenleukemie en uitgebreide tumoren. Kenmerken: daling van plaatjes en fibrinogeen, verlengde PT/APTT en sterk verhoogde D-dimeer, met orgaanschade en bloedingen. Behandeling van de oorzaak staat centraal.</p>","image_url":"","wiki_title":"Disseminated intravascular coagulation","match":"diffuse intravasale stolling (dis)|diffuse intravasale stolling|dis|dic","option_only":true},"myocardinfarcering":{"title":"Myocardinfarct","short":"Bij een myocardinfarct sterft hartspierweefsel af doordat een kransslagader (meestal door een trombus op een gescheurde plaque) afsluit.","definition":"<p>Een <strong>myocardinfarct</strong> ontstaat meestal doordat een atherosclerotische plaque in een coronairarterie scheurt, waarna een trombus het vat (deels) afsluit. Het hartspierweefsel achter de afsluiting raakt ischemisch en gaat na 20–30 minuten necrotisch.</p><p>Klachten: drukkende pijn op de borst, uitstralend naar arm, kaak of rug, met zweten, misselijkheid en benauwdheid. Diagnose op basis van klachten, ECG (ST-elevatie of niet) en een stijging van troponine. Complicaties zijn ritmestoornissen, hartfalen en mechanische complicaties. Snelle reperfusie (PCI) is cruciaal.</p>","image_url":"","wiki_title":"Myocardial infarction","match":"myocardinfarcering","option_only":true},"gesloten ductus arteriosus":{"title":"Persisterende ductus arteriosus (PDA)","short":"Bij een PDA sluit de ductus arteriosus na de geboorte niet, waardoor bloed van de aorta naar de a. pulmonalis stroomt.","definition":"<p>De <strong>ductus arteriosus</strong> verbindt foetaal de a. pulmonalis met de aorta. Normaal sluit hij in de eerste dagen na de geboorte (door stijgende zuurstofspanning en dalende prostaglandinen). Bij prematuren en na rubella in de zwangerschap blijft hij vaker open. Er is een continu ‘machinegeruis’; sluiting met indomethacine/ibuprofen of via een katheter.</p>","image_url":"","wiki_title":"Patent ductus arteriosus","match":"gesloten ductus arteriosus","option_only":true},"diep veneuze trombose":{"title":"Trombosebeen (diepveneuze trombose)","short":"Een trombosebeen is een stolsel in een diepe vene van het been, met een dik, pijnlijk, warm been.","definition":"<p>Bij een <strong>diepveneuze trombose</strong> ontstaat een stolsel in de diepe venen, meestal in de kuit of bovenbeen. Risicofactoren volgen de trias van Virchow: stase, hypercoagulabiliteit en vaatwandschade (bijv. operatie, immobilisatie, kanker, zwangerschap, oestrogenen). Diagnostiek met een beslisregel (Wells), D-dimeer en compressie-echografie. De belangrijkste complicatie is een longembolie; behandeling met antistolling.</p>","image_url":"","wiki_title":"Deep vein thrombosis","match":"diep veneuze trombose","option_only":true},"glomerulaire filtratiesnelheid":{"title":"Nier","short":"De nieren filteren het bloed en regelen water-, zout- en zuur-base-evenwicht en bloeddruk; ook maken ze hormonen (renine, EPO, actief vitamine D).","definition":"<p>De <strong>nieren</strong> liggen retroperitoneaal aan weerszijden van de wervelkolom. De functionele eenheid is het <em>nefron</em>: glomerulus, proximale tubulus, lis van Henle, distale tubulus en verzamelbuis. Samen filteren de nieren ongeveer 180 liter per dag, waarvan meer dan 99% wordt teruggeresorbeerd.</p><p>Ze scheiden afvalstoffen (ureum, creatinine) en geneesmiddelen uit, regelen het volume en de samenstelling van de lichaamsvloeistoffen en de pH, en maken <em>renine</em> (bloeddruk), <em>erytropoëtine</em> (aanmaak van rode bloedcellen) en <em>calcitriol</em> (actief vitamine D).</p>","image_url":"","wiki_title":"Kidney","match":"glomerulaire filtratiesnelheid","option_only":true},"colon sigmoideum":{"title":"Colon sigmoideum","short":"Het colon sigmoideum is het S-vormige deel van de dikke darm tussen colon descendens en rectum.","definition":"<p>Het <strong>sigmoïd</strong> heeft een eigen mesenterium en is daardoor beweeglijk, wat een volvulus mogelijk maakt. Het is de meest voorkomende plaats van divertikels en diverticulitis en een veelvoorkomende plaats voor coloncarcinoom.</p>","image_url":"","wiki_title":"Sigmoid colon","match":"colon sigmoideum|sigmoïd|sigmoid","option_only":true},"tertiair follikel":{"title":"Tertiaire (Graafse) follikel","short":"Een tertiaire of Graafse follikel is een rijpe follikel met een groot antrum, klaar voor de ovulatie.","definition":"<p>In de <strong>Graafse follikel</strong> ligt de oöcyt op een heuveltje granulosacellen (cumulus oophorus) in een met vocht gevulde holte. De dominante follikel maakt veel oestradiol, wat de LH-piek en de ovulatie uitlokt. Na de ovulatie wordt hij een corpus luteum.</p>","image_url":"","wiki_title":"Ovarian follicle","match":"tertiair follikel|tertiaire follikel|graafse follikel","option_only":true},"primaire follikel":{"title":"Primaire follikel","short":"Een primaire follikel is een vroeg stadium van de ovariële follikel, met één laag kubische granulosacellen rond de oöcyt.","definition":"<p>Uit de <strong>primordiale follikel</strong> (afgeplatte cellen) ontstaat de primaire follikel, daarna de secundaire (meerlagig) en tertiaire (met antrum). Bij de geboorte is de voorraad primordiale follikels al aangelegd en daalt die levenslang.</p>","image_url":"","wiki_title":"Ovarian follicle","match":"primaire follikel|primordiale follikel","option_only":true},"extra-uteriene graviditeit":{"title":"Extra-uteriene graviditeit (EUG)","short":"Bij een extra-uteriene graviditeit nestelt het embryo zich buiten de baarmoederholte, meestal in de eileider.","definition":"<p>Risicofactoren voor een <strong>EUG</strong> zijn eerdere salpingitis (chlamydia), eerdere EUG of tubachirurgie, IUD en IVF. Klachten: amenorroe, vaginaal bloedverlies en buikpijn; bij een ruptuur een acute buik en shock. Diagnose met hCG en transvaginale echo (geen intra-uteriene zwangerschap). Behandeling: afwachten, methotrexaat of laparoscopie.</p>","image_url":"","wiki_title":"Ectopic pregnancy","match":"extra-uteriene graviditeit|buitenbaarmoederlijke zwangerschap|eug|ectopische zwangerschap","option_only":true},"placenta praevia":{"title":"Placenta praevia","short":"Bij placenta praevia ligt de placenta (deels) over de inwendige baarmoedermond, met risico op pijnloos helderrood bloedverlies.","definition":"<p><strong>Placenta praevia</strong> geeft in de tweede helft van de zwangerschap pijnloos vaginaal bloedverlies. Een vaginaal toucher is gecontra-indiceerd tot de ligging met een echo is uitgesloten. Risicofactoren: eerdere sectio, multipariteit, hogere leeftijd. Bevalling meestal via een keizersnede.</p>","image_url":"","wiki_title":"Placenta praevia","match":"placenta praevia|placenta previa","option_only":true},"autoimmuun destructie van betacellen":{"title":"Diabetes mellitus type 1","short":"Bij diabetes type 1 vernietigt het immuunsysteem de insulineproducerende bètacellen, met een absoluut insulinetekort.","definition":"<p><strong>Diabetes type 1</strong> begint meestal op jonge leeftijd, vaak met dorst, veel plassen, gewichtsverlies en soms een diabetische ketoacidose. Er zijn auto-antistoffen (bijv. tegen GAD of IA-2). Behandeling is levenslang insuline.</p>","image_url":"","wiki_title":"Type 1 diabetes","match":"autoimmuun destructie van betacellen|diabetes mellitus type 1|type 1 diabetes","option_only":true},"urinekweek":{"title":"Urinekweek","short":"Bij een urinekweek wordt urine op voedingsbodems gekweekt om de verwekker van een urineweginfectie en de antibioticagevoeligheid te bepalen.","definition":"<p>Een <strong>urinekweek</strong> wordt gedaan bij gecompliceerde of recidiverende urineweginfecties, zwangeren, kinderen, mannen en bij koorts. Een goede (midstream) afname voorkomt verontreiniging met huid- of vaginaflora. De uitslag duurt meestal 1–2 dagen.</p>","image_url":"","wiki_title":"Urine culture","match":"urinekweek","option_only":true},"kraamvrouwenkoorts":{"title":"Kraamvrouwenkoorts (puerperale sepsis)","short":"Kraamvrouwenkoorts is een ernstige infectie na de bevalling, klassiek door groep A-streptokokken.","definition":"<p><strong>Puerperale sepsis</strong> ontstaat vanuit de uterus (endometritis) en kan zeer snel verlopen, met hoge koorts, buikpijn en shock. Semmelweis toonde in de 19e eeuw aan dat handhygiëne de sterfte sterk verminderde.</p>","image_url":"","wiki_title":"Puerperal fever","match":"kraamvrouwenkoorts|puerperale sepsis","option_only":true},"cholelithiasis":{"title":"Cholelithiasis (galstenen)","short":"Cholelithiasis betekent galstenen in de galblaas; veel mensen hebben geen klachten, anderen krijgen koliekpijn of complicaties.","definition":"<p>De meeste <strong>galstenen</strong> zijn cholesterolstenen (risicofactoren: vrouw, overgewicht, snel afvallen, zwangerschap, leeftijd); pigmentstenen ontstaan bij hemolyse. Een galsteenkoliek geeft heftige pijn rechtsboven of in het epigastrium. Complicaties zijn cholecystitis, choledocholithiasis, cholangitis en pancreatitis.</p>","image_url":"","wiki_title":"Gallstone","match":"cholelithiasis|galstenen|galsteenlijden","option_only":true},"a. umbilicalis":{"title":"A. umbilicalis (navelarterie)","short":"De aa. umbilicales voeren zuurstofarm bloed van de foetus via de navelstreng naar de placenta.","definition":"<p>Normaal heeft de navelstreng twee <strong>navelarteriën</strong> en één navelvene. Ze ontspringen uit de aa. iliacae internae. Na de geboorte sluiten ze en worden ze (deels) de mediale umbilicale plooien; een proximaal deel blijft als a. vesicalis superior bestaan. Een navelstreng met één arterie is geassocieerd met aangeboren afwijkingen.</p>","image_url":"","wiki_title":"Umbilical artery","match":"a. umbilicalis|arteria umbilicalis|navelarterie|navelarteriën","option_only":true},"bradycardie (lage hartfrequentie)":{"title":"Bradycardie","short":"Bradycardie is een trage hartslag, bij volwassenen meestal onder 50–60 slagen per minuut.","definition":"<p><strong>Bradycardie</strong> kan fysiologisch zijn (bijv. bij getrainde sporters en tijdens de slaap) of pathologisch, door sinusknoopdysfunctie, AV-blok, medicatie (bètablokkers, digoxine, verapamil), hypothyreoïdie, hypothermie of verhoogde intracraniële druk. Klachten zijn moeheid, duizeligheid en syncope.</p>","image_url":"","wiki_title":"Bradycardia","match":"bradycardie (lage hartfrequentie)","option_only":true},"tachycardie (hoge hartfrequentie)":{"title":"Tachycardie","short":"Tachycardie is een snelle hartslag, bij volwassenen boven 100 slagen per minuut.","definition":"<p>Een <strong>sinustachycardie</strong> is een fysiologische reactie op o.a. inspanning, koorts, pijn, angst, hypovolemie, anemie, hypoxie en hyperthyreoïdie. Pathologische tachycardieën zijn o.a. boezemfibrilleren, AVNRT en ventrikeltachycardie. Het ECG maakt het onderscheid.</p>","image_url":"","wiki_title":"Tachycardia","match":"tachycardie (hoge hartfrequentie)","option_only":true},"s. aureus":{"title":"Staphylococcus aureus","short":"S. aureus is een grampositieve kok in trosjes, coagulasepositief, die huid- en wondinfecties, abcessen en ernstige systemische infecties veroorzaakt.","definition":"<p><strong><em>Staphylococcus aureus</em></strong> is een grampositieve kok die in trosjes groeit en <em>coagulase-positief</em> is (onderscheid met andere stafylokokken). Ongeveer een derde van de mensen draagt hem in de neus.</p><p>Hij veroorzaakt huid- en wekedeleninfecties (impetigo, furunkels, abcessen, wondinfecties), maar ook osteomyelitis, septische artritis, endocarditis en sepsis. Via toxines kan hij voedselvergiftiging en het toxischeshocksyndroom veroorzaken. MRSA is een methicillineresistente variant.</p>","image_url":"","wiki_title":"Staphylococcus aureus","match":"s. aureus","option_only":true},"een corticosteroïd":{"title":"Corticosteroïden","short":"Corticosteroïden zijn van cortisol afgeleide middelen met sterke ontstekingsremmende en immunosuppressieve werking.","definition":"<p>Glucocorticoïden binden aan een intracellulaire receptor en remmen de transcriptie van ontstekingsgenen (cytokines, COX-2) en de vorming van ontstekingsmediatoren. Ze worden lokaal (huid, inhalatie, injectie) en systemisch gebruikt. Bij langdurig systemisch gebruik: osteoporose, hyperglykemie, gewichtstoename, huidatrofie, infecties, spierzwakte, cataract en remming van de eigen bijnier (niet abrupt stoppen).</p>","image_url":"","wiki_title":"Corticosteroid","match":"een corticosteroïd","option_only":true},"herpes simplex type 2":{"title":"Herpes genitalis","short":"Herpes genitalis is een seksueel overdraagbare infectie met HSV-2 of HSV-1, met pijnlijke blaasjes en zweertjes in het genitale gebied.","definition":"<p>Bij <strong>herpes genitalis</strong> ontstaan na besmetting pijnlijke groepjes blaasjes die openbreken tot oppervlakkige ulcera, vaak met koorts, pijn bij het plassen en vergrote lieslymfeklieren. Het virus blijft latent in de sacrale ganglia en kan recidiveren. Een primaire infectie rond de bevalling geeft een groot risico op neonatale herpes.</p>","image_url":"","wiki_title":"Genital herpes","match":"herpes simplex type 2","option_only":true},"factoren van het complementsysteem":{"title":"Complement","short":"Het complementsysteem is een cascade van plasma-eiwitten die micro-organismen opsoneert, ontsteking aanjaagt en via het membraanaanvalscomplex cellen lyseert.","definition":"<p>Het <strong>complementsysteem</strong> bestaat uit plasma-eiwitten (C1–C9 en regulatoren) die in een cascade worden geactiveerd via de klassieke (antilichamen), de lectine- en de alternatieve route.</p><p>Belangrijke functies: <em>opsonisatie</em> (C3b), aantrekken van ontstekingscellen en mestcelactivatie (anafylatoxinen C3a en C5a) en lysis van micro-organismen door het <em>membraanaanvalscomplex</em> (C5b–C9). Tekort aan late complementfactoren geeft een verhoogd risico op <em>Neisseria</em>-infecties.</p>","image_url":"","wiki_title":"Complement system","match":"factoren van het complementsysteem","option_only":true},"sigmoïd":{"title":"Colon sigmoideum","short":"Het colon sigmoideum is het S-vormige deel van de dikke darm tussen colon descendens en rectum.","definition":"<p>Het <strong>sigmoïd</strong> heeft een eigen mesenterium en is daardoor beweeglijk, wat een volvulus mogelijk maakt. Het is de meest voorkomende plaats van divertikels en diverticulitis en een veelvoorkomende plaats voor coloncarcinoom.</p>","image_url":"","wiki_title":"Sigmoid colon","match":"sigmoïd","option_only":true},"de uterus":{"title":"Uterus (baarmoeder)","short":"De uterus is het peervormige, gespierde orgaan in het kleine bekken waarin het embryo innestelt en de foetus groeit.","definition":"<p>De <strong>uterus</strong> bestaat uit fundus, corpus en cervix. De wand heeft drie lagen: endometrium (slijmvlies dat cyclisch opbouwt en afstoot), myometrium (dikke laag gladde spier) en perimetrium. De uterus ligt meestal geanteverteerd en geanteflecteerd en wordt doorbloed door de a. uterina.</p>","image_url":"","wiki_title":"Uterus","match":"de uterus","option_only":true},"down syndroom":{"title":"Trisomie 21 (syndroom van Down)","short":"Het syndroom van Down ontstaat door een extra (deel van) chromosoom 21, met verstandelijke beperking en kenmerkende uiterlijke en medische kenmerken.","definition":"<p>Bij <strong>trisomie 21</strong> (meestal door non-disjunctie, risico stijgend met de leeftijd van de moeder) zijn er o.a. hypotonie, een kenmerkend gezicht, één handpalmplooi, hartafwijkingen (AVSD), duodenumatresie, ziekte van Hirschsprung, hypothyreoïdie, een verhoogd risico op leukemie en vroege Alzheimer. Prenatale screening gebeurt met de NIPT.</p>","image_url":"","wiki_title":"Down syndrome","match":"down syndroom","option_only":true},"echo van de lever":{"title":"Echo abdomen","short":"Een echo abdomen is een echografisch onderzoek van de buikorganen; zonder straling en goed voor galblaas, galwegen, lever, nieren en vrij vocht.","definition":"<p>Bij een <strong>echo abdomen</strong> wordt met geluidsgolven een beeld gemaakt van de buikorganen. Het onderzoek gebruikt geen ioniserende straling, is goedkoop en direct beschikbaar.</p><p>Het is bijzonder geschikt voor het aantonen van galstenen en cholecystitis, verwijde galwegen, leverafwijkingen, nierstuwing (hydronefrose), een abdominaal aorta-aneurysma en vrij vocht. Darmgas en een dikke buikwand beperken het zicht; de kwaliteit hangt af van de onderzoeker.</p>","image_url":"","wiki_title":"Abdominal ultrasonography","match":"echo van de lever","option_only":true},"diverticultis":{"title":"Diverticulitis","short":"Diverticulitis is een ontsteking van een of meer divertikels (uitstulpingen) van de dikke darm.","definition":"<p>Bij <b>diverticulitis</b> raakt een divertikel ontstoken, vermoedelijk door obstructie en microperforatie. Divertikels ontstaan vooral bij ouderen en bij vezelarme voeding. De ernst wordt ingedeeld volgens Hinchey (van lokale ontsteking tot abces en perforatie met peritonitis). Diagnose met echo of CT; ongecompliceerde gevallen worden meestal conservatief behandeld.</p>","image_url":"","wiki_title":"Diverticulitis","match":"diverticultis","option_only":true},"tertiaire follikel":{"title":"Tertiaire (Graafse) follikel","short":"Een tertiaire of Graafse follikel is een rijpe follikel met een groot antrum, klaar voor de ovulatie.","definition":"<p>In de <strong>Graafse follikel</strong> ligt de oöcyt op een heuveltje granulosacellen (cumulus oophorus) in een met vocht gevulde holte. De dominante follikel maakt veel oestradiol, wat de LH-piek en de ovulatie uitlokt. Na de ovulatie wordt hij een corpus luteum.</p>","image_url":"","wiki_title":"Ovarian follicle","match":"tertiaire follikel","option_only":true},"eug (extra-uteriene zwangerschap)":{"title":"Extra-uteriene graviditeit (EUG)","short":"Bij een extra-uteriene graviditeit nestelt het embryo zich buiten de baarmoederholte, meestal in de eileider.","definition":"<p>Risicofactoren voor een <strong>EUG</strong> zijn eerdere salpingitis (chlamydia), eerdere EUG of tubachirurgie, IUD en IVF. Klachten: amenorroe, vaginaal bloedverlies en buikpijn; bij een ruptuur een acute buik en shock. Diagnose met hCG en transvaginale echo (geen intra-uteriene zwangerschap). Behandeling: afwachten, methotrexaat of laparoscopie.</p>","image_url":"","wiki_title":"Ectopic pregnancy","match":"eug (extra-uteriene zwangerschap)","option_only":true},"placenta preavia":{"title":"Placenta praevia","short":"Bij placenta praevia ligt de placenta (deels) over de inwendige baarmoedermond, met risico op pijnloos helderrood bloedverlies.","definition":"<p><strong>Placenta praevia</strong> geeft in de tweede helft van de zwangerschap pijnloos vaginaal bloedverlies. Een vaginaal toucher is gecontra-indiceerd tot de ligging met een echo is uitgesloten. Risicofactoren: eerdere sectio, multipariteit, hogere leeftijd. Bevalling meestal via een keizersnede.</p>","image_url":"","wiki_title":"Placenta praevia","match":"placenta preavia","option_only":true},"bloedgroep antagonisme":{"title":"AB0-antagonisme","short":"Bij AB0-antagonisme breken maternale anti-A- of anti-B-antistoffen (IgG) de rode bloedcellen van het kind af; meestal bij een moeder met bloedgroep O en een kind met A of B.","definition":"<p>Bij <strong>AB0-antagonisme</strong> heeft de moeder meestal <em>bloedgroep O</em> en het kind bloedgroep A of B. Mensen met bloedgroep O maken van nature anti-A- en anti-B-antistoffen, waarvan een deel IgG is en de placenta kan passeren.</p><p>Die antistoffen veroorzaken hemolyse van de foetale erytrocyten, wat bij de pasgeborene leidt tot een ongeconjugeerde hyperbilirubinemie. Het verloopt meestal milder dan rhesusantagonisme en kan ook bij een eerste zwangerschap voorkomen. De directe antiglobulinetest (Coombs) bij het kind is vaak (zwak) positief.</p>","image_url":"","wiki_title":"Hemolytic disease of the newborn (ABO)","match":"bloedgroep antagonisme","option_only":true},"type 2 diabetes mellitus":{"title":"Diabetes mellitus","short":"Diabetes mellitus is een chronisch verhoogde bloedglucose door een tekort aan insuline (type 1) of verminderde insulinegevoeligheid met relatief tekort (type 2).","definition":"<p>Bij <strong>diabetes mellitus</strong> is de bloedglucose chronisch te hoog. Bij <em>type 1</em> vernietigt een auto-immuunproces de bètacellen van de pancreas (absoluut insulinetekort, vaak op jonge leeftijd, risico op ketoacidose). Bij <em>type 2</em> is er insulineresistentie (vaak met overgewicht) en een tekortschietende insulineproductie.</p><p>Klachten: dorst, veel plassen, moeheid en gewichtsverlies. Op termijn ontstaan microvasculaire (retinopathie, nefropathie, neuropathie) en macrovasculaire complicaties (hart- en vaatziekten). Diagnose o.a. nuchter glucose ≥7,0 mmol/L of HbA1c ≥48 mmol/mol.</p>","image_url":"","wiki_title":"Diabetes","match":"type 2 diabetes mellitus","option_only":true},"prostaglandine":{"title":"Prostaglandinen","short":"Prostaglandinen zijn lokaal werkende lipidemediatoren uit arachidonzuur, gevormd via cyclo-oxygenase.","definition":"<p><strong>Prostaglandinen</strong> zijn betrokken bij ontsteking, pijn en koorts (PGE2), maagbescherming, nierdoorbloeding, de baring en het openhouden van de ductus arteriosus. Prostacycline (PGI2) uit het endotheel remt plaatjesaggregatie en verwijdt vaten; tromboxaan A2 uit plaatjes doet het omgekeerde. NSAID's remmen hun vorming.</p>","image_url":"","wiki_title":"Prostaglandin","match":"prostaglandine|prostaglandinen|prostaglandine pgi2|prostacycline","option_only":true},"myotoom":{"title":"Myotoom","short":"Een myotoom is de groep spieren die door één zenuwwortel wordt geïnnerveerd; embryonaal ook het deel van de somiet waaruit spieren ontstaan.","definition":"<p>Bij neurologisch onderzoek test men <strong>myotomen</strong> om de hoogte van een wortel- of ruggenmergletsel te bepalen, bijv. C5 schouderabductie, C7 elleboogextensie, L4 voetheffing (deels), L5 grote-teenextensie, S1 plantairflexie. Embryonaal splitst de somiet in sclerotoom, myotoom en dermatoom.</p>","image_url":"","wiki_title":"Myotome","match":"myotoom|myotomen","option_only":true},"primitieve streep":{"title":"Primitiefstreep","short":"De primitiefstreep is een groeve in de embryonale schijf waardoor cellen naar binnen migreren bij de gastrulatie.","definition":"<p>Tijdens de derde week verschijnt de <strong>primitiefstreep</strong> aan de caudale zijde van de epiblast. Cellen die erdoorheen migreren vormen het endoderm en mesoderm (gastrulatie), waarmee de drie kiembladen ontstaan. Restanten kunnen een sacrococcygeaal teratoom geven.</p>","image_url":"","wiki_title":"Primitive streak","match":"primitieve streep|primitiefstreep","option_only":true},"neurale lijstcellen":{"title":"Neurale-lijstcellen","short":"Neurale-lijstcellen ontstaan aan de rand van de neurale plaat en migreren door het embryo; ze vormen o.a. perifere zenuwen, melanocyten en het bijniermerg.","definition":"<p>Uit de <strong>neurale lijst</strong> ontstaan sensibele en autonome ganglia, Schwann-cellen, melanocyten, het bijniermerg, de C-cellen van de schildklier, delen van het hart (septering van de uitstroom) en veel gezichts- en halsstructuren. Stoornissen geven bijv. de ziekte van Hirschsprung of het 22q11-deletiesyndroom.</p>","image_url":"","wiki_title":"Neural crest","match":"neurale lijstcellen|neurale lijst|neurale-lijstcellen","option_only":true},"paraxiaal mesoderm":{"title":"Paraxiaal mesoderm","short":"Het paraxiaal mesoderm ligt naast de chorda en deelt zich in somieten, waaruit wervels, skeletspieren en de dermis van de rug ontstaan.","definition":"<p>Elke <strong>somiet</strong> splitst in een sclerotoom (wervels en ribben), myotoom (skeletspieren) en dermatoom (dermis). De segmentale opbouw verklaart de indeling in dermatomen en myotomen bij volwassenen.</p>","image_url":"","wiki_title":"Paraxial mesoderm","match":"paraxiaal mesoderm|somieten","option_only":true},"excavatio recto-uterina":{"title":"Excavatio recto-uterina (cavum Douglasi)","short":"De excavatio recto-uterina is het laagste punt van de buikholte bij de vrouw, tussen uterus en rectum.","definition":"<p>In het <strong>cavum Douglasi</strong> verzamelen zich vocht, bloed of pus, bijvoorbeeld bij een geruptureerde extra-uteriene zwangerschap of een abces. Het is te bereiken via het achterste vaginagewelf en zichtbaar op een transvaginale echo. Bij de man ligt op deze plek de excavatio rectovesicalis.</p>","image_url":"","wiki_title":"Rectouterine pouch","match":"excavatio recto-uterina|cavum douglasi|douglasholte","option_only":true},"fossa ischio-analis":{"title":"Fossa ischioanalis","short":"De fossa ischioanalis is een met vet gevulde ruimte aan weerszijden van het anaalkanaal.","definition":"<p>De <strong>fossa ischioanalis</strong> ligt tussen de m. levator ani en de zijwand van het bekken. Er lopen de vasa pudenda en de n. pudendus (kanaal van Alcock). Een ischioanaal abces ontstaat vaak vanuit een ontstoken anale klier.</p>","image_url":"","wiki_title":"Ischioanal fossa","match":"fossa ischio-analis|fossa ischioanalis|fossa ischiorectalis","option_only":true},"os coccygis":{"title":"Os coccygis (stuitbeen)","short":"Het os coccygis is het stuitbeen: drie tot vijf vergroeide rudimentaire wervels onder het sacrum.","definition":"<p>Het <strong>stuitbeen</strong> is een aanhechtingspunt voor bekkenbodemspieren en ligamenten. Pijn eraan (coccygodynie) ontstaat vaak na een val of bevalling.</p>","image_url":"","wiki_title":"Coccyx","match":"os coccygis|stuitbeen|coccyx","option_only":true},"hirsutisme":{"title":"Hirsutisme","short":"Hirsutisme is overmatige beharing bij vrouwen volgens een mannelijk patroon, meestal door een overmaat aan androgenen.","definition":"<p>De meest voorkomende oorzaak van <strong>hirsutisme</strong> is het polycysteus ovariumsyndroom; daarnaast idiopathisch, late-onset congenitale bijnierhyperplasie, het syndroom van Cushing, medicatie en zelden androgeenproducerende tumoren (bij snel ontstaan en virilisatie).</p>","image_url":"","wiki_title":"Hirsutism","match":"hirsutisme","option_only":true},"vaginitis":{"title":"Vaginitis","short":"Vaginitis is een ontsteking van de vagina, met afscheiding, jeuk of branderigheid.","definition":"<p>Veel voorkomende oorzaken zijn <strong>candida</strong> (wittige, kruimelige afscheiding, jeuk), <strong>bacteriële vaginose</strong> (dunne grijze afscheiding met visgeur, pH &gt;4,5) en <strong>trichomoniasis</strong> (schuimende, groengele afscheiding). Ook atrofie na de menopauze en irritatie kunnen vaginitis geven.</p>","image_url":"","wiki_title":"Vaginitis","match":"vaginitis|vulvovaginitis","option_only":true},"chlamydia trachomatis":{"title":"Chlamydia trachomatis","short":"Chlamydia trachomatis is een obligaat intracellulaire bacterie en de meest voorkomende bacteriële soa.","definition":"<p><strong>Chlamydia</strong> geeft vaak geen klachten; soms urethritis, cervicitis met afscheiding of bloedverlies na gemeenschap. Complicaties zijn salpingitis met subfertiliteit en extra-uteriene zwangerschap, epididymitis en reactieve artritis. Bij pasgeborenen conjunctivitis en pneumonie. Behandeling met doxycycline of azitromycine.</p>","image_url":"","wiki_title":"Chlamydia","match":"chlamydia trachomatis|chlamydia","option_only":true},"cornelia de lange syndroom":{"title":"Syndroom van Cornelia de Lange","short":"Het syndroom van Cornelia de Lange is een genetisch syndroom met groeiachterstand, verstandelijke beperking en kenmerkende gelaatstrekken.","definition":"<p>Kenmerken van <strong>Cornelia de Lange</strong> zijn doorlopende wenkbrauwen, lange wimpers, een klein neusje met naar voren gerichte neusgaten, een dunne bovenlip, kleine handen en voeten en soms afwijkingen van de armen. Het wordt vaak veroorzaakt door een mutatie in het NIPBL-gen.</p>","image_url":"","wiki_title":"Cornelia de Lange syndrome","match":"cornelia de lange syndroom|syndroom van cornelia de lange","option_only":true},"williams syndroom":{"title":"Syndroom van Williams","short":"Het syndroom van Williams ontstaat door een microdeletie op chromosoom 7 en geeft o.a. een supravalvulaire aortastenose, hypercalciëmie en een opvallend sociaal karakter.","definition":"<p>Bij het <strong>syndroom van Williams</strong> (deletie met o.a. het elastinegen) zijn er een ‘elfachtig’ gezicht, een lichte tot matige verstandelijke beperking met relatief goede taal, een zeer sociale persoonlijkheid, supravalvulaire aortastenose en soms hypercalciëmie in de babytijd.</p>","image_url":"","wiki_title":"Williams syndrome","match":"williams syndroom|syndroom van williams|williams-beuren","option_only":true},"caput succedaneum":{"title":"Caput succedaneum","short":"Een caput succedaneum is een oedemateuze zwelling van de hoofdhuid bij de pasgeborene, die over de schedelnaden heen loopt.","definition":"<p>Het <strong>caput succedaneum</strong> ontstaat door druk tijdens de baring (of vacuümextractie) en verdwijnt binnen enkele dagen. Een cefaalhematoom daarentegen is een bloeding onder het periost, begrensd door de schedelnaden, dat weken blijft en geelzucht kan verergeren.</p>","image_url":"","wiki_title":"Caput succedaneum","match":"caput succedaneum|een caput succedaneum|geboortegezwel","option_only":true},"cefaalhematoom":{"title":"Cefaalhematoom","short":"Een cefaalhematoom is een bloeding onder het periost van een schedelbot bij een pasgeborene, scherp begrensd door de schedelnaden.","definition":"<p>Een <strong>cefaalhematoom</strong> ontstaat na een moeizame of instrumentele bevalling, wordt soms pas na enkele uren zichtbaar en verdwijnt in weken. Door de afbraak van het bloed kan een neonatale icterus verergeren. Het subgaleale hematoom is een gevaarlijker vorm die niet door de naden wordt begrensd.</p>","image_url":"","wiki_title":"Cephalohematoma","match":"cefaalhematoom|een cefaalhematoom|kephalhematoom","option_only":true},"multipariteit":{"title":"Multipariteit","short":"Multipariteit betekent dat een vrouw al meerdere kinderen heeft gebaard.","definition":"<p>Een <strong>multipara</strong> heeft een of meer eerdere bevallingen na minstens 24 weken achter de rug. De ontsluiting en uitdrijving verlopen gemiddeld sneller dan bij een primipara. Hoge pariteit is een risicofactor voor o.a. uterusatonie, placenta praevia en verzakkingen.</p>","image_url":"","wiki_title":"Gravidity and parity","match":"multipariteit|multipara","option_only":true},"aneurysma aorta abdominalis":{"title":"Aneurysma van de aorta abdominalis (AAA)","short":"Een AAA is een verwijding van de buikslagader tot meer dan 3 cm; bij ruptuur is het levensbedreigend.","definition":"<p>Een <strong>AAA</strong> komt vooral voor bij oudere mannen die roken, met hypertensie en familiaire belasting. Meestal geeft het geen klachten; soms voelt men een pulserende zwelling. Een ruptuur geeft plotseling buik- of rugpijn en shock. Electieve behandeling (open of endovasculair) vanaf ongeveer 5,5 cm bij mannen.</p>","image_url":"","wiki_title":"Abdominal aortic aneurysm","match":"aneurysma aorta abdominalis|aaa|abdominaal aorta-aneurysma","option_only":true},"spanningspneumothorax links":{"title":"Spanningspneumothorax","short":"Bij een spanningspneumothorax hoopt lucht zich via een ventielmechanisme op in de pleuraholte, met verschuiving van het mediastinum en circulatoire shock.","definition":"<p>Kenmerken van een <strong>spanningspneumothorax</strong>: ernstige benauwdheid, hypotensie, gestuwde halsvenen, afwezig ademgeruis en hypersonore percussie aan de aangedane kant, en een trachea die naar de andere kant wijst. Het is een klinische diagnose en vraagt om directe ontlasting met een naald of thoracostomie, gevolgd door een drain.</p>","image_url":"","wiki_title":"Tension pneumothorax","match":"spanningspneumothorax links|spanningspneumothorax","option_only":true},"placentarest":{"title":"Placentarest","short":"Een placentarest is achtergebleven placentaweefsel in de uterus na de bevalling, met risico op nabloeding en infectie.","definition":"<p>Een <strong>placentarest</strong> verhindert dat de uterus goed samentrekt. Het kan direct een fluxus postpartum geven of later (dagen tot weken) bloedverlies en endometritis. Na de geboorte wordt de placenta daarom altijd op volledigheid gecontroleerd; zo nodig volgt een curettage.</p>","image_url":"","wiki_title":"Retained placenta","match":"placentarest|achtergebleven placentaresten","option_only":true},"cervixruptuur":{"title":"Cervixruptuur","short":"Een cervixruptuur is een scheur in de baarmoederhals tijdens de bevalling, die een nabloeding kan veroorzaken bij een goed samengetrokken uterus.","definition":"<p>Een <strong>cervixruptuur</strong> komt vaker voor bij een snelle of instrumentele bevalling. Bij helderrood bloedverlies ondanks een goed gecontraheerde uterus moet het geboortekanaal worden geïnspecteerd en een scheur worden gehecht.</p>","image_url":"","wiki_title":"","match":"cervixruptuur|cervixscheur","option_only":true},"placenta-insufficiëntie":{"title":"Placenta-insufficiëntie","short":"Bij placenta-insufficiëntie levert de placenta te weinig zuurstof en voeding aan de foetus, met groeivertraging als gevolg.","definition":"<p><strong>Placenta-insufficiëntie</strong> hangt samen met pre-eclampsie, hypertensie, roken en vaatziekten. Gevolgen zijn foetale groeivertraging en een verminderde hoeveelheid vruchtwater. Er is een verhoogd risico op foetale nood en sterfte; vaak wordt de bevalling eerder ingeleid.</p>","image_url":"","wiki_title":"Placental insufficiency","match":"placenta-insufficiëntie|placentainsufficiëntie","option_only":true},"fsh":{"title":"FSH (follikelstimulerend hormoon)","short":"FSH is een hormoon uit de hypofysevoorkwab dat de rijping van follikels en de spermatogenese stimuleert.","definition":"<p><strong>FSH</strong> stimuleert bij de vrouw de groei van follikels en de omzetting van androgenen in oestrogeen door granulosacellen; bij de man stimuleert het de Sertolicellen. Inhibine en oestrogeen remmen de afgifte. Een sterk verhoogd FSH wijst op falende gonaden, zoals na de menopauze of bij prematuur ovarieel falen.</p>","image_url":"","wiki_title":"Follicle-stimulating hormone","match":"fsh|follikelstimulerend hormoon","option_only":true},"galactosemie":{"title":"Galactosemie","short":"Galactosemie is een erfelijke stofwisselingsziekte waarbij galactose (uit melksuiker) niet goed kan worden afgebroken.","definition":"<p>Bij de klassieke vorm (GALT-deficiëntie) worden pasgeborenen na het starten van melkvoeding ziek, met braken, icterus, leverfalen, cataract en <em>E. coli</em>-sepsis. Het wordt opgespoord met de hielprik; behandeling is een galactosevrij dieet. Bij galactokinasedeficiëntie staat cataract op de voorgrond.</p>","image_url":"","wiki_title":"Galactosemia","match":"galactosemie","option_only":true},"meconium aspiratie":{"title":"Meconiumaspiratie","short":"Bij meconiumaspiratie ademt een pasgeborene met meconium besmeurd vruchtwater in, met benauwdheid door luchtwegobstructie en ontsteking.","definition":"<p><strong>Meconiumaspiratie</strong> komt vooral voor bij voldragen of serotiene kinderen na foetale nood. Het meconium verstopt de luchtwegen, inactiveert surfactant en veroorzaakt een chemische pneumonitis, soms met pulmonale hypertensie. Behandeling is ondersteunend (zuurstof, beademing, soms surfactant).</p>","image_url":"","wiki_title":"Meconium aspiration syndrome","match":"meconium aspiratie|meconiumaspiratie","option_only":true},"amniotomie":{"title":"Amniotomie","short":"Bij een amniotomie worden de vliezen kunstmatig gebroken, om de baring in te leiden of te versnellen.","definition":"<p>Een <strong>amniotomie</strong> kan alleen bij een (deels) ontsloten cervix en een goed ingedaald voorliggend deel, om een navelstrengprolaps te voorkomen. Na het breken van de vliezen wordt de kleur van het vruchtwater beoordeeld (meconium) en de foetale hartslag gecontroleerd.</p>","image_url":"","wiki_title":"Amniotomy","match":"amniotomie|vliezen breken","option_only":true},"een cefaalhematoom":{"title":"Cefaalhematoom","short":"Een cefaalhematoom is een bloeding onder het periost van een schedelbot bij een pasgeborene, scherp begrensd door de schedelnaden.","definition":"<p>Een <strong>cefaalhematoom</strong> ontstaat na een moeizame of instrumentele bevalling, wordt soms pas na enkele uren zichtbaar en verdwijnt in weken. Door de afbraak van het bloed kan een neonatale icterus verergeren. Het subgaleale hematoom is een gevaarlijker vorm die niet door de naden wordt begrensd.</p>","image_url":"","wiki_title":"Cephalohematoma","match":"een cefaalhematoom","option_only":true},"g6pd deficiëntie":{"title":"G6PD-deficiëntie","short":"Bij G6PD-deficiëntie zijn rode bloedcellen gevoelig voor oxidatieve stress, met hemolyse na bijv. infecties, bepaalde geneesmiddelen of tuinbonen.","definition":"<p><strong>G6PD</strong> levert via de pentosefosfaatroute NADPH, dat glutathion in rode bloedcellen actief houdt. Bij een tekort (X-gebonden) kunnen o.a. primaquine, dapson, sulfonamiden, nitrofurantoïne en tuinbonen een acute hemolyse uitlokken, met Heinz-lichaampjes en ‘bite cells’ in het uitstrijkje.</p>","image_url":"","wiki_title":"Glucose-6-phosphate dehydrogenase deficiency","match":"g6pd deficiëntie|g6pd-deficiëntie|favisme","option_only":true},"flagelline":{"title":"Flagelline","short":"Flagelline is het eiwit waaruit de zweepdraad (flagel) van bacteriën bestaat; TLR5 herkent het.","definition":"<p>Bacteriële <strong>flagellen</strong> maken beweging mogelijk en zijn een virulentiefactor. Het H-antigeen van Salmonella en E. coli is gebaseerd op flagelline. Eukaryote flagellen (zoals de staart van een zaadcel) zijn anders opgebouwd, uit microtubuli.</p>","image_url":"","wiki_title":"Flagellin","match":"flagelline|flagel|zweepdraad","option_only":true},"radicale cystectomie":{"title":"Radicale cystectomie","short":"Bij een radicale cystectomie wordt de blaas (met bij de man de prostaat) verwijderd, meestal bij een spierinvasief blaascarcinoom.","definition":"<p>Na een <strong>cystectomie</strong> wordt de urine afgeleid via een urostoma (Bricker) of een nieuwe blaas van darmweefsel (neoblaas). Vaak wordt vooraf neoadjuvante chemotherapie gegeven.</p>","image_url":"","wiki_title":"Cystectomy","match":"radicale cystectomie|cystectomie","option_only":true},"ovariumcarcinoom":{"title":"Ovariumcarcinoom","short":"Het ovariumcarcinoom is kanker van de eierstok, vaak laat ontdekt doordat klachten vaag zijn.","definition":"<p>Het meest voorkomende type is het hooggradig sereus carcinoom. Klachten: opgeblazen gevoel, toename van de buikomvang (ascites), vroege verzadiging en plasklachten. Risicofactoren: BRCA1/2-mutaties, Lynch-syndroom, weinig zwangerschappen. Het CA-125 is vaak verhoogd. Behandeling met chirurgie en chemotherapie.</p>","image_url":"","wiki_title":"Ovarian cancer","match":"ovariumcarcinoom|eierstokkanker","option_only":true},"ovariumtorsie":{"title":"Ovariumtorsie","short":"Bij een ovariumtorsie draait het ovarium (vaak met eileider) om zijn steel, waardoor de bloedtoevoer afknelt; een spoedgeval.","definition":"<p><strong>Torsie</strong> treedt vaker op bij een vergroot ovarium (cyste, tumor, stimulatie bij IVF). Klachten: plotselinge, hevige eenzijdige buikpijn met misselijkheid en braken. Snelle laparoscopische detorsie kan het ovarium redden.</p>","image_url":"","wiki_title":"Ovarian torsion","match":"ovariumtorsie|torsie van het ovarium|adnextorsie","option_only":true},"chlamydia-infectie":{"title":"Chlamydia trachomatis","short":"Chlamydia trachomatis is een obligaat intracellulaire bacterie en de meest voorkomende bacteriële soa.","definition":"<p><strong>Chlamydia</strong> geeft vaak geen klachten; soms urethritis, cervicitis met afscheiding of bloedverlies na gemeenschap. Complicaties zijn salpingitis met subfertiliteit en extra-uteriene zwangerschap, epididymitis en reactieve artritis. Bij pasgeborenen conjunctivitis en pneumonie. Behandeling met doxycycline of azitromycine.</p>","image_url":"","wiki_title":"Chlamydia","match":"chlamydia-infectie","option_only":true},"amoxycilline":{"title":"Amoxicilline","short":"Amoxicilline is een breedspectrum-penicilline die ook een deel van de gramnegatieve bacteriën dekt; veel gebruikt bij luchtweginfecties.","definition":"<p><strong>Amoxicilline</strong> is een aminopenicilline: een bètalactamantibioticum dat de celwandsynthese remt. Het spectrum is breder dan penicilline en omvat ook o.a. <em>H. influenzae</em> en <em>E. coli</em> (mits geen bètalactamase).</p><p>Het is in de huisartsenpraktijk eerste keus bij pneumonie en wordt ook gebruikt bij otitis en sinusitis. Met clavulaanzuur (amoxicilline-clavulaanzuur) is het ook werkzaam tegen bètalactamasevormers.</p>","image_url":"","wiki_title":"Amoxicillin","match":"amoxycilline","option_only":true},"koemelkeiwit":{"title":"Koemelkeiwitallergie","short":"Koemelkeiwitallergie is een allergische reactie op eiwitten uit koemelk, vooral bij zuigelingen.","definition":"<p>Koemelkallergie kan IgE-gemedieerd zijn (snelle reacties: urticaria, braken, zelden anafylaxie) of niet-IgE-gemedieerd (eczeem, darmklachten, bloed bij de ontlasting). Behandeling met een volledig gehydrolyseerde of aminozuurvoeding; de meeste kinderen groeien er vóór de schoolleeftijd overheen.</p>","image_url":"","wiki_title":"Milk allergy","match":"koemelkeiwit|koemelkallergie|koemelkeiwitallergie|allergie voor kunstvoeding","option_only":true},"os ischium":{"title":"Os ischii (zitbeen)","short":"Het os ischii is het onderste-achterste deel van het heupbeen, met de zitknobbel (tuber ischiadicum).","definition":"<p>Aan het <strong>tuber ischiadicum</strong> hechten de hamstrings aan; bij jonge sporters kan hier een avulsiefractuur ontstaan. Bij zitten draagt het tuber het lichaamsgewicht.</p>","image_url":"","wiki_title":"Ischium","match":"os ischium|os ischii|zitbeen|tuber ischiadicum","option_only":true},"conventionele x-thorax":{"title":"X-thorax","short":"Een X-thorax is een röntgenfoto van de borstkas; het eerste beeldvormend onderzoek bij verdenking op longafwijkingen, hartfalen of pneumothorax.","definition":"<p>Een <strong>X-thorax</strong> is een röntgenopname van de borstkas, meestal posterieur-anterieur en lateraal. Lucht is zwart, weke delen grijs en bot wit.</p><p>Het is snel, goedkoop en met een lage stralingsdosis, en wordt gebruikt om o.a. pneumonie (infiltraat), pleuravocht, pneumothorax, longtumoren, hartvergroting en tekenen van hartfalen op te sporen. Kleine of subtiele afwijkingen zijn er minder goed op te zien dan op een CT.</p>","image_url":"","wiki_title":"Chest radiograph","match":"conventionele x-thorax","option_only":true},"geconjugeerde hyperbilirubinemie":{"title":"Geconjugeerd bilirubine","short":"Geconjugeerd bilirubine is het in de lever aan glucuronzuur gekoppelde, in water oplosbare bilirubine dat via de gal wordt uitgescheiden.","definition":"<p>Een verhoogd <strong>geconjugeerd bilirubine</strong> past bij leverziekte of galwegobstructie. Omdat het in water oplosbaar is, komt het in de urine (donkere urine). Bij pasgeborenen is een verhoogd geconjugeerd bilirubine altijd afwijkend en vraagt het om onderzoek naar bijv. galgangatresie.</p>","image_url":"","wiki_title":"Bilirubin","match":"geconjugeerde hyperbilirubinemie","option_only":true},"trichomoniasi":{"title":"Trichomonas vaginalis","short":"Trichomonas vaginalis is een seksueel overdraagbare protozo die vaginitis met schuimende, groengele afscheiding veroorzaakt.","definition":"<p><strong>Trichomoniasis</strong> geeft bij vrouwen jeuk, branderigheid en riekende, schuimende afscheiding, soms met een ‘aardbeiencervix’; bij mannen meestal geen klachten. De beweeglijke flagellaten zijn soms te zien in een nat preparaat; PCR is gevoeliger. Behandeling met metronidazol, ook voor de partner.</p>","image_url":"","wiki_title":"Trichomoniasis","match":"trichomoniasi","option_only":true},"dubbelzijdige nieragenesie":{"title":"Bilaterale nieragenesie","short":"Bij bilaterale nieragenesie zijn beide nieren niet aangelegd, met ernstig tekort aan vruchtwater en longhypoplasie als gevolg.","definition":"<p>Bij <strong>bilaterale nieragenesie</strong> ontstaan de nieren niet, doordat de ureterknop niet of verkeerd met het metanefrogene mesoderm in contact komt. Er wordt geen foetale urine gemaakt, met oligo- of anhydramnion. Dat leidt tot de Potter-sequentie: longhypoplasie, een afgeplat gezicht en standsafwijkingen van de ledematen; het is niet met het leven verenigbaar.</p>","image_url":"","wiki_title":"Renal agenesis","match":"dubbelzijdige nieragenesie","option_only":true},"auto-immuun destructie van bètacellen":{"title":"Diabetes mellitus type 1","short":"Bij diabetes type 1 vernietigt het immuunsysteem de insulineproducerende bètacellen, met een absoluut insulinetekort.","definition":"<p><strong>Diabetes type 1</strong> begint meestal op jonge leeftijd, vaak met dorst, veel plassen, gewichtsverlies en soms een diabetische ketoacidose. Er zijn auto-antistoffen (bijv. tegen GAD of IA-2). Behandeling is levenslang insuline.</p>","image_url":"","wiki_title":"Type 1 diabetes","match":"auto-immuun destructie van bètacellen","option_only":true},"type 1 diabetes mellitus":{"title":"Diabetes mellitus type 1","short":"Bij diabetes type 1 vernietigt het immuunsysteem de insulineproducerende bètacellen, met een absoluut insulinetekort.","definition":"<p><strong>Diabetes type 1</strong> begint meestal op jonge leeftijd, vaak met dorst, veel plassen, gewichtsverlies en soms een diabetische ketoacidose. Er zijn auto-antistoffen (bijv. tegen GAD of IA-2). Behandeling is levenslang insuline.</p>","image_url":"","wiki_title":"Type 1 diabetes","match":"type 1 diabetes mellitus","option_only":true},"cortisol (een glucocorticoid)":{"title":"Cortisol","short":"Cortisol is het belangrijkste glucocorticoïd uit de bijnierschors; het is een stresshormoon met effecten op stofwisseling en afweer.","definition":"<p><strong>Cortisol</strong> wordt gemaakt in de zona fasciculata onder invloed van ACTH, met een dagritme (hoog in de ochtend). Het verhoogt de bloedglucose (gluconeogenese), breekt eiwitten af, remt ontsteking en afweer en ondersteunt de bloeddruk. Overmaat geeft het syndroom van Cushing, tekort bijnierinsufficiëntie (ziekte van Addison).</p>","image_url":"","wiki_title":"Cortisol","match":"cortisol (een glucocorticoid)","option_only":true},"acute pyelonefritis":{"title":"Pyelonefritis","short":"Pyelonefritis is een bacteriële infectie van het nierbekken en de nier, met koorts, flankpijn en vaak klachten van een blaasontsteking.","definition":"<p><strong>Pyelonefritis</strong> is een opstijgende urineweginfectie die de nier en het nierbekken bereikt, meestal door <em>E. coli</em>.</p><p>Kenmerkend zijn koorts, koude rillingen, flankpijn en slagpijn in de nierloge, eventueel met mictieklachten. Het is een gecompliceerde urineweginfectie die behandeld wordt met antibiotica met goede weefselpenetratie (niet nitrofurantoïne).</p>","image_url":"","wiki_title":"Pyelonephritis","match":"acute pyelonefritis","option_only":true},"velamenteuze insertie van de navelstreng":{"title":"Velamenteuze insertie van de navelstreng","short":"Bij een velamenteuze insertie hecht de navelstreng aan de vliezen in plaats van aan de placenta, waardoor de vaten onbeschermd door de vliezen lopen.","definition":"<p>Bij een <strong>velamenteuze insertie</strong> lopen de navelstrengvaten zonder gelei van Wharton door de vliezen naar de placenta. Liggen ze vóór de baarmoedermond (vasa praevia), dan kunnen ze bij het breken van de vliezen scheuren, met snel foetaal bloedverlies. Het komt vaker voor bij meerlingen en IVF.</p>","image_url":"","wiki_title":"Velamentous cord insertion","match":"velamenteuze insertie van de navelstreng","option_only":true},"mri scan":{"title":"MRI","short":"MRI maakt met een sterk magneetveld en radiogolven gedetailleerde beelden van weke delen, zonder ioniserende straling.","definition":"<p>Bij <strong>MRI</strong> worden waterstofkernen in een sterk magneetveld door radiogolven aangeslagen; het signaal bij terugkeer verschilt per weefseltype. MRI is bijzonder geschikt voor hersenen, ruggenmerg, gewrichten, weke delen en het bekken. Nadelen zijn de lange duur, kosten en beperkingen bij pacemakers en sommige metalen implantaten.</p>","image_url":"","wiki_title":"Magnetic resonance imaging","match":"mri scan","option_only":true},"ß-hcg":{"title":"hCG (humaan choriongonadotrofine)","short":"Zwangerschapshormoon uit de syncytiotrofoblast dat het corpus luteum in stand houdt.","definition":"<p><strong>hCG</strong> lijkt structureel op TSH/LH; door de α-subunit heeft het een licht schildklierstimulerend effect en verklaart mede de stijging van T4 vroeg in de zwangerschap.</p>","image_url":"","wiki_title":"Human chorionic gonadotropin","match":"ß-hcg","option_only":true},"een caput succedaneum":{"title":"Caput succedaneum","short":"Een caput succedaneum is een oedemateuze zwelling van de hoofdhuid bij de pasgeborene, die over de schedelnaden heen loopt.","definition":"<p>Het <strong>caput succedaneum</strong> ontstaat door druk tijdens de baring (of vacuümextractie) en verdwijnt binnen enkele dagen. Een cefaalhematoom daarentegen is een bloeding onder het periost, begrensd door de schedelnaden, dat weken blijft en geelzucht kan verergeren.</p>","image_url":"","wiki_title":"Caput succedaneum","match":"een caput succedaneum","option_only":true},"spermatocyt":{"title":"Spermatocyt","short":"Kiemcel in de spermatogenese; de primaire spermatocyt is diploïd en ondergaat de eerste meiotische deling tot secundaire spermatocyten.","definition":"<p>Een <strong>spermatocyt</strong> ontstaat uit een spermatogonium; na de meiose vormen zich haploïde spermatiden.</p>","image_url":"","wiki_title":"Spermatocyte","match":"spermatocyt","option_only":true},"velocardiofaciaal syndroom (deletie 22q11)":{"title":"22q11-deletiesyndroom","short":"Het 22q11-deletiesyndroom ontstaat door een microdeletie op chromosoom 22 en geeft o.a. hartafwijkingen, een gehemeltespleet, hypocalciëmie en immuunstoornissen.","definition":"<p>Bij het <strong>22q11-deletiesyndroom</strong> (DiGeorge) is de ontwikkeling van de derde en vierde kieuwzakjes verstoord. Kenmerken (‘CATCH-22’): hartafwijkingen (vooral conotruncaal, zoals Fallot en truncus arteriosus), afwijkend gezicht, hypoplasie van de thymus (T-celtekort), gehemeltespleet en hypocalciëmie door hypoplastische bijschildklieren. Op latere leeftijd is er een verhoogd risico op psychose.</p>","image_url":"","wiki_title":"DiGeorge syndrome","match":"velocardiofaciaal syndroom (deletie 22q11)","option_only":true},"lh":{"title":"LH (luteïniserend hormoon)","short":"Hypofysevoorkwabhormoon dat de ovulatie uitlokt en het corpus luteum onderhoudt; bij de man stimuleert het testosteronproductie.","definition":"<p>De <strong>LH</strong>-piek midden in de cyclus veroorzaakt de ovulatie.</p>","image_url":"","wiki_title":"Luteinizing hormone","match":"lh","option_only":true},"geavanceerd ultrageluid onderzoek (guo)":{"title":"GUO (geavanceerd ultrageluidonderzoek)","short":"Uitgebreid echografisch onderzoek naar structurele foetale afwijkingen, uitgevoerd bij verhoogde kans of afwijkende bevindingen.","definition":"<p>Het <strong>GUO</strong> is een gedetailleerde echo (type 2) die bij een verhoogd risico of afwijkende screening wordt ingezet, bv. bij <em>echogene darmen</em>.</p>","image_url":"","wiki_title":"","match":"geavanceerd ultrageluid onderzoek (guo)","option_only":true},"ct-angio":{"title":"CT-angiografie thorax","short":"CT-scan met contrast van de longvaten om een longembolie aan te tonen of uit te sluiten.","definition":"<p>Bij CTA (CT-angio) thorax worden de pulmonale arteriën met contrast in beeld gebracht; het is de gouden standaard voor het aantonen van een longembolie.</p>","image_url":"","wiki_title":"","match":"ct-angio","option_only":true},"vaginaal toucher":{"title":"Vaginaal toucher","short":"Inwendig onderzoek van portio, ontsluiting, indaling en ligging (POVIAS); gecontra-indiceerd bij placenta praevia.","definition":"<p>Bij een <strong>vaginaal toucher</strong> worden Portio, Ontsluiting, Vliezen, Indaling, Aard en Stand beoordeeld (POVIAS).</p>","image_url":"","wiki_title":"","match":"vaginaal toucher","option_only":true},"congenitale hartafwijking":{"title":"Congenitale hartafwijking","short":"Aangeboren structurele afwijking van hart of grote vaten; de meest voorkomende aangeboren afwijking bij de mens.","definition":"<p><strong>Congenitale hartafwijkingen</strong> zijn aangeboren structurele defecten van hart of grote vaten (bijv. VSD, ASD, tetralogie van Fallot). Ze komen bij ongeveer 8 per 1000 levendgeborenen voor; veel patiënten bereiken met behandeling de volwassenheid maar houden restrisico's.</p>","image_url":"","wiki_title":"Congenital heart defect","match":"congenitale hartafwijking","option_only":true},"papillaire dermis":{"title":"Dermis","short":"De lederhuid onder de epidermis: bindweefsel met collageen, bloedvaten, zenuwen, klieren en haarfollikels.","definition":"<p>De <b>dermis</b> (lederhuid) ligt onder de epidermis en bestaat uit bindweefsel met collageen en elastine.</p><p>Ze bevat bloedvaten, zenuwuiteinden, zweet- en talgklieren en haarfollikels en geeft de huid stevigheid en elasticiteit. Men onderscheidt een papillaire en een reticulaire dermis.</p>","image_url":"","wiki_title":"Dermis","match":"papillaire dermis","option_only":true},"de epidermis":{"title":"Epidermis","short":"De opperhuid: het bovenste, uit meerlagig verhoornend plaveiselepitheel opgebouwde deel van de huid.","definition":"<p>De <b>epidermis</b> (opperhuid) is de buitenste huidlaag, opgebouwd uit meerlagig verhoornend plaveiselepitheel zonder bloedvaten.</p><p>Ze bestaat vooral uit keratinocyten in opeenvolgende lagen (basale → hoornlaag) en levert de beschermende barrière.</p>","image_url":"","wiki_title":"Epidermis","match":"de epidermis","option_only":true},"bloedonderzoek (calcium)":{"title":"Calcium","short":"Mineraal dat essentieel is voor botmineralisatie, spiercontractie en zenuwgeleiding. Opname in de darm wordt bevorderd door 1,25-OH-vitamine D (calcitriol).","definition":"<p><strong>Calcium</strong> wordt in de dunne darm actief opgenomen onder invloed van 1,25-dihydroxyvitamine D. Het grootste deel van het lichaamscalcium ligt opgeslagen in het skelet als hydroxyapatiet.</p>","image_url":"","wiki_title":"Calcium in biology","match":"bloedonderzoek (calcium)","option_only":true},"dysmenorroe":{"title":"Dysmenorroe","short":"Pijnlijke menstruatie, vaak krampend onder in de buik.","definition":"<p><b>Dysmenorroe</b> is pijn tijdens de menstruatie. Primaire dysmenorroe berust op prostaglandine-gemedieerde uteruscontracties; secundaire dysmenorroe wijst op onderliggende pathologie zoals endometriose.</p>","image_url":"","wiki_title":"Dysmenorrhea","match":"dysmenorroe","option_only":true},"wet lungs":{"title":"Wet lungs (transiënte tachypneu)","short":"Voorbijgaande snelle ademhaling bij de pasgeborene door vertraagde resorptie van longvocht, vooral na een sectio.","definition":"<p><b>Wet lungs</b> (transiënte tachypneu van de neonaat) ontstaat doordat het foetale longvocht onvoldoende is geresorbeerd, vaker na een keizersnede. Het beeld is mild en zelflimiterend.</p>","image_url":"","wiki_title":"Transient tachypnea of the newborn","match":"wet lungs","option_only":true},"pid":{"title":"Salpingitis","short":"Salpingitis is een ontsteking van de eileiders, meestal door een opstijgende seksueel overdraagbare infectie.","definition":"<p><strong>Salpingitis</strong> maakt deel uit van pelvic inflammatory disease (PID) en wordt vaak veroorzaakt door <em>Chlamydia trachomatis</em> of gonokokken. Klachten: onderbuikpijn, koorts, abnormale afscheiding en slingerpijn bij vaginaal toucher. Complicaties zijn tubo-ovarieel abces, verklevingen, buitenbaarmoederlijke zwangerschap en subfertiliteit.</p>","image_url":"","wiki_title":"Salpingitis","match":"pid","option_only":true},"oxytocine":{"title":"Oxytocine","short":"Oxytocine is een hormoon uit de neurohypofyse dat de melkuitdrijving (toeschietreflex) en uteruscontracties regelt. Het onderscheidt zich van prolactine, dat de melkproductie stuurt.","definition":"<p>Hormoon dat wordt afgegeven door de achterkwab van de hypofyse. Het veroorzaakt de melkejectie tijdens borstvoeding en samentrekking van de baarmoeder tijdens de bevalling.</p>","image_url":"","wiki_title":"Oxytocin","match":"oxytocine","option_only":true},"hypoblast":{"title":"Hypoblast","short":"Het onderste kiemblad van de tweelagige kiemschijf, grenzend aan de dooierzakholte.","definition":"<p>De <strong>hypoblast</strong> draagt bij aan extra-embryonale structuren en wordt tijdens de gastrulatie grotendeels vervangen door definitief endoderm.</p>","image_url":"","wiki_title":"Hypoblast","match":"hypoblast","option_only":true},"epiblast":{"title":"Epiblast","short":"Het bovenste kiemblad van de tweelagige kiemschijf; hieruit ontstaan tijdens de gastrulatie alle drie de kiembladen.","definition":"<p>Cellen van de <strong>epiblast</strong> migreren via de primitiefstreep naar binnen en vormen ecto-, meso- en endoderm.</p>","image_url":"","wiki_title":"Epiblast","match":"epiblast","option_only":true},"neurale buis":{"title":"Neurale buis","short":"Buisvormige structuur uit de neurale plaat waaruit hersenen en ruggenmerg ontstaan.","definition":"<p>Sluiting van de <strong>neurale buis</strong> gebeurt van midden naar craniaal en caudaal; falen geeft neuralebuisdefecten.</p>","image_url":"","wiki_title":"Neural tube","match":"neurale buis","option_only":true},"combinatietest":{"title":"Combinatietest","short":"Prenatale kansbepaling op trisomie 21 met nekplooimeting plus serum-B-hCG en PAPP-A.","definition":"<p>De <strong>combinatietest</strong> combineert echografie (nekplooi) met serologie; een verhoogd B-hCG en verlaagd PAPP-A verhogen de kans op trisomie 21.</p>","image_url":"","wiki_title":"","match":"combinatietest","option_only":true},"vlokkentest":{"title":"Vlokkentest (CVS)","short":"Invasieve prenatale diagnostiek waarbij chorionvlokken worden afgenomen voor genetisch onderzoek.","definition":"<p>De <strong>vlokkentest</strong> (chorionic villus sampling) geeft vroeg (vanaf ~11 weken) zekerheid en is sneller uitvoerbaar dan de vruchtwaterpunctie.</p>","image_url":"","wiki_title":"Chorionic villus sampling","match":"vlokkentest","option_only":true},"hyaline membraanziekte":{"title":"Hyaline membraan ziekte (IRDS)","short":"Ademnoodsyndroom van de premature neonaat door surfactanttekort.","definition":"<p><strong>Hyaline membraan ziekte</strong> (infant respiratory distress syndrome) geeft kreunende ademhaling en intrekkingen; corticosteroïden antenataal verminderen het risico.</p>","image_url":"","wiki_title":"Infant respiratory distress syndrome","match":"hyaline membraanziekte","option_only":true},"sertoli-cel":{"title":"Sertoli-cel","short":"Steuncel in de wand van de tubulus seminiferus die de spermatogenese ondersteunt en de bloed-testisbarrière vormt.","definition":"<p>De <strong>Sertoli-cellen</strong> reiken van de basale membraan tot het lumen van de tubulus seminiferus en verzorgen en beschermen de zich ontwikkelende kiemcellen.</p>","image_url":"","wiki_title":"Sertoli cell","match":"sertoli-cel","option_only":true},"granulosacellen":{"title":"Granulosacellen","short":"Hormoonproducerende cellen die de follikelholte bekleden; zetten androgenen om in oestrogenen.","definition":"<p><strong>Granulosacellen</strong> reageren op FSH en vormen na de ovulatie het corpus luteum.</p>","image_url":"","wiki_title":"Granulosa cell","match":"granulosacellen","option_only":true},"pericyten":{"title":"Pericyten","short":"Contractiele cellen rond capillairen en kleine venulen die de doorbloeding en vaatwand mede reguleren.","definition":"<p><b>Pericyten</b> omhullen het endotheel van capillairen en postcapillaire venulen en dragen bij aan de vaatstabiliteit.</p>","image_url":"","wiki_title":"Pericyte","match":"pericyten","option_only":true},"gastrulatie":{"title":"Gastrulatie","short":"Proces waarbij uit de tweelagige kiemschijf de drie kiembladen (ecto-, meso-, endoderm) ontstaan.","definition":"<p>Tijdens de <strong>gastrulatie</strong> migreren epiblastcellen via de primitiefstreep naar binnen en vormen de drie kiembladen.</p>","image_url":"","wiki_title":"Gastrulation","match":"gastrulatie","option_only":true},"pelvic inflammatory disease":{"title":"Salpingitis","short":"Salpingitis is een ontsteking van de eileiders, meestal door een opstijgende seksueel overdraagbare infectie.","definition":"<p><strong>Salpingitis</strong> maakt deel uit van pelvic inflammatory disease (PID) en wordt vaak veroorzaakt door <em>Chlamydia trachomatis</em> of gonokokken. Klachten: onderbuikpijn, koorts, abnormale afscheiding en slingerpijn bij vaginaal toucher. Complicaties zijn tubo-ovarieel abces, verklevingen, buitenbaarmoederlijke zwangerschap en subfertiliteit.</p>","image_url":"","wiki_title":"Salpingitis","match":"pelvic inflammatory disease","option_only":true},"v. umbilicalis":{"title":"Vena umbilicalis","short":"Foetale navelstrengader; het obliterende restant vormt het ligamentum teres hepatis.","definition":"<p>De <b>vena umbilicalis</b> voert in de foetus zuurstofrijk bloed van de placenta naar de foetus. Na de geboorte obliteert zij tot het <i>ligamentum teres hepatis</i> (rond ligament van de lever).</p>","image_url":"","wiki_title":"Umbilical vein","match":"v. umbilicalis","option_only":true},"primordiale follikel":{"title":"Primaire follikel","short":"Een primaire follikel is een vroeg stadium van de ovariële follikel, met één laag kubische granulosacellen rond de oöcyt.","definition":"<p>Uit de <strong>primordiale follikel</strong> (afgeplatte cellen) ontstaat de primaire follikel, daarna de secundaire (meerlagig) en tertiaire (met antrum). Bij de geboorte is de voorraad primordiale follikels al aangelegd en daalt die levenslang.</p>","image_url":"","wiki_title":"Ovarian follicle","match":"primordiale follikel","option_only":true},"ctg":{"title":"CTG (cardiotocografie)","short":"Gelijktijdige registratie van de foetale hartfrequentie en de weeënactiviteit om de foetale conditie te beoordelen.","definition":"<p>Het <b>cardiotocogram (CTG)</b> registreert de foetale hartslag en uteruscontracties. Beoordeeld worden basisfrequentie, variabiliteit, acceleraties en deceleraties.</p>","image_url":"","wiki_title":"Cardiotocography","match":"ctg","option_only":true},"wet lung":{"title":"Wet lung (TTN)","short":"Transient tachypneu van de pasgeborene door vertraagde resorptie van longvocht, vooral na een sectio.","definition":"<p><strong>Wet lung</strong> (transient tachypnea of the newborn) geeft kortdurende tachypneu en intrekkingen; het herstelt doorgaans binnen enkele uren tot dagen spontaan.</p>","image_url":"","wiki_title":"Transient tachypnea of the newborn","match":"wet lung","option_only":true},"chorionholte":{"title":"Chorionholte","short":"De extra-embryonale coeloomholte tussen het chorion en de amnion/dooierzak; verdwijnt naarmate de amnionholte groeit.","definition":"<p>De <b>chorionholte</b> (extra-embryonale coeloom) omgeeft aanvankelijk de amnionholte en dooierzak. Ze wordt geleidelijk opgevuld door de zich uitzettende amnionholte.</p>","image_url":"","wiki_title":"Chorionic cavity","match":"chorionholte","option_only":true},"foetale groeivertraging":{"title":"Foetale groeivertraging (IUGR)","short":"Onvoldoende foetale groei voor de zwangerschapsduur, vaak door placenta-insufficiëntie.","definition":"<p>Bij <strong>foetale groeivertraging</strong> is de groei (buikomtrek/femurlengte) te laag; dopplermetingen van de a. umbilicalis helpen de placentafunctie te beoordelen.</p>","image_url":"","wiki_title":"Intrauterine growth restriction","match":"foetale groeivertraging","option_only":true},"crh":{"title":"CRH","short":"Corticotropin-releasing hormone uit de hypothalamus dat de hypofyse aanzet tot ACTH-afgifte.","definition":"<p><b>CRH</b> (corticotropin-releasing hormone) is het eerste hormoon van de HPA-as: het stimuleert de hypofyse tot ACTH-afgifte. Een hoog cortisol remt CRH en ACTH via negatieve feedback.</p>","image_url":"","wiki_title":"Corticotropin-releasing hormone","match":"crh","option_only":true},"persisterende pulmonale hypertensie":{"title":"Persisterende pulmonale hypertensie (PPHN)","short":"Uitblijven van de normale daling van de pulmonale vaatweerstand na de geboorte, met rechts-links shunt en cyanose.","definition":"<p>Bij <strong>PPHN</strong> blijft de druk in de longcirculatie hoog, waardoor bloed via foramen ovale en ductus arteriosus naar links shunt.</p>","image_url":"","wiki_title":"Persistent pulmonary hypertension of the newborn","match":"persisterende pulmonale hypertensie","option_only":true},"doppleronderzoek":{"title":"Doppleronderzoek","short":"Echografische meting van de bloedstroomsnelheid, bijv. in de a. umbilicalis. Een afwezige/omgekeerde einddiastolische flow wijst op ernstige placentaire insufficiëntie.","definition":"<p><strong>Echoscopisch doppleronderzoek</strong> van de a. umbilicalis beoordeelt de placentaire weerstand; <em>afwezige of reversed einddiastolische flow</em> duidt op foetale nood.</p>","image_url":"","wiki_title":"Doppler ultrasonography","match":"doppleronderzoek","option_only":true},"stuwing":{"title":"Stuwing (borst)","short":"Bilaterale, gespannen en pijnlijke borsten door melkophoping rond dag 3-4 post partum; niet infectieus.","definition":"<p><strong>Stuwing</strong> is meestal dubbelzijdig zonder duidelijke koorts, in tegenstelling tot de eenzijdige, ontstoken borst bij mastitis.</p>","image_url":"","wiki_title":"Breast engorgement","match":"stuwing","option_only":true},"parametritis":{"title":"Parametritis","short":"Ontsteking van het bindweefsel naast de uterus (parametrium), vaak als kraambedinfectie.","definition":"<p><b>Parametritis</b> is een ontsteking van het parametrium, het bindweefsel lateraal van de uterus. Als kraambedkoorts treedt ze doorgaans wat later op (na ongeveer 6-7 dagen post partum).</p>","image_url":"","wiki_title":"","match":"parametritis","option_only":true},"persisterende ductus van botalli (ductus arteriosus)":{"title":"Ductus arteriosus (Botalli)","short":"Foetaal bloedvat tussen longslagader en aorta dat de longcirculatie omzeilt; sluit normaal na de geboorte.","definition":"<p>De <b>ductus arteriosus</b> verbindt in de foetus de a. pulmonalis met de aorta (long → aorta), zodat de longen worden omzeild. Blijft hij open (persisterende ductus arteriosus), dan ontstaat een links-rechtsshunt.</p>","image_url":"","wiki_title":"Ductus arteriosus","match":"persisterende ductus van botalli (ductus arteriosus)","option_only":true},"leydigcel":{"title":"Leydig-cel","short":"Cel in het interstitium van de testis, tussen de zaadbuisjes, die onder invloed van LH testosteron produceert.","definition":"<p>De <b>Leydig-cellen</b> liggen in het bindweefsel tussen de tubuli seminiferi en zijn verantwoordelijk voor de productie van testosteron, gestimuleerd door luteïniserend hormoon (LH).</p>","image_url":"","wiki_title":"Leydig cell","match":"leydigcel","option_only":true},"abo antagonisme":{"title":"AB0-antagonisme","short":"Bij AB0-antagonisme breken maternale anti-A- of anti-B-antistoffen (IgG) de rode bloedcellen van het kind af; meestal bij een moeder met bloedgroep O en een kind met A of B.","definition":"<p>Bij <strong>AB0-antagonisme</strong> heeft de moeder meestal <em>bloedgroep O</em> en het kind bloedgroep A of B. Mensen met bloedgroep O maken van nature anti-A- en anti-B-antistoffen, waarvan een deel IgG is en de placenta kan passeren.</p><p>Die antistoffen veroorzaken hemolyse van de foetale erytrocyten, wat bij de pasgeborene leidt tot een ongeconjugeerde hyperbilirubinemie. Het verloopt meestal milder dan rhesusantagonisme en kan ook bij een eerste zwangerschap voorkomen. De directe antiglobulinetest (Coombs) bij het kind is vaak (zwak) positief.</p>","image_url":"","wiki_title":"Hemolytic disease of the newborn (ABO)","match":"abo antagonisme","option_only":true},"prikkelbare darmsyndroom":{"title":"Prikkelbare darm syndroom","short":"Functionele darmstoornis met buikpijn en wisselend ontlastingspatroon zonder aantoonbare afwijkingen.","definition":"<p>Het <b>prikkelbare darm syndroom</b> (PDS/IBS) is een diagnose per uitsluiting: buikpijn en veranderd defecatiepatroon zonder alarmsymptomen of afwijkend onderzoek.</p>","image_url":"","wiki_title":"Irritable bowel syndrome","match":"prikkelbare darmsyndroom","option_only":true},"leptine":{"title":"Leptine","short":"Verzadigingshormoon uit vetweefsel dat de eetlust remt.","definition":"<p><b>Leptine</b> wordt door adipocyten afgegeven in verhouding tot de vetmassa en onderdrukt via de hypothalamus het hongergevoel.</p>","image_url":"","wiki_title":"Leptin","match":"leptine","option_only":true},"meckel’s divertikel":{"title":"Divertikel van Meckel","short":"Het divertikel van Meckel is een restant van de ductus omphaloentericus aan het ileum; het kan bloeden, ontsteken of een obstructie veroorzaken.","definition":"<p>De ‘regel van 2’: komt bij ongeveer 2% van de mensen voor, ligt ongeveer 60 cm (2 voet) van de ileocaecaalklep, is ongeveer 5 cm lang en geeft vaak klachten vóór het 2e jaar. Het kan maagslijmvlies bevatten, met ulceratie en pijnloos rectaal bloedverlies, of als leidpunt voor invaginatie dienen.</p>","image_url":"","wiki_title":"Meckel's diverticulum","match":"meckel’s divertikel","option_only":true},"ventilatie/perfusie scan":{"title":"Ventilatie-perfusiescan","short":"Een ventilatie-perfusiescan vergelijkt met radioactieve stoffen de luchtverdeling en de doorbloeding van de longen, bijv. bij verdenking op longembolie.","definition":"<p>Bij een longembolie toont de <strong>V/Q-scan</strong> gebieden met normale ventilatie maar uitgevallen perfusie (‘mismatch’). Het wordt gebruikt als CT-angiografie niet kan (contrastallergie, nierfunctie, zwangerschap) en bij chronische trombo-embolische pulmonale hypertensie.</p>","image_url":"","wiki_title":"Ventilation/perfusion scan","match":"ventilatie/perfusie scan","option_only":true},"pre- eclampsie":{"title":"Pre-eclampsie","short":"Zwangerschapshypertensie ná 20 weken mét proteïnurie of orgaanschade. Kan overgaan in eclampsie (convulsies).","definition":"<p><strong>Pre-eclampsie</strong> is een zwangerschapscomplicatie met nieuw ontstane hypertensie na 20 weken samen met proteïnurie of tekenen van orgaanschade. Onbehandeld kan het leiden tot eclampsie (insulten) en HELLP-syndroom.</p>","image_url":"","wiki_title":"Pre-eclampsia","match":"pre- eclampsie","option_only":true},"groeivertraging":{"title":"Intra-uteriene groeivertraging","short":"Foetus die achterblijft in groei; symmetrisch (vroeg, o.a. infectie/chromosomaal) of asymmetrisch (laat, placenta-insufficiëntie).","definition":"<p><b>Intra-uteriene groeivertraging (IUGR)</b> betekent dat de foetale groei onder de verwachting blijft. Symmetrische vormen ontstaan vroeg (infecties, genetische oorzaken), asymmetrische later door placenta-insufficiëntie.</p>","image_url":"","wiki_title":"Intrauterine growth restriction","match":"groeivertraging","option_only":true},"sertolicel":{"title":"Sertoli-cel","short":"Steuncel in de wand van de tubulus seminiferus die de spermatogenese ondersteunt en de bloed-testisbarrière vormt.","definition":"<p>De <strong>Sertoli-cellen</strong> reiken van de basale membraan tot het lumen van de tubulus seminiferus en verzorgen en beschermen de zich ontwikkelende kiemcellen.</p>","image_url":"","wiki_title":"Sertoli cell","match":"sertolicel","option_only":true},"pelvic inflamatory disease (pid)":{"title":"Pelvic Inflammatory Disease (PID)","short":"Opstijgende infectie van de bovenste genitale tractus (endometrium, tubae, ovaria en peritoneum).","definition":"<p><strong>PID</strong> geeft onderbuikpijn, afscheiding en koorts; complicaties zijn een <em>tubo-ovarieel abces</em>, subfertiliteit en EUG.</p>","image_url":"","wiki_title":"Pelvic inflammatory disease","match":"pelvic inflamatory disease (pid)","option_only":true},"diverticulose":{"title":"Diverticulose","short":"Aanwezigheid van uitstulpingen (divertikels) in de colonwand, vooral in het sigmoïd; kan ontsteken tot diverticulitis.","definition":"<p><b>Diverticulose</b> zijn asymptomatische uitstulpingen van de mucosa door de colonwand (vooral sigmoïd). Ontsteking hiervan heet diverticulitis.</p>","image_url":"","wiki_title":"Diverticulosis","match":"diverticulose","option_only":true},"dunne darmobstructie":{"title":"Dunne darm obstructie","short":"Belemmering van de darmpassage in de dunne darm, met een bolle buik, braken en hyperactieve (klinkende) peristaltiek.","definition":"<p>Een <strong>dunne darm obstructie</strong> geeft koliekpijn, opgezette buik en aanvankelijk levendige, gootsteengeluid-achtige peristaltiek.</p>","image_url":"","wiki_title":"Bowel obstruction","match":"dunne darmobstructie","option_only":true},"groep-a-streptokok":{"title":"Streptococcus pyogenes (groep A-streptokok)","short":"Groep A-streptokok: grampositieve, bètahemolytische kok in ketens die o.a. keelontsteking, impetigo, erysipelas en roodvonk veroorzaakt.","definition":"<p><strong><em>Streptococcus pyogenes</em></strong> koloniseert keel en huid. Het M-eiwit beschermt tegen fagocytose; pyrogene exotoxinen veroorzaken roodvonk en het toxischeshocksyndroom. Invasieve infecties zijn o.a. cellulitis en necrotiserende fasciitis. Na een infectie kunnen immunologische complicaties optreden: acuut reuma en poststreptokokken-glomerulonefritis. Penicilline is eerste keus.</p>","image_url":"","wiki_title":"Streptococcus pyogenes","match":"groep-a-streptokok","option_only":true},"extra uteriene graviditeit":{"title":"Extra-uteriene graviditeit (EUG)","short":"Bij een extra-uteriene graviditeit nestelt het embryo zich buiten de baarmoederholte, meestal in de eileider.","definition":"<p>Risicofactoren voor een <strong>EUG</strong> zijn eerdere salpingitis (chlamydia), eerdere EUG of tubachirurgie, IUD en IVF. Klachten: amenorroe, vaginaal bloedverlies en buikpijn; bij een ruptuur een acute buik en shock. Diagnose met hCG en transvaginale echo (geen intra-uteriene zwangerschap). Behandeling: afwachten, methotrexaat of laparoscopie.</p>","image_url":"","wiki_title":"Ectopic pregnancy","match":"extra uteriene graviditeit","option_only":true},"lig. teres uteri":{"title":"Lig. teres uteri","short":"Ronde moederband; loopt van de laterale uterushoek via het lieskanaal naar de labia majora. Een restant van het gubernaculum.","definition":"<p>Het <strong>lig. teres uteri</strong> (ligamentum rotundum) verloopt van de uterushoek door het canalis inguinalis naar de labium majus en houdt de uterus in anteflexie/anteversie.</p>","image_url":"","wiki_title":"Round ligament of uterus","match":"lig. teres uteri","option_only":true},"dooierzak":{"title":"Dooierzak","short":"Vroeg-embryonale structuur betrokken bij voeding en de eerste bloedvorming; bron van de primordiale kiemcellen.","definition":"<p>De <b>dooierzak</b> speelt een rol bij de eerste hematopoëse en levert de primordiale kiemcellen. De primaire dooierzak wordt vervangen door de definitieve (secundaire) dooierzak.</p>","image_url":"","wiki_title":"Yolk sac","match":"dooierzak","option_only":true},"primipariteit":{"title":"Primipariteit","short":"Het voor de eerste keer een kind ter wereld brengen (P0 → eerste bevalling).","definition":"<p><strong>Primipariteit</strong> is op zichzelf geen oorzaak van foetale groeivertraging.</p>","image_url":"","wiki_title":"Gravidity and parity","match":"primipariteit","option_only":true},"groep-a- streptokok":{"title":"Streptococcus pyogenes (groep A-streptokok)","short":"Groep A-streptokok: grampositieve, bètahemolytische kok in ketens die o.a. keelontsteking, impetigo, erysipelas en roodvonk veroorzaakt.","definition":"<p><strong><em>Streptococcus pyogenes</em></strong> koloniseert keel en huid. Het M-eiwit beschermt tegen fagocytose; pyrogene exotoxinen veroorzaken roodvonk en het toxischeshocksyndroom. Invasieve infecties zijn o.a. cellulitis en necrotiserende fasciitis. Na een infectie kunnen immunologische complicaties optreden: acuut reuma en poststreptokokken-glomerulonefritis. Penicilline is eerste keus.</p>","image_url":"","wiki_title":"Streptococcus pyogenes","match":"groep-a- streptokok","option_only":true},"udp-glucose epimerase":{"title":"UDP-galactose-4-epimerase","short":"Dit enzym zet UDP-galactose om in UDP-glucose en is een van de stappen in de afbraak van galactose.","definition":"<p>De galactoseafbraak verloopt via galactokinase, galactose-1-fosfaat-uridyltransferase (GALT) en de <strong>epimerase</strong>. Een tekort aan GALT geeft klassieke galactosemie bij pasgeborenen (braken, icterus, leverfalen, cataract en E. coli-sepsis); daar wordt in de hielprik op gescreend.</p>","image_url":"","wiki_title":"Galactosemia","match":"udp-glucose epimerase|udp-galactose-4-epimerase|galactosemie","option_only":true},"endoderm":{"title":"Kiembladen","short":"Bij de gastrulatie ontstaan drie kiembladen: ectoderm, mesoderm en endoderm, waaruit alle weefsels ontstaan.","definition":"<p>Uit het <strong>ectoderm</strong> ontstaan o.a. de opperhuid en het zenuwstelsel; uit het <strong>endoderm</strong> het epitheel van darm, luchtwegen, lever en pancreas. Het <strong>mesoderm</strong> wordt verdeeld in axiaal (chorda), paraxiaal (somieten: spieren, wervels, dermis), intermediair (nieren en geslachtsorganen) en zijplaatmesoderm (lichaamswand, hart en bloedvaten, wand van de darm).</p>","image_url":"","wiki_title":"Germ layer","match":"endoderm|ectoderm|mesoderm|zijplaatmesoderm|paraxiaal mesoderm|intermediair mesoderm","option_only":true},"micrognatie":{"title":"Micrognathie","short":"Micrognathie is een te kleine onderkaak, die bij pasgeborenen ademhalings- en voedingsproblemen kan geven.","definition":"<p><strong>Micrognathie</strong> komt voor bij de Pierre Robin-sequentie (met terugvallende tong en gespleten gehemelte) en bij chromosomale afwijkingen zoals trisomie 18.</p>","image_url":"","wiki_title":"Micrognathism","match":"micrognatie|micrognathie|retrognathie","option_only":true},"rds":{"title":"Respiratory distress syndrome (IRDS)","short":"IRDS is ademnood bij prematuren door een tekort aan surfactant, waardoor de longblaasjes samenvallen.","definition":"<p>Bij <strong>IRDS</strong> zijn er kreunen, intrekkingen, tachypneu en een korrelig longbeeld op de foto. Corticosteroïden aan de moeder voor de bevalling versnellen de longrijping. Behandeling: CPAP en surfactant.</p>","image_url":"","wiki_title":"Infant respiratory distress syndrome","match":"rds|irds|hyaliene membraanziekte","option_only":true},"tubulus seminiferi":{"title":"Tubuli seminiferi","short":"In de tubuli seminiferi van de testis vindt de spermatogenese plaats, ondersteund door Sertolicellen.","definition":"<p><strong>Sertolicellen</strong> vormen de bloed-testisbarrière, worden aangestuurd door FSH en maken inhibine en anti-Müllerhormoon.</p>","image_url":"","wiki_title":"Seminiferous tubule","match":"tubulus seminiferi|tubuli seminiferi|sertolicel","option_only":true},"niet-vorderende uitdrijving":{"title":"Niet-vorderende uitdrijving","short":"Bij een niet-vorderende uitdrijving daalt het hoofd ondanks volledige ontsluiting en persen onvoldoende in.","definition":"<p>Oorzaken zijn zwakke weeën, een ongunstige ligging van het hoofd (bijv. achterhoofdsligging achter) of een wanverhouding. Afhankelijk van de stand kan worden gekozen voor oxytocine, een vaginale kunstverlossing (vacuüm, forceps) of een keizersnede.</p>","image_url":"","wiki_title":"","match":"niet-vorderende uitdrijving|niet-vorderende ontsluiting|stagnatie van de baring","option_only":true},"manuele placentaverwijdering":{"title":"Manuele placentaverwijdering","short":"Bij een manuele placentaverwijdering haalt de arts de placenta met de hand uit de baarmoeder als deze niet vanzelf loskomt.","definition":"<p>Bij een <strong>retentio placentae</strong> (geen geboorte van de placenta binnen 30–60 minuten) of veel bloedverlies wordt de placenta onder verdoving manueel verwijderd. Een risicofactor is een placenta accreta.</p>","image_url":"","wiki_title":"Retained placenta","match":"manuele placentaverwijdering|retentio placentae","option_only":true},"diverticulosis/itis":{"title":"Diverticulose en diverticulitis","short":"Bij diverticulose zijn er uitstulpingen van het slijmvlies door de wand van het colon; als zo'n divertikel ontsteekt, heet het diverticulitis.","definition":"<p><strong>Diverticulose</strong> komt in westerse landen vooral voor in het sigmoïd, bij ouderen en bij een vezelarm dieet. Diverticulitis geeft pijn linksonder en koorts; complicaties zijn een abces, perforatie en fistels. Divertikels kunnen ook pijnloos een forse bloeding geven.</p>","image_url":"","wiki_title":"Diverticular disease","match":"diverticulosis/itis|diverticulose|diverticulitis|divertikelbloeding in het colon","option_only":true},"cholesterolstenen":{"title":"Galstenen","short":"De meeste galstenen zijn cholesterolstenen; pigmentstenen ontstaan bij hemolyse (zwart) of infecties van de galwegen (bruin).","definition":"<p>Risicofactoren voor <strong>cholesterolstenen</strong> zijn vrouw zijn, leeftijd boven 40, overgewicht, zwangerschap, snel afvallen en bepaalde etnische achtergronden. De meeste galstenen geven geen klachten; complicaties zijn koliek, cholecystitis, choledocholithiasis, cholangitis en pancreatitis.</p>","image_url":"","wiki_title":"Gallstone","match":"cholesterolstenen|pigmentstenen|galstenen|cholelithiasis","option_only":true},"excavatio rectovesicalis":{"title":"Excavatio rectovesicalis en rectouterina","short":"De excavatio rectovesicalis (man) en rectouterina (vrouw, cavum van Douglas) zijn het laagste punt van de buikholte, waar zich vocht, bloed of pus kan verzamelen.","definition":"<p>In het <strong>cavum van Douglas</strong> is bij een echo vrij vocht te zien bij bijv. een gebarsten buitenbaarmoederlijke zwangerschap of een ovariumcyste. Een abces hier kan bij rectaal toucher pijnlijk zijn.</p>","image_url":"","wiki_title":"Rectouterine pouch","match":"excavatio rectovesicalis|excavatio rectouterina|cavum douglasi","option_only":true},"nipt":{"title":"NIPT","short":"De NIPT onderzoekt DNA van de placenta in het bloed van de zwangere op trisomie 21, 18 en 13.","definition":"<p>De <strong>NIPT</strong> is zeer gevoelig en specifiek, maar blijft een screening: een afwijkende uitslag moet worden bevestigd met een vlokkentest of vruchtwaterpunctie. De test kan vanaf 10 weken.</p>","image_url":"","wiki_title":"Non-invasive prenatal testing","match":"nipt|niet-invasieve prenatale test","option_only":true},"hsg":{"title":"Hysterosalpingografie (HSG)","short":"Bij een HSG wordt contrast via de baarmoederhals ingebracht om de baarmoederholte en de doorgankelijkheid van de eileiders op röntgenfoto's te beoordelen.","definition":"<p>Een <strong>HSG</strong> wordt gebruikt in het fertiliteitsonderzoek. Een alternatief zonder straling is een echo met schuim (HyFoSy).</p>","image_url":"","wiki_title":"Hysterosalpingography","match":"hsg|hysterosalpingografie","option_only":true},"downslant":{"title":"Dysmorfe kenmerken van het gezicht","short":"Dysmorfe kenmerken zijn afwijkingen in vorm of maat, zoals de stand van de oogspleten (up- of downslant) en de afstand tussen de ogen (hypo- of hypertelorisme).","definition":"<p>Een <strong>upslant</strong> (oogspleten schuin omhoog) en epicanthus passen bij het syndroom van Down; een downslant komt bij andere syndromen voor. Een enkel dysmorf kenmerk komt ook bij gezonde mensen voor; een combinatie kan op een syndroom wijzen.</p>","image_url":"","wiki_title":"Dysmorphic feature","match":"downslant|upslant|hypotelorisme|hypertelorisme|epicanthus","option_only":true},"klinefelter syndroom":{"title":"Klinefeltersyndroom","short":"Bij het Klinefeltersyndroom (47,XXY) hebben mannen een extra X-chromosoom, met kleine testes, onvruchtbaarheid en een laag testosteron.","definition":"<p>Kenmerken van <strong>Klinefelter</strong> zijn een lange gestalte, gynaecomastie, weinig lichaamsbeharing en soms leer- en gedragsproblemen. Het FSH en LH zijn hoog (hypergonadotroop hypogonadisme). Behandeling met testosteron.</p>","image_url":"","wiki_title":"Klinefelter syndrome","match":"klinefelter syndroom|klinefeltersyndroom|47,xxy","option_only":true},"niersteen":{"title":"Nierstenen (urolithiasis)","short":"Nierstenen ontstaan als stoffen in de urine uitkristalliseren; een steen in de ureter geeft een hevige koliekpijn.","definition":"<p>De meeste <strong>nierstenen</strong> bestaan uit calciumoxalaat. Andere soorten zijn urinezuur- (niet zichtbaar op een gewone röntgenfoto), struviet- (bij infectie met ureasevormers) en cystinestenen. Diagnose met CT zonder contrast. Stenen tot 5 mm gaan meestal vanzelf; bij koorts met een afgesloten nier is drainage een spoedgeval.</p>","image_url":"","wiki_title":"Kidney stone disease","match":"niersteen|nierstenen|urolithiasis|nefrolithiasis","option_only":true},"positief teken van mcburney":{"title":"Buikonderzoekstekens (McBurney, Murphy)","short":"Drukpijn op het punt van McBurney (rechtsonder) past bij appendicitis; bij het teken van Murphy stopt de patiënt met inademen bij druk rechtsboven, passend bij cholecystitis.","definition":"<p>Andere tekens bij <strong>appendicitis</strong> zijn loslaatpijn, het teken van Rovsing (pijn rechtsonder bij druk linksonder) en het psoas- en obturatorteken. Bij <strong>cholecystitis</strong> is het teken van Murphy positief, vaak met koorts.</p>","image_url":"","wiki_title":"McBurney's point","match":"positief teken van mcburney|teken van mcburney|teken van murphy|mcburney","option_only":true},"foley-ballonkatheter":{"title":"Foley-katheter","short":"Een Foley-katheter is een katheter met een opblaasbaar ballonnetje aan het uiteinde; in de verloskunde wordt hij gebruikt om de baarmoederhals mechanisch rijp te maken.","definition":"<p>Bij de <strong>inleiding van de baring</strong> wordt een ballonkatheter in de cervix gebracht, die door druk ontsluiting op gang brengt. Een alternatief zijn prostaglandinen (misoprostol, dinoproston). Als blaaskatheter blijft hij met de ballon in de blaas zitten.</p>","image_url":"","wiki_title":"Foley catheter","match":"foley-ballonkatheter|foley-katheter|ballonkatheter","option_only":true},"dreigende partus prematurus":{"title":"Dreigende vroeggeboorte","short":"Bij een dreigende vroeggeboorte zijn er vóór 37 weken weeën of andere tekenen dat de bevalling op gang komt.","definition":"<p>Bij een <strong>dreigende vroeggeboorte</strong> vóór 34 weken worden corticosteroïden (longrijping) en weeënremmers (nifedipine, atosiban) gegeven, en vóór 32 weken ook magnesiumsulfaat (neuroprotectie). Een korte cervix en een positieve fibronectinetest voorspellen een vroeggeboorte.</p>","image_url":"","wiki_title":"Preterm birth","match":"dreigende partus prematurus|dreigende vroeggeboorte|partus prematurus","option_only":true},"thecaluteïnecellen":{"title":"Granulosa- en thecacellen","short":"Thecacellen maken onder invloed van LH androgenen, die granulosacellen onder invloed van FSH omzetten in oestrogenen (twee-cellen-twee-gonadotrofinenmodel).","definition":"<p>Na de ovulatie worden ze <strong>luteïnecellen</strong> van het corpus luteum, dat progesteron maakt. Hoge hCG-spiegels (bijv. bij een molazwangerschap) kunnen thecaluteïnecysten geven.</p>","image_url":"","wiki_title":"Theca of follicle","match":"thecaluteïnecellen|thecacellen|granulosacellen|granulosaluteïnecellen","option_only":true},"grensstrengganglia":{"title":"Grensstreng (truncus sympathicus)","short":"De grensstreng is een keten van sympathische ganglia aan beide kanten van de wervelkolom, waarin preganglionaire vezels overschakelen.","definition":"<p>De preganglionaire sympathische neuronen liggen in het ruggenmerg van T1 tot L2. Een onderbreking van de <strong>sympathische keten</strong> in de hals (bijv. door een Pancoast-tumor) geeft het syndroom van Horner.</p>","image_url":"","wiki_title":"Sympathetic trunk","match":"grensstrengganglia|grensstreng|truncus sympathicus|paravertebrale ganglia","option_only":true},"sclerotomen":{"title":"Somieten (sclerotoom, myotoom, dermatoom)","short":"Somieten delen zich in een sclerotoom (wervels en ribben), myotoom (skeletspieren) en dermatoom (dermis van de rug).","definition":"<p>Het <strong>sclerotoom</strong> omgeeft de chorda dorsalis en het neurale buis en vormt de wervels; elk wervellichaam ontstaat uit de helften van twee aangrenzende sclerotomen. Daardoor treden de spinale zenuwen tussen de wervels uit.</p>","image_url":"","wiki_title":"Somite","match":"sclerotomen|sclerotoom|somieten|myotoom","option_only":true},"episiotomie":{"title":"Episiotomie en perineumruptuur","short":"Een episiotomie is een knip in het perineum tijdens de bevalling; een perineumruptuur is een spontane scheur, ingedeeld in vier graden.","definition":"<p>Bij een <strong>derde- of vierdegraads ruptuur</strong> (totaalruptuur) is de anale sluitspier, en bij de vierde graad ook het anaalslijmvlies, betrokken; dit moet zorgvuldig worden gehecht om incontinentie te voorkomen. Een mediolaterale episiotomie wordt gedaan bij foetale nood of een kunstverlossing.</p>","image_url":"","wiki_title":"Episiotomy","match":"episiotomie|perineumruptuur|totaalruptuur","option_only":true},"secundaire dooierzakholte":{"title":"Dooierzak","short":"De dooierzak is een embryonaal vliesje dat in de eerste weken de bloedvorming en de aanleg van de oergeslachtscellen verzorgt.","definition":"<p>De <strong>primaire dooierzak</strong> wordt vervangen door de kleinere secundaire dooierzak. Op een vroege echo is de dooierzak een van de eerste tekenen van een intra-uteriene zwangerschap. Een restant (ductus omphaloentericus) kan een divertikel van Meckel geven.</p>","image_url":"","wiki_title":"Yolk sac","match":"secundaire dooierzakholte|primaire dooierzakholte|dooierzak","option_only":true},"afgenomen variabiliteit":{"title":"CTG-kenmerken","short":"Op een CTG worden de basale hartfrequentie, de variabiliteit, acceleraties en deceleraties van het foetale hart beoordeeld.","definition":"<p><strong>Vroege deceleraties</strong> vallen samen met de wee en komen door hoofdcompressie (onschuldig). <strong>Variabele deceleraties</strong> komen door navelstrengcompressie, <strong>late deceleraties</strong> (na de top van de wee) wijzen op placentaire insufficiëntie. Een verminderde variabiliteit kan wijzen op hypoxie, maar ook op slaap of medicatie.</p>","image_url":"","wiki_title":"Cardiotocography","match":"afgenomen variabiliteit|toegenomen variabiliteit|vroege deceleraties|late deceleraties|variabele deceleraties","option_only":true},"cellen van leydig":{"title":"Leydigcellen","short":"Leydigcellen liggen in het interstitium van de testis en maken onder invloed van LH testosteron.","definition":"<p>Al in de foetale periode maken <strong>Leydigcellen</strong> testosteron, nodig voor de mannelijke ontwikkeling van de geslachtsorganen. Een Leydigceltumor kan vroege puberteit of gynaecomastie geven.</p>","image_url":"","wiki_title":"Leydig cell","match":"cellen van leydig|leydigcellen","option_only":true},"erythromycine":{"title":"Erytromycine (macroliden)","short":"Erytromycine is een macrolide-antibioticum dat de eiwitsynthese remt via het 50S-ribosoom.","definition":"<p><strong>Macroliden</strong> werken tegen streptokokken, atypische verwekkers (Mycoplasma, Chlamydia, Legionella) en kinkhoest. Erytromycine stimuleert ook de maaglediging (motilinereceptor). Bijwerkingen: maag-darmklachten, QT-verlenging en interacties via CYP3A4 (vooral erytromycine en claritromycine).</p>","image_url":"","wiki_title":"Erythromycin","match":"erythromycine|erytromycine|macroliden|azitromycine|claritromycine","option_only":true},"levofloxacine":{"title":"Fluorochinolonen","short":"Levofloxacine en ciprofloxacine zijn fluorochinolonen, die bacterieel DNA-gyrase en topo-isomerase IV remmen.","definition":"<p><strong>Fluorochinolonen</strong> werken breed, ook bij gramnegatieve bacteriën en (levofloxacine, moxifloxacine) bij luchtwegpathogenen. Ze hebben ernstige bijwerkingen: peesrupturen, QT-verlenging, aneurysma's en neuropathie, en worden daarom terughoudend gebruikt.</p>","image_url":"","wiki_title":"Fluoroquinolone","match":"levofloxacine|ciprofloxacine|moxifloxacine|fluorochinolonen","option_only":true},"anti mullerian-hormoon":{"title":"Anti-Müllerhormoon (AMH)","short":"AMH wordt gemaakt door Sertolicellen bij de mannelijke foetus en door granulosacellen van kleine follikels bij de vrouw.","definition":"<p>Bij de mannelijke foetus zorgt <strong>AMH</strong> ervoor dat de buizen van Müller (eileiders, baarmoeder) verdwijnen. Bij vrouwen is het AMH een maat voor de eicelreserve; het is hoog bij PCOS en laag bij een verminderde reserve.</p>","image_url":"","wiki_title":"Anti-Müllerian hormone","match":"anti mullerian-hormoon|amh|anti-müllerhormoon","option_only":true},"ectopia cordis":{"title":"Ectopia cordis","short":"Bij ectopia cordis ligt het hart (gedeeltelijk) buiten de borstkas door een sluitingsdefect van de borstwand.","definition":"<p><strong>Ectopia cordis</strong> is zeer zeldzaam, gaat vaak samen met andere afwijkingen (pentalogie van Cantrell) en heeft een slechte prognose.</p>","image_url":"","wiki_title":"Ectopia cordis","match":"ectopia cordis","option_only":true},"sirenomelie (“zeemeerminnensyndroom”)":{"title":"Sirenomelie","short":"Bij sirenomelie zijn de benen van de foetus samengegroeid, door een ernstig ontwikkelingsdefect van het caudale deel van het embryo.","definition":"<p><strong>Sirenomelie</strong> gaat meestal samen met afwezige nieren en is vrijwel altijd dodelijk. Het hoort bij het spectrum van het caudale-regressiesyndroom, dat vaker voorkomt bij diabetes van de moeder.</p>","image_url":"","wiki_title":"Sirenomelia","match":"sirenomelie (“zeemeerminnensyndroom”)|sirenomelie","option_only":true},"d-dimeer bepalen":{"title":"D-dimeer","short":"D-dimeer is een afbraakproduct van fibrine; een normale waarde maakt trombose of longembolie onwaarschijnlijk bij een laag klinisch risico.","definition":"<p><strong>D-dimeer</strong> is gevoelig maar niet specifiek: het is ook verhoogd na operaties, bij infecties, kanker, zwangerschap en ouderdom. Daarom wordt het alleen gebruikt in combinatie met een beslisregel (Wells, YEARS).</p>","image_url":"","wiki_title":"D-dimer","match":"d-dimeer bepalen|d-dimeer|d-dimeren","option_only":true},"sua":{"title":"Single umbilical artery (SUA)","short":"Bij een SUA heeft de navelstreng maar één arterie in plaats van twee.","definition":"<p>Een <strong>SUA</strong> komt bij ongeveer 1% van de zwangerschappen voor. Meestal is het een geïsoleerde bevinding, maar het gaat vaker samen met afwijkingen van nieren en hart en met groeivertraging; daarom volgt uitgebreid echoscopisch onderzoek.</p>","image_url":"","wiki_title":"Single umbilical artery","match":"sua|single umbilical artery|enkele navelstrengarterie","option_only":true},"fysiologische icterus":{"title":"Icterus neonatorum","short":"Fysiologische icterus is een lichte geelzucht bij pasgeborenen vanaf dag 2–3, door een snelle afbraak van rode bloedcellen en een onrijpe leverconjugatie.","definition":"<p>Een <strong>icterus in de eerste 24 uur</strong> is nooit fysiologisch (denk aan bloedgroepantagonisme). Moedermelkicterus kan weken aanhouden en is meestal onschuldig. Bij een icterus na twee weken moet een geconjugeerde hyperbilirubinemie (galgangatresie) worden uitgesloten. Behandeling met fototherapie volgens de bilirubinecurven.</p>","image_url":"","wiki_title":"Neonatal jaundice","match":"fysiologische icterus|icterus neonatorum|borstvoedingsicterus|moedermelkicterus","option_only":true},"glandula bulbo-urethales":{"title":"Glandulae bulbourethrales (klieren van Cowper)","short":"De klieren van Cowper liggen onder de prostaat en maken een helder slijm dat de urethra vóór de zaadlozing smeert en neutraliseert.","definition":"<p>Bij de vrouw zijn de <strong>klieren van Bartholin</strong> het equivalent; afsluiting daarvan geeft een bartholinicyste of -abces.</p>","image_url":"","wiki_title":"Bulbourethral gland","match":"glandula bulbo-urethales|glandulae bulbourethrales|klieren van cowper","option_only":true},"torsie van een adnex":{"title":"Adnextorsie","short":"Bij een adnextorsie draait het ovarium (met eileider) om zijn steel, waardoor de bloedtoevoer afknelt; een gynaecologisch spoedgeval.","definition":"<p>Een <strong>adnextorsie</strong> geeft plotselinge, hevige eenzijdige onderbuikpijn met misselijkheid en braken, vaak bij een vergroot ovarium (cyste, tumor). Behandeling: snelle laparoscopie om het ovarium terug te draaien en te sparen.</p>","image_url":"","wiki_title":"Ovarian torsion","match":"torsie van een adnex|adnextorsie|ovariumtorsie","option_only":true},"primitieve knoop":{"title":"Primitieve streep en knoop","short":"De primitieve streep met de primitieve knoop verschijnt in de derde week op de kiemschijf; hier begint de gastrulatie.","definition":"<p>Via de <strong>primitieve streep</strong> migreren cellen naar binnen om mesoderm en endoderm te vormen. Uit de primitieve knoop ontstaat de chorda dorsalis. Restanten van de primitieve streep kunnen een sacrococcygeaal teratoom geven.</p>","image_url":"","wiki_title":"Primitive streak","match":"primitieve knoop|primitieve streep|knoop van hensen","option_only":true},"amnion":{"title":"Amnion","short":"Het amnion is het binnenste vruchtvlies dat de amnionholte met vruchtwater rond het embryo vormt.","definition":"<p>Het <strong>amnion</strong> ligt tegen het buitenste vlies, het chorion. Het vruchtwater beschermt de foetus en is nodig voor de ontwikkeling van longen en ledematen. Losgescheurde strengen van het amnion kunnen ledematen afknellen (amniotische strengen).</p>","image_url":"","wiki_title":"Amnion","match":"amnion|amnionholte|vruchtvliezen","option_only":true},"groep- b- streptokok":{"title":"Groep B-streptokok (GBS)","short":"De groep B-streptokok (Streptococcus agalactiae) komt bij veel vrouwen in vagina en darm voor en kan bij pasgeborenen sepsis en meningitis veroorzaken.","definition":"<p>Bij risicofactoren (vroeggeboorte, langdurig gebroken vliezen, koorts tijdens de bevalling, een eerder kind met GBS-ziekte) krijgt de moeder antibiotica tijdens de bevalling. Bij volwassenen geeft <strong>GBS</strong> soms urineweginfecties en huidinfecties.</p>","image_url":"","wiki_title":"Streptococcus agalactiae","match":"groep- b- streptokok|groep b-streptokok|streptococcus agalactiae","option_only":true},"tunica albuginea":{"title":"Tunica albuginea","short":"De tunica albuginea is een stevig bindweefselkapsel rond de testis, het ovarium en de zwellichamen van de penis.","definition":"<p>Bij een <strong>peniele fractuur</strong> scheurt de tunica albuginea rond het corpus cavernosum. Bij de ziekte van Peyronie ontstaan bindweefselplaques in deze laag, met een kromstand.</p>","image_url":"","wiki_title":"Tunica albuginea","match":"tunica albuginea","option_only":true},"lig. sacrouterina":{"title":"Ligamenta van de uterus","short":"De uterus wordt op zijn plaats gehouden door o.a. de ligg. sacrouterina, de ligg. cardinalia en het bekkenbodemspierstelsel.","definition":"<p>Het <strong>lig. cardinale</strong> (Mackenrodt) bevat de a. uterina. Het lig. teres uteri loopt door het lieskanaal. Verzwakking van deze steunstructuren draagt bij aan een prolaps.</p>","image_url":"","wiki_title":"Uterosacral ligament","match":"lig. sacrouterina|lig. sacrouterinum|lig. cardinale|lig. teres uteri|lig. latum","option_only":true},"meningocele":{"title":"Meningokèle en spina bifida","short":"Bij een meningokèle puilen alleen de hersenvliezen uit door een defect in de wervelboog; bij een myelomeningokèle ook het ruggenmerg en de zenuwwortels.","definition":"<p>Een <strong>myelomeningokèle</strong> geeft verlamming en gevoelsverlies van de benen, blaas- en darmstoornissen en vaak hydrocefalus (Arnold-Chiari II). Foliumzuur rond de conceptie verlaagt het risico op neuraalbuisdefecten. Een spina bifida occulta geeft meestal geen klachten.</p>","image_url":"","wiki_title":"Spina bifida","match":"meningocele|meningokèle|myelomeningokèle|spina bifida","option_only":true},"sectio caesarea":{"title":"Sectio caesarea (keizersnede)","short":"Bij een sectio caesarea wordt het kind via een snede in buikwand en baarmoeder geboren.","definition":"<p>Na een eerdere <strong>keizersnede</strong> is er bij een volgende vaginale bevalling een klein risico op een uterusruptuur en is er een verhoogd risico op placenta praevia en accreta. Complicaties van de ingreep zelf zijn bloeding, infectie en trombose.</p>","image_url":"","wiki_title":"Caesarean section","match":"sectio caesarea|keizersnede|sectio in voorgeschiedenis","option_only":true},"dhea":{"title":"DHEA (dehydro-epiandrosteron)","short":"DHEA is een zwak androgeen uit de zona reticularis van de bijnierschors, dat in de weefsels kan worden omgezet in testosteron en oestrogeen.","definition":"<p>Een sterk verhoogd <strong>DHEA-S</strong> wijst bij hirsutisme op een androgene bron in de bijnier (tumor of congenitale bijnierhyperplasie). In de zwangerschap levert DHEA-S van de foetus de grondstof voor oestriol in de placenta.</p>","image_url":"","wiki_title":"Dehydroepiandrosterone","match":"dhea|dhea-s|dehydro-epiandrosteron","option_only":true},"overstimulatie":{"title":"Ovarieel hyperstimulatiesyndroom (OHSS)","short":"OHSS is een complicatie van hormoonbehandeling bij IVF, met vergrote ovaria en vochtlekkage naar de buikholte.","definition":"<p>Bij <strong>OHSS</strong> zijn er buikpijn, een opgezette buik, ascites, hemoconcentratie en een verhoogd risico op trombose. Het wordt uitgelokt door hCG. Risicofactoren zijn PCOS, een jonge leeftijd en een hoog AMH.</p>","image_url":"","wiki_title":"Ovarian hyperstimulation syndrome","match":"overstimulatie|hyperstimulatie|ohss|ovarieel hyperstimulatiesyndroom","option_only":true},"strippen":{"title":"Strippen van de vliezen","short":"Bij strippen maakt de verloskundige met een vinger de vliezen los van de onderkant van de baarmoeder, om de bevalling op gang te helpen.","definition":"<p>Door <strong>strippen</strong> komen prostaglandinen vrij. Het wordt vanaf 39–41 weken aangeboden om een inleiding te voorkomen en kan wat ongemak en bloedverlies geven.</p>","image_url":"","wiki_title":"Membrane sweep","match":"strippen|membraanstrippen","option_only":true},"randvenebloeding":{"title":"Randsinusbloeding","short":"Een randsinusbloeding is een bloeding uit de rand van de placenta, met (meestal) pijnloos vaginaal bloedverlies.","definition":"<p>Een <strong>randsinusbloeding</strong> wordt vaak achteraf vastgesteld; eerst moeten een placenta praevia en een abruptio placentae worden uitgesloten. Het risico op vroeggeboorte is iets verhoogd.</p>","image_url":"","wiki_title":"","match":"randvenebloeding|randsinusbloeding|marginale bloeding","option_only":true},"innestelingsbloeding":{"title":"Innestelingsbloeding","short":"Een innestelingsbloeding is licht bloedverlies rond het moment van de verwachte menstruatie, als de bevruchte eicel zich in het baarmoederslijmvlies nestelt.","definition":"<p>Een <strong>innestelingsbloeding</strong> is onschuldig, maar kan tot een verkeerd geschatte zwangerschapsduur leiden. Daarom wordt de termijn bepaald met een vroege echo.</p>","image_url":"","wiki_title":"Implantation bleeding","match":"innestelingsbloeding|nidatiebloeding","option_only":true},"stuitligging":{"title":"Stuitligging","short":"Bij een stuitligging ligt het kind met de billen of voeten naar beneden in plaats van met het hoofd.","definition":"<p>Rond 35–36 weken wordt bij een <strong>stuitligging</strong> een uitwendige versie aangeboden. Lukt dat niet, dan kan worden gekozen tussen een vaginale stuitbevalling en een geplande keizersnede. Een stuitligging is een risicofactor voor heupdysplasie; daarom volgt een echo van de heupen bij het kind.</p>","image_url":"","wiki_title":"Breech birth","match":"stuitligging|uitwendige versie","option_only":true},"cervixpoliep":{"title":"Cervixpoliep","short":"Een cervixpoliep is een goedaardig uitgroeisel van het slijmvlies van de baarmoederhals, dat contactbloedingen kan geven.","definition":"<p>Een <strong>cervixpoliep</strong> is bij speculumonderzoek te zien als een rood, glad uitsteeksel uit de cervixopening. Meestal wordt hij eenvoudig weggedraaid en histologisch onderzocht.</p>","image_url":"","wiki_title":"Cervical polyp","match":"cervixpoliep","option_only":true},"a. ovarica":{"title":"A. ovarica en a. uterina","short":"De a. ovarica ontspringt direct uit de aorta en loopt via het lig. suspensorium ovarii; de a. uterina is een tak van de a. iliaca interna.","definition":"<p>In de zwangerschap verwijden de spiraalarteriën zich sterk; een gestoorde ombouw hangt samen met pre-eclampsie en groeivertraging (afwijkende doppler van de a. uterina). De a. vesicalis inferior voorziet blaas en prostaat.</p>","image_url":"","wiki_title":"Ovarian artery","match":"a. ovarica|a. uterina|maternale a. uterina|a. vesicalis inferior","option_only":true},"vaginale cerclage":{"title":"Cerclage","short":"Bij een cerclage wordt een hechting rond de baarmoederhals gelegd om te voorkomen dat die voortijdig opengaat.","definition":"<p>Een <strong>cerclage</strong> wordt gedaan bij cervixinsufficiëntie, bijv. bij eerdere vroeggeboorten met een korte cervix. Rond 36–37 weken of bij weeën wordt de hechting verwijderd.</p>","image_url":"","wiki_title":"Cervical cerclage","match":"vaginale cerclage|cerclage","option_only":true},"meconium houdend vruchtwater":{"title":"Meconiumhoudend vruchtwater","short":"Meconiumhoudend vruchtwater is groen gekleurd door de eerste ontlasting van het kind, vaak bij een serotiene zwangerschap of foetale nood.","definition":"<p>Bij <strong>meconium</strong> in het vruchtwater wordt de baring nauwkeuriger bewaakt (CTG). Het kind kan meconium inademen (meconiumaspiratiesyndroom), met ademnood en pulmonale hypertensie.</p>","image_url":"","wiki_title":"Meconium aspiration syndrome","match":"meconium houdend vruchtwater|meconiumhoudend vruchtwater|meconiumaspiratie","option_only":true},"lactose":{"title":"Lactose (melksuiker)","short":"Lactose is een disacharide van glucose en galactose, die door het enzym lactase in de dunne darm wordt gesplitst.","definition":"<p>Bij <strong>lactose-intolerantie</strong> komt onverteerde lactose in het colon, waar bacteriën het vergisten, met winderigheid, buikpijn en diarree. Primaire lactasedeficiëntie (afname na het spenen) is wereldwijd het meest voorkomend; secundaire vormen ontstaan na darmbeschadiging.</p>","image_url":"","wiki_title":"Lactose","match":"lactose|melksuiker","option_only":true},"viscerale en pariëtale peritoneum":{"title":"Peritoneum viscerale en parietale","short":"Het buikvlies bestaat uit het pariëtale blad, dat de buikwand bekleedt, en het viscerale blad, dat de organen bedekt.","definition":"<p>Het <strong>pariëtale peritoneum</strong> is somatisch geïnnerveerd en goed lokaliseerbaar pijngevoelig (loslaatpijn, défense bij peritonitis). Het <strong>viscerale peritoneum</strong> is autonoom geïnnerveerd en geeft vage, slecht lokaliseerbare pijn.</p>","image_url":"","wiki_title":"Peritoneum","match":"viscerale en pariëtale peritoneum","option_only":true},"ectoderm":{"title":"Kiembladen","short":"Bij de gastrulatie ontstaan drie kiembladen: ectoderm, mesoderm en endoderm, waaruit alle weefsels ontstaan.","definition":"<p>Uit het <strong>ectoderm</strong> ontstaan o.a. de opperhuid en het zenuwstelsel; uit het <strong>endoderm</strong> het epitheel van darm, luchtwegen, lever en pancreas. Het <strong>mesoderm</strong> wordt verdeeld in axiaal (chorda), paraxiaal (somieten: spieren, wervels, dermis), intermediair (nieren en geslachtsorganen) en zijplaatmesoderm (lichaamswand, hart en bloedvaten, wand van de darm).</p>","image_url":"","wiki_title":"Germ layer","match":"ectoderm","option_only":true},"zijplaat mesoderm":{"title":"Kiembladen","short":"Bij de gastrulatie ontstaan drie kiembladen: ectoderm, mesoderm en endoderm, waaruit alle weefsels ontstaan.","definition":"<p>Uit het <strong>ectoderm</strong> ontstaan o.a. de opperhuid en het zenuwstelsel; uit het <strong>endoderm</strong> het epitheel van darm, luchtwegen, lever en pancreas. Het <strong>mesoderm</strong> wordt verdeeld in axiaal (chorda), paraxiaal (somieten: spieren, wervels, dermis), intermediair (nieren en geslachtsorganen) en zijplaatmesoderm (lichaamswand, hart en bloedvaten, wand van de darm).</p>","image_url":"","wiki_title":"Germ layer","match":"zijplaat mesoderm","option_only":true},"zijplaatmesoderm":{"title":"Kiembladen","short":"Bij de gastrulatie ontstaan drie kiembladen: ectoderm, mesoderm en endoderm, waaruit alle weefsels ontstaan.","definition":"<p>Uit het <strong>ectoderm</strong> ontstaan o.a. de opperhuid en het zenuwstelsel; uit het <strong>endoderm</strong> het epitheel van darm, luchtwegen, lever en pancreas. Het <strong>mesoderm</strong> wordt verdeeld in axiaal (chorda), paraxiaal (somieten: spieren, wervels, dermis), intermediair (nieren en geslachtsorganen) en zijplaatmesoderm (lichaamswand, hart en bloedvaten, wand van de darm).</p>","image_url":"","wiki_title":"Germ layer","match":"zijplaatmesoderm","option_only":true},"axiale mesoderm":{"title":"Kiembladen","short":"Bij de gastrulatie ontstaan drie kiembladen: ectoderm, mesoderm en endoderm, waaruit alle weefsels ontstaan.","definition":"<p>Uit het <strong>ectoderm</strong> ontstaan o.a. de opperhuid en het zenuwstelsel; uit het <strong>endoderm</strong> het epitheel van darm, luchtwegen, lever en pancreas. Het <strong>mesoderm</strong> wordt verdeeld in axiaal (chorda), paraxiaal (somieten: spieren, wervels, dermis), intermediair (nieren en geslachtsorganen) en zijplaatmesoderm (lichaamswand, hart en bloedvaten, wand van de darm).</p>","image_url":"","wiki_title":"Germ layer","match":"axiale mesoderm","option_only":true},"intermediaire mesoderm":{"title":"Kiembladen","short":"Bij de gastrulatie ontstaan drie kiembladen: ectoderm, mesoderm en endoderm, waaruit alle weefsels ontstaan.","definition":"<p>Uit het <strong>ectoderm</strong> ontstaan o.a. de opperhuid en het zenuwstelsel; uit het <strong>endoderm</strong> het epitheel van darm, luchtwegen, lever en pancreas. Het <strong>mesoderm</strong> wordt verdeeld in axiaal (chorda), paraxiaal (somieten: spieren, wervels, dermis), intermediair (nieren en geslachtsorganen) en zijplaatmesoderm (lichaamswand, hart en bloedvaten, wand van de darm).</p>","image_url":"","wiki_title":"Germ layer","match":"intermediaire mesoderm","option_only":true},"hyaliene mebraanziekte":{"title":"Respiratory distress syndrome (IRDS)","short":"IRDS is ademnood bij prematuren door een tekort aan surfactant, waardoor de longblaasjes samenvallen.","definition":"<p>Bij <strong>IRDS</strong> zijn er kreunen, intrekkingen, tachypneu en een korrelig longbeeld op de foto. Corticosteroïden aan de moeder voor de bevalling versnellen de longrijping. Behandeling: CPAP en surfactant.</p>","image_url":"","wiki_title":"Infant respiratory distress syndrome","match":"hyaliene mebraanziekte","option_only":true},"neonatale wet lung":{"title":"Respiratory distress syndrome (IRDS)","short":"IRDS is ademnood bij prematuren door een tekort aan surfactant, waardoor de longblaasjes samenvallen.","definition":"<p>Bij <strong>IRDS</strong> zijn er kreunen, intrekkingen, tachypneu en een korrelig longbeeld op de foto. Corticosteroïden aan de moeder voor de bevalling versnellen de longrijping. Behandeling: CPAP en surfactant.</p>","image_url":"","wiki_title":"Infant respiratory distress syndrome","match":"neonatale wet lung","option_only":true},"upslant":{"title":"Dysmorfe kenmerken van het gezicht","short":"Dysmorfe kenmerken zijn afwijkingen in vorm of maat, zoals de stand van de oogspleten (up- of downslant) en de afstand tussen de ogen (hypo- of hypertelorisme).","definition":"<p>Een <strong>upslant</strong> (oogspleten schuin omhoog) en epicanthus passen bij het syndroom van Down; een downslant komt bij andere syndromen voor. Een enkel dysmorf kenmerk komt ook bij gezonde mensen voor; een combinatie kan op een syndroom wijzen.</p>","image_url":"","wiki_title":"Dysmorphic feature","match":"upslant","option_only":true},"hypotelorisme":{"title":"Dysmorfe kenmerken van het gezicht","short":"Dysmorfe kenmerken zijn afwijkingen in vorm of maat, zoals de stand van de oogspleten (up- of downslant) en de afstand tussen de ogen (hypo- of hypertelorisme).","definition":"<p>Een <strong>upslant</strong> (oogspleten schuin omhoog) en epicanthus passen bij het syndroom van Down; een downslant komt bij andere syndromen voor. Een enkel dysmorf kenmerk komt ook bij gezonde mensen voor; een combinatie kan op een syndroom wijzen.</p>","image_url":"","wiki_title":"Dysmorphic feature","match":"hypotelorisme","option_only":true},"excavatio recto-vesicalis":{"title":"Excavatio rectovesicalis en rectouterina","short":"De excavatio rectovesicalis (man) en rectouterina (vrouw, cavum van Douglas) zijn het laagste punt van de buikholte, waar zich vocht, bloed of pus kan verzamelen.","definition":"<p>In het <strong>cavum van Douglas</strong> is bij een echo vrij vocht te zien bij bijv. een gebarsten buitenbaarmoederlijke zwangerschap of een ovariumcyste. Een abces hier kan bij rectaal toucher pijnlijk zijn.</p>","image_url":"","wiki_title":"Rectouterine pouch","match":"excavatio recto-vesicalis","option_only":true},"positief teken van murphy":{"title":"Buikonderzoekstekens (McBurney, Murphy)","short":"Drukpijn op het punt van McBurney (rechtsonder) past bij appendicitis; bij het teken van Murphy stopt de patiënt met inademen bij druk rechtsboven, passend bij cholecystitis.","definition":"<p>Andere tekens bij <strong>appendicitis</strong> zijn loslaatpijn, het teken van Rovsing (pijn rechtsonder bij druk linksonder) en het psoas- en obturatorteken. Bij <strong>cholecystitis</strong> is het teken van Murphy positief, vaak met koorts.</p>","image_url":"","wiki_title":"McBurney's point","match":"positief teken van murphy","option_only":true},"primaire dooierzakholte":{"title":"Dooierzak","short":"De dooierzak is een embryonaal vliesje dat in de eerste weken de bloedvorming en de aanleg van de oergeslachtscellen verzorgt.","definition":"<p>De <strong>primaire dooierzak</strong> wordt vervangen door de kleinere secundaire dooierzak. Op een vroege echo is de dooierzak een van de eerste tekenen van een intra-uteriene zwangerschap. Een restant (ductus omphaloentericus) kan een divertikel van Meckel geven.</p>","image_url":"","wiki_title":"Yolk sac","match":"primaire dooierzakholte","option_only":true},"vroege deceleraties":{"title":"CTG-kenmerken","short":"Op een CTG worden de basale hartfrequentie, de variabiliteit, acceleraties en deceleraties van het foetale hart beoordeeld.","definition":"<p><strong>Vroege deceleraties</strong> vallen samen met de wee en komen door hoofdcompressie (onschuldig). <strong>Variabele deceleraties</strong> komen door navelstrengcompressie, <strong>late deceleraties</strong> (na de top van de wee) wijzen op placentaire insufficiëntie. Een verminderde variabiliteit kan wijzen op hypoxie, maar ook op slaap of medicatie.</p>","image_url":"","wiki_title":"Cardiotocography","match":"vroege deceleraties","option_only":true},"toegenomen variabiliteit":{"title":"CTG-kenmerken","short":"Op een CTG worden de basale hartfrequentie, de variabiliteit, acceleraties en deceleraties van het foetale hart beoordeeld.","definition":"<p><strong>Vroege deceleraties</strong> vallen samen met de wee en komen door hoofdcompressie (onschuldig). <strong>Variabele deceleraties</strong> komen door navelstrengcompressie, <strong>late deceleraties</strong> (na de top van de wee) wijzen op placentaire insufficiëntie. Een verminderde variabiliteit kan wijzen op hypoxie, maar ook op slaap of medicatie.</p>","image_url":"","wiki_title":"Cardiotocography","match":"toegenomen variabiliteit","option_only":true},"cel van leydig":{"title":"Leydigcellen","short":"Leydigcellen liggen in het interstitium van de testis en maken onder invloed van LH testosteron.","definition":"<p>Al in de foetale periode maken <strong>Leydigcellen</strong> testosteron, nodig voor de mannelijke ontwikkeling van de geslachtsorganen. Een Leydigceltumor kan vroege puberteit of gynaecomastie geven.</p>","image_url":"","wiki_title":"Leydig cell","match":"cel van leydig","option_only":true},"groep-b-streptokok":{"title":"Groep B-streptokok (GBS)","short":"De groep B-streptokok (Streptococcus agalactiae) komt bij veel vrouwen in vagina en darm voor en kan bij pasgeborenen sepsis en meningitis veroorzaken.","definition":"<p>Bij risicofactoren (vroeggeboorte, langdurig gebroken vliezen, koorts tijdens de bevalling, een eerder kind met GBS-ziekte) krijgt de moeder antibiotica tijdens de bevalling. Bij volwassenen geeft <strong>GBS</strong> soms urineweginfecties en huidinfecties.</p>","image_url":"","wiki_title":"Streptococcus agalactiae","match":"groep-b-streptokok","option_only":true},"episiotomie of perineumruptuur":{"title":"Episiotomie en perineumruptuur","short":"Een episiotomie is een knip in het perineum tijdens de bevalling; een perineumruptuur is een spontane scheur, ingedeeld in vier graden.","definition":"<p>Bij een <strong>derde- of vierdegraads ruptuur</strong> (totaalruptuur) is de anale sluitspier, en bij de vierde graad ook het anaalslijmvlies, betrokken; dit moet zorgvuldig worden gehecht om incontinentie te voorkomen. Een mediolaterale episiotomie wordt gedaan bij foetale nood of een kunstverlossing.</p>","image_url":"","wiki_title":"Episiotomy","match":"episiotomie of perineumruptuur","option_only":true},"perineum letsel":{"title":"Episiotomie en perineumruptuur","short":"Een episiotomie is een knip in het perineum tijdens de bevalling; een perineumruptuur is een spontane scheur, ingedeeld in vier graden.","definition":"<p>Bij een <strong>derde- of vierdegraads ruptuur</strong> (totaalruptuur) is de anale sluitspier, en bij de vierde graad ook het anaalslijmvlies, betrokken; dit moet zorgvuldig worden gehecht om incontinentie te voorkomen. Een mediolaterale episiotomie wordt gedaan bij foetale nood of een kunstverlossing.</p>","image_url":"","wiki_title":"Episiotomy","match":"perineum letsel","option_only":true},"geconjugeerd hyperbilirubinemie":{"title":"Geconjugeerd bilirubine","short":"Geconjugeerd bilirubine is het in de lever aan glucuronzuur gekoppelde, in water oplosbare bilirubine dat via de gal wordt uitgescheiden.","definition":"<p>Een verhoogd <strong>geconjugeerd bilirubine</strong> past bij leverziekte of galwegobstructie. Omdat het in water oplosbaar is, komt het in de urine (donkere urine). Bij pasgeborenen is een verhoogd geconjugeerd bilirubine altijd afwijkend en vraagt het om onderzoek naar bijv. galgangatresie.</p>","image_url":"","wiki_title":"Bilirubin","match":"geconjugeerd hyperbilirubinemie","option_only":true},"icterus prolongatus door moedermelk":{"title":"Icterus neonatorum","short":"Fysiologische icterus is een lichte geelzucht bij pasgeborenen vanaf dag 2–3, door een snelle afbraak van rode bloedcellen en een onrijpe leverconjugatie.","definition":"<p>Een <strong>icterus in de eerste 24 uur</strong> is nooit fysiologisch (denk aan bloedgroepantagonisme). Moedermelkicterus kan weken aanhouden en is meestal onschuldig. Bij een icterus na twee weken moet een geconjugeerde hyperbilirubinemie (galgangatresie) worden uitgesloten. Behandeling met fototherapie volgens de bilirubinecurven.</p>","image_url":"","wiki_title":"Neonatal jaundice","match":"icterus prolongatus door moedermelk","option_only":true},"gentamycine":{"title":"Gentamicine (aminoglycosiden)","short":"Gentamicine is een aminoglycoside dat werkt tegen gramnegatieve bacteriën door de eiwitsynthese via het 30S-ribosoom te verstoren.","definition":"<p><strong>Aminoglycosiden</strong> werken concentratieafhankelijk en worden vaak eenmaal daags gegeven, met spiegelbepalingen. Bijwerkingen zijn nefrotoxiciteit en (blijvende) ototoxiciteit. Ze werken niet tegen anaeroben.</p>","image_url":"","wiki_title":"Gentamicin","match":"gentamycine","option_only":true},"sepsis door groep-a-streptokokken":{"title":"Streptococcus pyogenes (groep A-streptokok)","short":"Groep A-streptokok: grampositieve, bètahemolytische kok in ketens die o.a. keelontsteking, impetigo, erysipelas en roodvonk veroorzaakt.","definition":"<p><strong><em>Streptococcus pyogenes</em></strong> koloniseert keel en huid. Het M-eiwit beschermt tegen fagocytose; pyrogene exotoxinen veroorzaken roodvonk en het toxischeshocksyndroom. Invasieve infecties zijn o.a. cellulitis en necrotiserende fasciitis. Na een infectie kunnen immunologische complicaties optreden: acuut reuma en poststreptokokken-glomerulonefritis. Penicilline is eerste keus.</p>","image_url":"","wiki_title":"Streptococcus pyogenes","match":"sepsis door groep-a-streptokokken","option_only":true},"sepsis door een groep-a-streptokok":{"title":"Streptococcus pyogenes (groep A-streptokok)","short":"Groep A-streptokok: grampositieve, bètahemolytische kok in ketens die o.a. keelontsteking, impetigo, erysipelas en roodvonk veroorzaakt.","definition":"<p><strong><em>Streptococcus pyogenes</em></strong> koloniseert keel en huid. Het M-eiwit beschermt tegen fagocytose; pyrogene exotoxinen veroorzaken roodvonk en het toxischeshocksyndroom. Invasieve infecties zijn o.a. cellulitis en necrotiserende fasciitis. Na een infectie kunnen immunologische complicaties optreden: acuut reuma en poststreptokokken-glomerulonefritis. Penicilline is eerste keus.</p>","image_url":"","wiki_title":"Streptococcus pyogenes","match":"sepsis door een groep-a-streptokok","option_only":true},"groep a streptococci":{"title":"Streptococcus pyogenes (groep A-streptokok)","short":"Groep A-streptokok: grampositieve, bètahemolytische kok in ketens die o.a. keelontsteking, impetigo, erysipelas en roodvonk veroorzaakt.","definition":"<p><strong><em>Streptococcus pyogenes</em></strong> koloniseert keel en huid. Het M-eiwit beschermt tegen fagocytose; pyrogene exotoxinen veroorzaken roodvonk en het toxischeshocksyndroom. Invasieve infecties zijn o.a. cellulitis en necrotiserende fasciitis. Na een infectie kunnen immunologische complicaties optreden: acuut reuma en poststreptokokken-glomerulonefritis. Penicilline is eerste keus.</p>","image_url":"","wiki_title":"Streptococcus pyogenes","match":"groep a streptococci","option_only":true},"kweek op groep a-streptokokkeninfectie":{"title":"Streptococcus pyogenes (groep A-streptokok)","short":"Groep A-streptokok: grampositieve, bètahemolytische kok in ketens die o.a. keelontsteking, impetigo, erysipelas en roodvonk veroorzaakt.","definition":"<p><strong><em>Streptococcus pyogenes</em></strong> koloniseert keel en huid. Het M-eiwit beschermt tegen fagocytose; pyrogene exotoxinen veroorzaken roodvonk en het toxischeshocksyndroom. Invasieve infecties zijn o.a. cellulitis en necrotiserende fasciitis. Na een infectie kunnen immunologische complicaties optreden: acuut reuma en poststreptokokken-glomerulonefritis. Penicilline is eerste keus.</p>","image_url":"","wiki_title":"Streptococcus pyogenes","match":"kweek op groep a-streptokokkeninfectie","option_only":true},"stafylokok":{"title":"Staphylococcus aureus","short":"S. aureus is een grampositieve kok in trosjes, coagulasepositief, die huid- en wondinfecties, abcessen en ernstige systemische infecties veroorzaakt.","definition":"<p><strong><em>Staphylococcus aureus</em></strong> is een grampositieve kok die in trosjes groeit en <em>coagulase-positief</em> is (onderscheid met andere stafylokokken). Ongeveer een derde van de mensen draagt hem in de neus.</p><p>Hij veroorzaakt huid- en wekedeleninfecties (impetigo, furunkels, abcessen, wondinfecties), maar ook osteomyelitis, septische artritis, endocarditis en sepsis. Via toxines kan hij voedselvergiftiging en het toxischeshocksyndroom veroorzaken. MRSA is een methicillineresistente variant.</p>","image_url":"","wiki_title":"Staphylococcus aureus","match":"stafylokok","option_only":true},"appendicits":{"title":"Appendicitis","short":"Appendicitis is een ontsteking van de appendix, met buikpijn die vaak rond de navel begint en naar rechtsonder trekt.","definition":"<p>Bij <strong>appendicitis</strong> raakt het lumen van de appendix afgesloten (bijv. door een fecoliet of lymfoïde hyperplasie), waarna ontsteking en infectie volgen. Klachten: pijn eerst rond de navel, later rechtsonder (McBurney), misselijkheid, koorts en lokale peritoneale prikkeling. Zonder behandeling kan perforatie optreden. Diagnose met echo en/of CT; behandeling meestal appendectomie.</p>","image_url":"","wiki_title":"Appendicitis","match":"appendicits","option_only":true},"de sectio caesarea (keizersnede)":{"title":"Sectio caesarea (keizersnede)","short":"Bij een sectio caesarea wordt het kind via een snede in buikwand en baarmoeder geboren.","definition":"<p>Na een eerdere <strong>keizersnede</strong> is er bij een volgende vaginale bevalling een klein risico op een uterusruptuur en is er een verhoogd risico op placenta praevia en accreta. Complicaties van de ingreep zelf zijn bloeding, infectie en trombose.</p>","image_url":"","wiki_title":"Caesarean section","match":"de sectio caesarea (keizersnede)","option_only":true},"de vlokkentest":{"title":"Vlokkentest (CVS)","short":"Invasieve prenatale diagnostiek waarbij chorionvlokken worden afgenomen voor genetisch onderzoek.","definition":"<p>De <strong>vlokkentest</strong> (chorionic villus sampling) geeft vroeg (vanaf ~11 weken) zekerheid en is sneller uitvoerbaar dan de vruchtwaterpunctie.</p>","image_url":"","wiki_title":"Chorionic villus sampling","match":"de vlokkentest","option_only":true},"de nipt":{"title":"NIPT","short":"De NIPT onderzoekt DNA van de placenta in het bloed van de zwangere op trisomie 21, 18 en 13.","definition":"<p>De <strong>NIPT</strong> is zeer gevoelig en specifiek, maar blijft een screening: een afwijkende uitslag moet worden bevestigd met een vlokkentest of vruchtwaterpunctie. De test kan vanaf 10 weken.</p>","image_url":"","wiki_title":"Non-invasive prenatal testing","match":"de nipt","option_only":true},"geboren in stuitligging":{"title":"Stuitligging","short":"Bij een stuitligging ligt het kind met de billen of voeten naar beneden in plaats van met het hoofd.","definition":"<p>Rond 35–36 weken wordt bij een <strong>stuitligging</strong> een uitwendige versie aangeboden. Lukt dat niet, dan kan worden gekozen tussen een vaginale stuitbevalling en een geplande keizersnede. Een stuitligging is een risicofactor voor heupdysplasie; daarom volgt een echo van de heupen bij het kind.</p>","image_url":"","wiki_title":"Breech birth","match":"geboren in stuitligging","option_only":true},"amoxicilline met clavulaanzuur":{"title":"Amoxicilline-clavulaanzuur","short":"Amoxicilline-clavulaanzuur combineert een penicilline met een bètalactamaseremmer, waardoor ook bètalactamasevormende bacteriën worden gedekt.","definition":"<p>Clavulaanzuur heeft zelf nauwelijks antibacteriële werking maar remt veel <em>bètalactamasen</em>, zodat amoxicilline niet wordt afgebroken. De combinatie werkt daardoor ook tegen o.a. <em>S. aureus</em> (geen MRSA), <em>H. influenzae</em>, <em>Moraxella</em>, veel <em>E. coli</em> en anaeroben zoals <em>Bacteroides</em>. Bijwerkingen: diarree en (zelden) cholestatische hepatitis.</p>","image_url":"","wiki_title":"Amoxicillin/clavulanic acid","match":"amoxicilline met clavulaanzuur","option_only":true},"gastro-enteritis, mogelijk het norovirus":{"title":"Norovirus","short":"Norovirus is een zeer besmettelijk RNA-virus dat acute gastro-enteritis veroorzaakt met plotseling braken en diarree, vaak in uitbraken.","definition":"<p>Het <strong>norovirus</strong> is een niet-omhuld RNA-virus (calicivirus). Er zijn maar weinig deeltjes nodig voor infectie en het overleeft lang in de omgeving.</p><p>Het veroorzaakt acute gastro-enteritis met plotseling braken, waterige diarree en buikkrampen, die 1 à 3 dagen duurt. Uitbraken komen vooral voor in verpleeghuizen, ziekenhuizen en op cruiseschepen; handhygiëne is de belangrijkste maatregel.</p>","image_url":"","wiki_title":"Norovirus","match":"gastro-enteritis, mogelijk het norovirus","option_only":true},"arterosclerose":{"title":"Atherosclerose","short":"Atherosclerose is een chronisch ontstekingsproces in de vaatwand waarbij plaques met vet, ontstekingscellen en bindweefsel ontstaan.","definition":"<p>Bij <strong>atherosclerose</strong> dringt LDL de intima binnen en wordt het geoxideerd; monocyten worden macrofagen en schuimcellen (fatty streak). Gladde spiercellen migreren en vormen een fibreuze kap over een lipidenkern. Scheuren van een plaque met trombose veroorzaakt een acuut coronair syndroom of herseninfarct. Risicofactoren: roken, hypertensie, LDL, diabetes, leeftijd en familiaire belasting.</p>","image_url":"","wiki_title":"Atherosclerosis","match":"arterosclerose","option_only":true},"trombose":{"title":"Trombosebeen (diepveneuze trombose)","short":"Een trombosebeen is een stolsel in een diepe vene van het been, met een dik, pijnlijk, warm been.","definition":"<p>Bij een <strong>diepveneuze trombose</strong> ontstaat een stolsel in de diepe venen, meestal in de kuit of bovenbeen. Risicofactoren volgen de trias van Virchow: stase, hypercoagulabiliteit en vaatwandschade (bijv. operatie, immobilisatie, kanker, zwangerschap, oestrogenen). Diagnostiek met een beslisregel (Wells), D-dimeer en compressie-echografie. De belangrijkste complicatie is een longembolie; behandeling met antistolling.</p>","image_url":"","wiki_title":"Deep vein thrombosis","match":"trombose","option_only":true},"zenuwcellen":{"title":"Celtypen","short":"Het lichaam bestaat uit vier basisweefsels: epitheel, bindweefsel (inclusief bot en kraakbeen), spierweefsel en zenuwweefsel.","definition":"<p>Elk <strong>basisweefsel</strong> heeft eigen kenmerken: epitheel bedekt oppervlakken, spierweefsel kan samentrekken en zenuwweefsel geleidt prikkels.</p>","image_url":"","wiki_title":"","match":"zenuwcellen|bindweefselcellen|spiercellen|epitheelweefsel|botweefsel","option_only":true},"de combinatietest":{"title":"Prenatale screening","short":"De combinatietest combineerde een nekplooimeting met bloedonderzoek om het risico op trisomieën te schatten; hij is grotendeels vervangen door de NIPT.","definition":"<p>Sinds 2023 wordt in Nederland een <strong>13-wekenecho</strong> aangeboden om vroeg lichamelijke afwijkingen op te sporen, naast de 20-wekenecho. Diagnostisch onderzoek gebeurt met een vlokkentest of vruchtwaterpunctie.</p>","image_url":"","wiki_title":"","match":"de combinatietest|combinatietest|een 13 weken echo|13-wekenecho|20-wekenecho","option_only":true},"een amnionpunctie":{"title":"Vruchtwaterpunctie","short":"Bij een vruchtwaterpunctie wordt vanaf ongeveer 15–16 weken vruchtwater afgenomen voor chromosoom- of DNA-onderzoek van het kind.","definition":"<p>Het risico op een miskraam door een <strong>vruchtwaterpunctie</strong> is klein. Omdat de cellen van het kind zelf komen, speelt placentamozaïcisme geen rol.</p>","image_url":"","wiki_title":"Amniocentesis","match":"een amnionpunctie|amnionpunctie|vruchtwaterpunctie|amniocentese","option_only":true},"foetale cytomegalie infectie":{"title":"Congenitale CMV-infectie","short":"Een congenitale CMV-infectie is de meest voorkomende aangeboren infectie en kan gehoorverlies en een ontwikkelingsachterstand geven.","definition":"<p>Bij de geboorte zijn de meeste kinderen zonder klachten; anderen hebben groeivertraging, microcefalie, verkalkingen in de hersenen, petechieën en hepatosplenomegalie. Gehoorverlies kan ook later ontstaan. Goede handhygiëne rond jonge kinderen verkleint het risico.</p>","image_url":"","wiki_title":"Congenital cytomegalovirus infection","match":"foetale cytomegalie infectie|congenitale cmv|cytomegalovirus","option_only":true},"navelstrengcompressie":{"title":"Oorzaken van deceleraties","short":"Deceleraties in de foetale hartslag kunnen ontstaan door compressie van het hoofd (vagale reactie), van de navelstreng of door placentaire insufficiëntie.","definition":"<p><strong>Navelstrengcompressie</strong> geeft variabele deceleraties, wisselend van vorm en timing. Hoofdcompressie geeft vroege deceleraties die samenvallen met de wee.</p>","image_url":"","wiki_title":"","match":"navelstrengcompressie|hoofdcompressie|oogbolcompressie","option_only":true},"aanbieden van pijnstilling middels remifentanyl":{"title":"Pijnstilling tijdens de bevalling","short":"Pijnstilling tijdens de bevalling kan met een epidurale analgesie (ruggenprik) of met remifentanil via een pompje dat de vrouw zelf bedient.","definition":"<p><strong>Remifentanil</strong> is een zeer kortwerkend opioïd; bijwerkingen zijn ademhalingsdepressie en sufheid, dus bewaking van de saturatie is nodig. Epidurale analgesie geeft betere pijnstilling, maar kan de uitdrijving verlengen.</p>","image_url":"","wiki_title":"","match":"aanbieden van pijnstilling middels remifentanyl|remifentanil|epidurale analgesie|ruggenprik bij bevalling","option_only":true},"diabetes mellitus van de moeder":{"title":"Diabetes in de zwangerschap","short":"Diabetes bij de moeder (vooraf bestaand of zwangerschapsdiabetes) verhoogt het risico op een groot kind, schouderdystocie, aangeboren afwijkingen en neonatale hypoglykemie.","definition":"<p>Bij vooraf bestaande diabetes is een goede glucoseregulatie vóór de conceptie belangrijk om aangeboren afwijkingen te voorkomen. <strong>Zwangerschapsdiabetes</strong> wordt behandeld met dieet en zo nodig insuline of metformine.</p>","image_url":"","wiki_title":"Gestational diabetes","match":"diabetes mellitus van de moeder|zwangerschapsdiabetes|diabetes gravidarum","option_only":true},"oöcyt":{"title":"Cellen van de follikel","short":"Een follikel bestaat uit een oöcyt, omringd door granulosacellen en daaromheen de thecacellen.","definition":"<p>De <strong>oöcyt</strong> blijft tot vlak voor de ovulatie in de profase van de eerste meiose. De granulosacellen maken oestrogeen en voeden de eicel via gap junctions.</p>","image_url":"","wiki_title":"Ovarian follicle","match":"oöcyt|folliculaire cel|folliculaire fibroblast|granulosacellen","option_only":true}};
